BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ddaf684c-b3d1-5fbd-af81-77234910d44b','Cultural retention','A translation strategy in which a source-culture reference is kept unchanged in the target version, preserving its foreign form rather than adapting or explaining it. It maintains the source culture''s presence and flavor, at the cost of possible unfamiliarity for the target audience.','This keeps a foreign reference exactly as it is. A place or brand name stays the same in the dub. It keeps the original flavor, even if some viewers do not know it.','It preserves the authenticity and setting of the source culture, signaling that the story belongs to another place rather than smoothing it into the target culture.','An adapter leaves a well-known foreign place or brand name untouched so the dub keeps its original sense of place.','Cultural Adaptation',ARRAY['Cultural explicitation','Cultural neutralization','Cultural compensation','Foreignization','Extralinguistic cultural reference','Adaptation']::text[],ARRAY['Retaining a reference the audience cannot possibly understand, hurting clarity.','Confusing retention with direct translation, which changes the language but not the reference.','Keeping every reference untouched and making the dub hard to follow.']::text[],ARRAY['Keeping a famous foreign landmark''s name unchanged in a dub.','Preserving a signature brand name central to a character''s identity.','Retaining culturally iconic terms to maintain the story''s setting.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ddaf684c-b3d1-5fbd-af81-77234910d44b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural retention'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ddaf684c-b3d1-5fbd-af81-77234910d44b','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ddaf684c-b3d1-5fbd-af81-77234910d44b' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cb9c7fd1-7b44-5b1f-bcf7-aefcb1b861b6','Cultural substitution','A translation strategy that swaps a source reference for a familiar target-culture counterpart, accepting a change in the literal meaning in order to reproduce, for the new audience, roughly the same effect the original carried.','Cultural substitution means swapping a local reference for one the new audience knows. The exact meaning changes, but the effect stays the same. It is like changing a joke so it still makes people laugh.','It preserves the communicative effect, humor, or connotation of a reference that would be confusing or meaningless if translated literally, keeping the localized version natural and relatable.','A dubbing adapter uses it to replace a local food, celebrity, or idiom with a familiar target-culture equivalent so the new audience reacts as the original viewers did.','Translation Strategy',ARRAY['Cultural transplantation','Cultural adaptation','Dynamic equivalence','Transcreation','Localization']::text[],ARRAY['Confusing cultural substitution with literal translation; substitution deliberately changes the reference to keep the effect.','Substituting a reference that carries the wrong connotation or is anachronistic for the setting, breaking immersion.','Over-substituting so heavily that the source setting is erased even when the story depends on it.']::text[],ARRAY['Dubbing a sitcom where a country-specific snack brand is replaced with one the target audience recognizes.','Localizing a joke built on a local TV show by swapping in an equivalent show the new audience knows.','Adapting an idiom with no direct equivalent into a target-language saying that carries the same meaning.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cb9c7fd1-7b44-5b1f-bcf7-aefcb1b861b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural substitution'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cb9c7fd1-7b44-5b1f-bcf7-aefcb1b861b6','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cb9c7fd1-7b44-5b1f-bcf7-aefcb1b861b6' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a1c98101-4b86-5819-8739-112c3560e335','Cultural transplantation','An extreme domesticating translation strategy in which the whole source setting — names, places, institutions, and cultural references — is wholesale relocated into the target culture, so the text reads as if it had originated there.','This is the boldest way to make a foreign story feel local. You move the whole setting into the new culture. Names, places, and customs all become ones the new audience knows.','It maximizes familiarity and accessibility by removing all foreign markers, used when a fully localized feel matters more than preserving the source culture''s identity.','An adapter may transplant a foreign show''s characters, place names, and customs into the target country, a choice sometimes seen in children''s animation and comedy localization.','Translation Strategy',ARRAY['Cultural substitution','Cultural adaptation','Dynamic equivalence','Localization','Dubbing script adaptation']::text[],ARRAY['Treating transplantation as a default; it is the extreme end of domestication and can misrepresent a story tied to its original setting.','Confusing it with cultural substitution, which changes single references rather than relocating the whole setting.','Leaving visual cues such as signs, flags, or landmarks that contradict the transplanted setting, so picture and dialogue clash.']::text[],ARRAY['Localizing a children''s animated series so characters have target-language names and live in a recognizably local town.','Adapting a comedy sketch show so all references, places, and institutions belong to the target country.','Reworking a foreign format completely into the host country''s cultural frame.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a1c98101-4b86-5819-8739-112c3560e335' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural transplantation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a1c98101-4b86-5819-8739-112c3560e335','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a1c98101-4b86-5819-8739-112c3560e335' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6b93bc20-c18e-5fc1-b8e3-d5a5d6a5444d','Detection','In dubbing, the technical phase in which a detector transcribes the source-language dialogue in exact synchrony with the picture and marks lip movements (labials and semi-labials), mouth openings and closures, pauses, breaths, reactions, on- and off-screen status, character cues, and take (loop) boundaries, producing the annotated basis for adaptation and recording.','Detection is careful prep work done before a film is dubbed. A specialist writes down the original lines. They mark every mouth movement, pause, and breath, matched to the picture.','It gives the adapter a precise timing and lip-shape map so the rewritten target dialogue can be made to fit the actors'' mouths and the rhythm of each scene.','Studios in the French and wider European dubbing tradition commission detection first; the detector''s marks on the rhythmo band tell the adapter exactly where labials and pauses fall.','Dubbing Process',ARRAY['Detection script','Dialogue detection','Rhythmo band','Dubbing script adaptation','Lip sync','Dubbing director']::text[],ARRAY['Thinking detection is translation; it is language-neutral technical annotation done before any target dialogue is written.','Ignoring off-screen and reaction marks, so the adapter forces lip-sync where none is needed or misses breaths and efforts.','Rushing detection so labial positions are mistimed, causing sync errors that are expensive to fix at the recording stage.']::text[],ARRAY['A dubbing studio preparing a feature film''s rhythmo band before adapters write the target script.','A detector marking bilabial consonants so the adapter knows where the target line must show closed lips.','Segmenting a program into takes (loops) so recording sessions can be organized efficiently.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6b93bc20-c18e-5fc1-b8e3-d5a5d6a5444d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detection'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6b93bc20-c18e-5fc1-b8e3-d5a5d6a5444d','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6b93bc20-c18e-5fc1-b8e3-d5a5d6a5444d' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b68c90b8-c754-5336-bcd5-3f8333e3513e','Detection script','The annotated document produced by detection: the source dialogue laid out in synchrony with the image and marked up with lip movements, pauses, breaths, reactions, on- and off-screen indicators, character cues, and take (loop) divisions, used by the adapter as the working basis for writing synchronized target-language dialogue.','This is the marked-up script that comes out of the detection stage. It shows the original lines lined up with the picture. It also notes mouth shapes, pauses, and who is on screen.','It serves as the blueprint for adaptation, carrying all the timing and synchronization information the adapter and, later, the voice actors and director need.','An adapter reads the detection script to see where a target line must contain a closed-mouth consonant or fit a fixed pause, then rewrites the dialogue to match.','Dubbing Process',ARRAY['Detection','Dialogue detection','Rhythmo band','Dubbing script adaptation','Dubbing adapter']::text[],ARRAY['Confusing the detection script with the finished dubbing script; it holds source-language annotation, not the target dialogue.','Overwriting or losing the detector''s marks while adapting, which strips out sync information the recording stage relies on.','Treating character and loop cues as optional, when they organize the recording sessions and attribute lines correctly.']::text[],ARRAY['An adapter working from the detection script to write lip-synced target dialogue.','A recording studio using loop divisions in the detection script to schedule sessions.','Checking a labial mark in the script to place a closed-mouth sound in the target line.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b68c90b8-c754-5336-bcd5-3f8333e3513e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detection script'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b68c90b8-c754-5336-bcd5-3f8333e3513e','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b68c90b8-c754-5336-bcd5-3f8333e3513e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9f7af6d6-a464-5867-9bd5-8ad4ea706db8','Dialect leveling','In sociolinguistics, the reduction or attrition of marked or minority variants among dialects in contact, whereby differences between regional varieties diminish and speakers converge toward a more uniform, often supra-regional, variety; in localization the term also describes toning down strongly marked source speech toward a broader variety.','Dialect leveling is when regional ways of speaking slowly blend together. As people from different areas mix, odd local features fade. Speech across regions becomes more alike.','As a concept it explains how dialect differences shrink through mobility and contact; in dubbing and subtitling it describes reducing marked speech so a wider audience is not distracted or excluded.','A localization team may level a heavily regional source accent toward a more neutral variety so the target audience can follow the dialogue easily.','Linguistic Variation',ARRAY['Dialect neutralization','Dialect relocation','Cultural adaptation','Localization','Dubbing script adaptation']::text[],ARRAY['Confusing levelling (marked features converging or fading) with a one-off neutralization made as a single translation choice.','Assuming levelling always means switching to the standard language, when it can converge on a regional norm instead.','Levelling out an accent that carries meaning for a character, erasing information the audience needs.']::text[],ARRAY['Describing how younger speakers in a mixed new town lose older local pronunciations.','A localization team reducing a strong source dialect toward neutral speech for a broad release.','Analyzing why regional features weaken in media aimed at national audiences.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9f7af6d6-a464-5867-9bd5-8ad4ea706db8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialect leveling'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9f7af6d6-a464-5867-9bd5-8ad4ea706db8','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9f7af6d6-a464-5867-9bd5-8ad4ea706db8' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'db5183c1-545f-57c1-a786-e82f0a3b5d25','Dialect neutralization','A translation and localization strategy in which the marked features of a source-text dialect — phonological, lexical, and syntactic — are systematically removed and the speech is rendered in a standard or unmarked target variety.','This means stripping the special features out of an accent or dialect. The dubbed or subtitled version is written in plain, standard language. The regional flavor is removed on purpose.','It maximizes clarity and reach and avoids the risks of choosing a particular target dialect, at the cost of losing the character or regional identity the source dialect signaled.','Subtitlers and adapters often neutralize a strong regional dialect into standard language when no target dialect fits well or when clarity is the priority.','Linguistic Variation',ARRAY['Dialect leveling','Dialect relocation','Cultural adaptation','Dynamic equivalence','Localization','Accent neutralization']::text[],ARRAY['Neutralizing by default and flattening every character''s voice, losing distinctions the story relies on.','Confusing neutralization (removing dialect markers) with relocation (swapping in a target dialect).','Neutralizing dialogue whose whole joke or conflict depends on the dialect, leaving the scene meaningless.']::text[],ARRAY['Subtitling a strongly dialectal film into standard target-language text.','Dubbing a regional character in neutral speech because no target accent fits.','Standardizing code-switching and slang for a broad international release.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='db5183c1-545f-57c1-a786-e82f0a3b5d25' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialect neutralization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'db5183c1-545f-57c1-a786-e82f0a3b5d25','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='db5183c1-545f-57c1-a786-e82f0a3b5d25' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72a85d2d-76b1-5384-b8b0-68ecf4faab2f','Dialect relocation','A translation and localization strategy in which a marked source-text dialect is rendered using a specific dialect or accent of the target language, relocating the geographic or social variety into the target culture rather than removing it.','This swaps a source accent for a real accent in the new language. A rural source voice might become a rural target accent. The character still sounds regional, just in a new place.','It keeps the fact that a character speaks a marked variety — preserving humor, contrast, or social meaning — instead of neutralizing it, though the chosen target dialect brings its own associations.','A dubbing team may voice a rustic or working-class source character with a recognizable regional target accent to signal the same social position.','Linguistic Variation',ARRAY['Dialect neutralization','Dialect leveling','Cultural substitution','Cultural transplantation','Localization']::text[],ARRAY['Choosing a target dialect that carries stereotypes or social baggage the source never implied.','Confusing relocation (dialect for dialect) with neutralization (removing the dialect entirely).','Relocating to a target accent whose real geography clashes with the on-screen visual setting.']::text[],ARRAY['Dubbing an animated film''s country characters with a well-known target-language regional accent.','Rendering a source working-class sociolect with a comparable target sociolect.','Localizing comedy where a character''s rural accent drives the humor.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72a85d2d-76b1-5384-b8b0-68ecf4faab2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialect relocation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '72a85d2d-76b1-5384-b8b0-68ecf4faab2f','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72a85d2d-76b1-5384-b8b0-68ecf4faab2f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '29ee8f3c-a5cc-545c-8bd5-b11a6885f2ab','Dialogue detection','The detection work focused specifically on spoken dialogue: transcribing and timing each line of source dialogue in synchrony with the picture and annotating it (speaker, on- and off-screen status, lip movements, pauses) to produce the timed, character-attributed dialogue that translation, adaptation, and recording work from.','This is the part of dubbing prep that focuses on the spoken lines. Each line is written out and timed to the picture. Notes show who speaks and how their mouth moves.','It produces the timed, annotated dialogue that translators and adapters build on, and that tools use to align target lines to the original speech.','A prep team detects the dialogue — marking start and end times and speakers — so the target script can be written to match each line''s length and timing.','Dubbing Process',ARRAY['Detection','Detection script','Rhythmo band','Dubbing script adaptation','Dubbing director']::text[],ARRAY['Treating dialogue detection as final translation rather than timed source-language annotation.','Mis-attributing overlapping or off-screen lines to the wrong speaker, corrupting the recording script.','Timing to the subtitle rather than the actual mouth movement, causing sync problems in the dub.']::text[],ARRAY['Transcribing and time-coding a program''s dialogue before translation begins.','Attributing each line to a character so the recording script is correctly cast.','Marking off-screen lines so the adapter knows where lip-sync is not required.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='29ee8f3c-a5cc-545c-8bd5-b11a6885f2ab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue detection'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '29ee8f3c-a5cc-545c-8bd5-b11a6885f2ab','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='29ee8f3c-a5cc-545c-8bd5-b11a6885f2ab' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '03912b59-8d7c-5245-8829-c7a43f13bc0c','Dialogue director','The person who directs the voice talent during a dubbing or ADR session — also called the dubbing or voice director — guiding performance, timing, and synchronization so the recorded target-language dialogue matches the on-screen acting and the original intent; the role often also covers casting and script/adaptation decisions.','The dialogue director leads the voice actors in the recording booth. They coach each performance and call for retakes. They make sure the new lines match the acting and lip movements.','The role safeguards performance quality and synchronization, carrying the original actor''s intent into the target-language recording and keeping consistency across a cast and across episodes.','During a session the dialogue director sits with the engineer, cues each take (loop), and asks for retakes until timing, emotion, and lip-sync are right.','Dubbing Roles',ARRAY['Dubbing adapter','Dubbing script adaptation','Lip sync','ADR','Detection']::text[],ARRAY['Leaving voice direction to the recording engineer or studio staff instead of a qualified director.','Confusing the dialogue director with the original film''s director; the dialogue director works only on the localized version.','Chasing perfect lip-sync over the original intent and natural performance, producing stiff dialogue.']::text[],ARRAY['Directing a cast through a dubbing session for a streaming series.','Running an ADR session where an actor re-records lines in the same language.','Guiding casting so target-language voices match the original characters.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='03912b59-8d7c-5245-8829-c7a43f13bc0c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue director'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '03912b59-8d7c-5245-8829-c7a43f13bc0c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='03912b59-8d7c-5245-8829-c7a43f13bc0c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '61d5d659-7845-560f-847f-829ce990f307','Dialogue-bearing effect','A sound effect or background element that carries intelligible spoken or vocal language content — such as a crowd chant, a radio or public-address announcement, or loop-group walla with discernible words — and therefore behaves like dialogue for localization, so it must be handled separately from a clean music-and-effects (M&E) track.','This is a sound effect that actually contains words. A crowd chant or a background announcement carries real language. So it must be treated like dialogue when a show is dubbed.','Flagging these elements keeps language content out of the international M&E mix so it can be re-recorded, translated, or retained as the localization requires.','A mixer places a crowd chant with recognizable words on an optional or language-specific track, not the clean M&E, so the dubbing team can decide whether to recreate it.','Localization Prep',ARRAY['Music and effects','Dub dialogue stem','Embedded dialogue','Walla','Loop group']::text[],ARRAY['Baking a dialogue-bearing effect into the M&E track, which leaves untranslatable foreign words in the dubbed version.','Assuming all crowd or background sound is language-free, when some walla and chants carry meaning.','Failing to flag on-screen vocal effects, so the localization team cannot decide whether to recreate them.']::text[],ARRAY['A stadium crowd chanting a slogan that viewers must understand.','A background radio or television broadcast whose words advance the plot.','Loop-group walla containing intelligible phrases in a busy scene.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='61d5d659-7845-560f-847f-829ce990f307' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue-bearing effect'),'[^a-z0-9]','','g'));
