INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2b084200-be50-5a64-aec9-3ef7d778e9bc','Dub QC','The quality-control process applied to a completed dubbed audio deliverable, in which linguistic and technical aspects — translation and adaptation accuracy, synchronization, performance, audio artifacts, mix balance, and conformance to loudness and delivery specifications — are checked against the original and the platform''s requirements before the dub is accepted.','Dub QC, or quality control, is the final check on a finished dub. Reviewers make sure the new dialogue is accurate and in sync. They also check that it is clean and mixed to spec.','It catches errors before release, protecting the viewing experience and the creative intent and ensuring the dub meets the contractual technical and editorial standards.','A QC operator screens the dubbed version against the original, logging sync slips, mistranslations, missed lines, clicks and pops, and loudness issues for the studio to fix.','Quality Control',ARRAY['Dub dialogue stem','Dubbing mix','Lip sync','Loudness normalization','Music and effects']::text[],ARRAY['Treating the platform''s internal QC as a replacement for the partner studio''s own QC pass.','Checking only translation and ignoring technical faults like sync drift, clipping, or wrong loudness.','UNSAFE: Running long QC listening sessions at high monitoring levels, risking noise-induced hearing loss; keep levels moderate, take breaks, and observe occupational noise-exposure limits.']::text[],ARRAY['Reviewing a dubbed episode before it is published on a streaming platform.','Logging a lip-sync drift and a mistranslated line for the studio to re-record.','Verifying the dubbed mix meets the platform''s loudness target and channel-format specs.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2b084200-be50-5a64-aec9-3ef7d778e9bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dub QC'),'[^a-z0-9]','','g'));
