INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ea7ec04-43cf-5474-a8c9-016d482baa5a','Dub dialogue stem','The isolated dialogue stem of a dubbed (localized) version — the discrete premixed track containing only the target-language dialogue, kept separate from the music-and-effects (M&E) so it can be balanced, archived, quality-controlled, and remixed independently of the other elements.','A stem is one grouped layer of a finished mix. The dub dialogue stem holds only the dubbed voices. It stays apart from music and effects, so it can be changed on its own.','Separating the dubbed dialogue as its own stem lets mixers balance it against the M&E, meet delivery specs, and re-use or fix the voices without touching music and effects.','A re-recording mixer combines the target-language dub dialogue stem with the M&E to build the final localized mix, and delivers the stem for archive and QC.','Audio Stem',ARRAY['Music and effects','Dialogue-bearing effect','Dubbing mix','Dub QC','Embedded dialogue']::text[],ARRAY['Confusing the dub dialogue stem with the full mix; the stem is dialogue only, not the finished soundtrack.','Delivering a dialogue stem with music or effects bleeding into it, breaking the M&E separation.','Assuming one stem fits all formats, when deliverables may need mono, 5.1, or immersive versions.']::text[],ARRAY['Delivering separated stems so a platform can remix a dub to different channel formats.','Archiving the dubbed dialogue separately for future re-versioning.','Balancing the dub dialogue stem against the M&E during the final localized mix.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ea7ec04-43cf-5474-a8c9-016d482baa5a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dub dialogue stem'),'[^a-z0-9]','','g'));
