INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6839e766-170e-52e7-a8f0-f2a64a984c19','Dub-stage foldback','On a dubbing (re-recording) or ADR stage, the monitored audio feed sent to a performer during recording — typically the original guide dialogue, cue beeps or streamers, and existing sound elements — routed to headphones or stage loudspeakers so the voice actor can hear the timing and pitch references needed to synchronize a replacement or dubbed line to picture.','Foldback is the sound played to a voice actor while they record. It usually holds the original line and timing cues. It works like a singer''s headphone mix, helping them match the picture.','It gives the performer the timing, pacing, and pitch references needed to deliver a replacement or dubbed line in sync with the picture and the original performance.','The mixer sends the guide track and cue beeps to the actor''s headphones on the dub stage, setting the foldback balance so the actor hears the line without it bleeding onto the recorded take.','Monitoring',ARRAY['ADR','Guide track','Cue beeps','Re-recording mixer','Lip sync']::text[],ARRAY['Setting foldback so loud that the original guide dialogue bleeds into the actor''s microphone and onto the recorded take.','Giving the actor only the original line without timing cues, so they guess at sync.','UNSAFE: Driving headphone foldback to very high levels, risking hearing damage over a long recording session.']::text[],ARRAY['Recording ADR where the actor hears the original line and beeps to match sync.','Dubbing a foreign-language line while monitoring the original delivery.','Feeding a guide mix to a voice actor''s headphones on the dub stage.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6839e766-170e-52e7-a8f0-f2a64a984c19' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dub-stage foldback'),'[^a-z0-9]','','g'));
