WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6839e766-170e-52e7-a8f0-f2a64a984c19' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '01407325-78bb-58fc-b053-02488b595b94','Dub-stage integration','On the dubbing (re-recording) stage, the process of blending replacement, ADR, or dubbed dialogue with the production sound, music, and effects so that it matches the scene''s acoustic space, perspective, level, and tone and plays as one seamless soundtrack rather than as separately recorded elements.','Integration means making re-recorded or dubbed lines fit the rest of the scene. The mixer matches the room sound, distance, and volume. The goal is that no one can tell the line was added later.','It hides the difference between studio-recorded replacement lines and the original location sound, preserving the illusion that all the audio was captured in the same space at the same time.','The re-recording mixer adds reverb, equalization, and level and panning matching so an ADR or dubbed line sits naturally alongside the boom and the music-and-effects stem.','Re-recording',ARRAY['ADR','Reverberation','Perspective','Music and effects','Re-recording mixer']::text[],ARRAY['Dropping a dry studio ADR line into a reverberant scene without matching the room, so it sounds pasted on.','Matching level but ignoring microphone perspective, so a close dubbed line does not match a wide shot.','Forgetting to match background tone, leaving an audible gap where the added line replaces production sound.']::text[],ARRAY['Blending an ADR line into a noisy exterior scene.','Matching a dubbed foreign line to the original room acoustics.','Seating a replacement line so it matches the boom mic''s perspective.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='01407325-78bb-58fc-b053-02488b595b94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dub-stage integration'),'[^a-z0-9]','','g'));
