SELECT '2664ccbc-64f3-5f01-aacb-a3fe6d55ef0c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2664ccbc-64f3-5f01-aacb-a3fe6d55ef0c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05d31a98-f599-53bc-90b2-619cbefb426e','Dubbing mix','The final mix in which the recorded target-language (dubbed) dialogue is balanced and combined with the original music-and-effects (M&E) stem to produce the localized version''s soundtrack. It mirrors the level balance, panning, and processing of the original-language mix so the dubbed version matches the creative intent of the source.','A dubbing mix blends the new voice recordings with the original music and sound effects. The mixer matches the balance of the first version. The result is a full soundtrack in the new language.','It produces a complete soundtrack in the target language by fitting the dubbed voices into the original music and effects, so the localized version sounds and feels like the original.','The mixer imports the M&E stem and the edited dubbed dialogue, balances levels and panning to match the original mix, and delivers the combined localized soundtrack to the required loudness spec.','Final Mix',ARRAY['Music and effects','Dubbing premix','Re-recording mixer','Loudness normalization','Dialogue guide']::text[],ARRAY['Mixing the dubbed dialogue to a different balance than the original, so the localized version feels unlike the source.','Ignoring the delivery loudness specification, so the dubbed mix fails quality control.','Letting dubbed dialogue clash with reactions already present in the M&E instead of complementing them.']::text[],ARRAY['Combining a Spanish dub with the original M&E for a streaming release.','Matching the dubbed mix balance to the original English mix.','Delivering a localized 5.1 mix at the platform''s loudness target.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05d31a98-f599-53bc-90b2-619cbefb426e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing mix'),'[^a-z0-9]','','g'));
