WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='05d31a98-f599-53bc-90b2-619cbefb426e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f6aa4705-3cf9-5942-89dc-6f0628cbf503','Dubbing rhythm','In dubbing synchronization, the temporal pacing dimension of a delivered line — its cadence, stress pattern, pauses, and speech rate — which the target-language dialogue and the dubbing actor must match to the original performance so the dubbed speech aligns with the character''s timing, breathing, and articulation. It is closely tied to isochrony, the equal-duration matching of source and target utterances.','Dubbing rhythm is the timing and beat of the spoken lines. The new voice must speak with the same pace and pauses as the original. It is like matching the rhythm of a song when you sing new words to it.','Matching rhythm keeps the dubbed dialogue believable: the voice starts, pauses, and stops when the character does, reinforcing the illusion that the actor on screen is speaking the target language.','The adapter shapes line length and stress to the original''s cadence, and the dubbing actor times pauses and speech rate to the picture, often guided by a rhythmo band or cue marks.','Synchronization',ARRAY['Isochrony','Lip sync','Kinesic synchrony','Rhythmo band','Dubbing script adaptation']::text[],ARRAY['Matching the words and lip shapes but rushing or dragging the pace, so the delivery feels out of step.','Ignoring the original''s pauses and breaths, making the dubbed line run continuously where the character paused.','Treating rhythm as less important than lip sync, when both are needed for believable dubbing.']::text[],ARRAY['Timing a dubbed line''s pauses to match the actor''s breathing on screen.','Fitting target-language stress to the original''s cadence during adaptation.','Coaching a dubbing actor to match the pace of a fast exchange.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f6aa4705-3cf9-5942-89dc-6f0628cbf503' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing rhythm'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f6aa4705-3cf9-5942-89dc-6f0628cbf503','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f6aa4705-3cf9-5942-89dc-6f0628cbf503' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6a7d10d8-1181-5d1a-9f3f-89d213d91f4c','Dubbing script adaptation','The stage in the dubbing workflow in which a raw translation of the source dialogue is reworked into a performable target-language script that satisfies dubbing''s synchronization constraints — isochrony (matching duration), lip and phonetic synchrony (matching visible articulation, especially labials in close-ups), and kinesic synchrony (matching gestures) — while preserving meaning, register, humor, and characterization.','Script adaptation reshapes the translated lines so they can be dubbed. The writer changes wording to fit the timing and lip movements on screen. The meaning stays the same, but the words are rebuilt to match the picture.','It bridges translation and performance: a faithful translation is not automatically speakable in sync, so adaptation makes the dialogue both accurate and able to match mouths, timing, and gestures.','An adapter watches the picture, rewrites each translated line to fit its on-screen duration and lip movements, and inserts sync symbols and notes for the dubbing director and actors.','Dubbing Process',ARRAY['Dubbing adapter','Isochrony','Lip sync','Kinesic synchrony','Dynamic equivalence']::text[],ARRAY['Translating literally and assuming the lines will fit, when they must be reshaped for sync.','Fixing lip sync so aggressively that meaning, tone, or jokes are lost.','Overrunning the original line''s length, so the dubbed dialogue cannot fit the on-screen timing.']::text[],ARRAY['Adapting a translated sitcom so jokes land within the original timing.','Reworking a line so a close-up''s lip closures fall on matching sounds.','Preparing a sync-ready dubbing script from a rough translation.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6a7d10d8-1181-5d1a-9f3f-89d213d91f4c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing script adaptation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6a7d10d8-1181-5d1a-9f3f-89d213d91f4c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6a7d10d8-1181-5d1a-9f3f-89d213d91f4c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '56cb3bee-c592-5dbe-9381-c93a52ce5956','Dynamic equivalence','A translation principle, formulated by Eugene Nida, that aims for the closest natural equivalent of the source message such that the relationship between the target audience and the translated text is substantially the same as that between the original audience and the source text — prioritizing equivalent effect and naturalness of expression over word-for-word formal correspondence. In audiovisual translation it underpins adapting dialogue so the dubbed or subtitled version produces the same response as the original.','Dynamic equivalence means translating for the same effect, not the same words. The goal is that the new audience reacts the way the first audience did. So a joke is replaced by a joke that works, not a literal copy.','It exists to make a translation feel natural and land with the intended impact on a new audience, rather than reading as a stiff, literal version that loses humor, tone, or meaning.','A dubbing adapter uses dynamic equivalence when replacing an idiom, pun, or cultural reference with a target-culture equivalent that lands the same way, instead of translating it literally.','Translation Theory',ARRAY['Formal equivalence','Dubbing script adaptation','Localization','Transcreation','Cultural adaptation','Functional equivalence (Nida''s later term for essentially the same idea as dynamic equivalence)']::text[],ARRAY['Confusing dynamic equivalence with loose or inaccurate translation; it must still convey the source meaning faithfully.','Assuming a literal, word-for-word translation is always the most faithful, when it can distort the intended effect.','Applying it so freely that the translation drifts away from the source content.']::text[],ARRAY['Replacing an untranslatable pun with a target-language joke in a dub.','Adapting a cultural reference so a foreign audience understands it.','Choosing natural phrasing over literal wording in a localized script.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='56cb3bee-c592-5dbe-9381-c93a52ce5956' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic equivalence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '56cb3bee-c592-5dbe-9381-c93a52ce5956','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='56cb3bee-c592-5dbe-9381-c93a52ce5956' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e7368bf-d615-54d8-adb2-d50acf802e8a','Effort vocal','A non-verbal vocal exertion or reaction sound — a grunt, breath, gasp, groan, or exertion sound — produced by a performer rather than spoken as words. In dubbing and ADR these ''efforts'' are treated as a distinct dialogue element and are frequently re-recorded to match a replacement or target-language voice, because they carry with the dialogue rather than the music-and-effects stem.','An effort is a non-word sound a person makes, like a grunt, breath, or gasp. In dubbing, actors often record these separately. That way the new voice''s grunts match the new voice, not the old one.','Recording efforts separately lets the dubbed or replaced voice keep believable, matching breaths and reactions, since these sounds travel with the dialogue and are usually stripped from the music-and-effects stem.','During an ADR or dubbing session the actor watches the picture and performs breaths, grunts, and reactions in sync, which the editor then places under the action.','Vocal Elements',ARRAY['Efforts pass','ADR','Walla','Music and effects','Loop group']::text[],ARRAY['Leaving the original actor''s efforts in a dubbed track, so grunts and breaths do not match the new voice.','Assuming all efforts live in the M&E; language-linked or character-specific efforts often must be re-recorded.','Recording efforts out of sync with the on-screen action, so breaths and grunts drift off picture.']::text[],ARRAY['Recording an actor''s fight grunts to match a dubbed voice.','Adding breaths under a replaced line so it sounds natural.','Replacing efforts that were stripped from the M&E stem along with the source-language dialogue.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e7368bf-d615-54d8-adb2-d50acf802e8a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Effort vocal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0e7368bf-d615-54d8-adb2-d50acf802e8a','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0e7368bf-d615-54d8-adb2-d50acf802e8a' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '419fb32f-8f0e-55ce-bbd9-c78144ea9b1c','Efforts pass','A dedicated recording pass or session in ADR/dubbing devoted solely to capturing a performer''s non-verbal vocal efforts — breaths, grunts, gasps, exertions, and reactions — separately from lexical dialogue, so they can be edited and placed to match the picture and the replacement or target-language voice.','An efforts pass is a recording run just for non-word sounds. The actor performs breaths, grunts, and reactions while watching the scene. Doing them in one focused pass keeps them clean and easy to place.','It isolates efforts from dialogue so the editor gets clean, well-synced grunts and breaths to lay under the action, matching the dubbed or replaced performance.','After recording the spoken lines, the director runs a separate efforts pass in which the actor performs only the exertions and reactions for the scene.','Recording Session',ARRAY['Effort vocal','ADR','Loop group','Walla','Music and effects']::text[],ARRAY['Skipping the efforts pass and hoping the M&E efforts will match the dubbed voice, which they often do not.','Recording efforts and dialogue together, making it hard to balance and place the efforts cleanly.','Performing efforts without watching the picture, so they land out of sync.']::text[],ARRAY['Capturing a stunt scene''s grunts after the dialogue is recorded.','Running an efforts pass so a dubbed character''s breaths match the new voice.','Recording reactions for a crowd scene separately from lines.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='419fb32f-8f0e-55ce-bbd9-c78144ea9b1c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Efforts pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '419fb32f-8f0e-55ce-bbd9-c78144ea9b1c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='419fb32f-8f0e-55ce-bbd9-c78144ea9b1c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26b3b46c-2feb-5f91-b8b6-ce90a6d3bcd7','Embedded dialogue','Dialogue that is inseparably mixed into another audio element — such as the music-and-effects stem, source music with lyrics, or background and crowd sound — so that it cannot be cleanly isolated or removed. In localization this is problematic because embedded dialogue cannot simply be replaced with a dubbed line and must be worked around, re-created, or left in the original language.','Embedded dialogue is speech baked into other sounds, so it cannot be pulled out on its own. Because you cannot separate it, you cannot easily dub it into another language. It is like text printed into a photo instead of typed on top.','Identifying embedded dialogue matters for localization and M&E creation: it flags speech that cannot be swapped for a dubbed version, so teams can plan to re-create, replace, or accept it in the original language.','When preparing an M&E, the editor flags embedded dialogue — such as a lyric or a mixed-in crowd line — so the dubbing team knows it cannot be cleanly replaced and decides how to handle it.','Localization Prep',ARRAY['Music and effects','Dubbing mix','Walla','Dialogue guide','Source music']::text[],ARRAY['Assuming all dialogue can be separated for dubbing, then discovering lines baked into the M&E.','Delivering an M&E with embedded dialogue left in, so the foreign version still contains original-language speech.','Confusing embedded dialogue with a clean dialogue stem that can be swapped.']::text[],ARRAY['A song with lyrics under a scene that cannot be re-dubbed.','Crowd lines mixed into the effects that survive into the foreign version.','Preparing an M&E and flagging speech that cannot be isolated.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26b3b46c-2feb-5f91-b8b6-ce90a6d3bcd7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Embedded dialogue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26b3b46c-2feb-5f91-b8b6-ce90a6d3bcd7','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='26b3b46c-2feb-5f91-b8b6-ce90a6d3bcd7' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '483869dc-4491-5130-944c-ad5a9ba7ee49','End-sync error','A synchronization fault in which a dubbed or replaced line finishes out of alignment with the picture — the audio continues after the character''s mouth stops, or ends before it — even if the line began in sync, reflecting a failure of isochrony across the length of the utterance. It is a common lip-sync defect caught in dubbing and ADR quality control.','An end-sync error is when a line ends out of time with the picture. The mouth stops but the voice keeps going, or the voice stops too soon. The start looked fine, but the timing drifted by the end.','Naming it helps editors and quality control catch lines that start in sync but drift, so they can retime, re-edit, or re-record the tail to match the character''s lip movements.','In review, the editor spots a dubbed line whose end runs past the closed mouth, then shortens or retimes it, or flags it for a re-take.','Sync Error',ARRAY['Isochrony','Lip sync','Dubbing rhythm','ADR','Kinesic synchrony']::text[],ARRAY['Checking only the start of a line for sync and missing drift at the end.','Fixing an end-sync error by cutting a word abruptly instead of retiming the whole line.','Writing an adapted line too long, so it cannot end in sync no matter how it is delivered.']::text[],ARRAY['A dubbed line''s audio runs on after the character''s mouth closes.','Quality control flags a line that drifts out of sync by its final word.','Retiming the tail of an ADR line so it lands with the lip movement.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='483869dc-4491-5130-944c-ad5a9ba7ee49' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('End-sync error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '483869dc-4491-5130-944c-ad5a9ba7ee49','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='483869dc-4491-5130-944c-ad5a9ba7ee49' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '987c1374-90a8-5dd8-9add-8d3e02d82b51','Ensemble dubbing','A dubbing recording method in which several voice actors perform their lines together in the same session, in real time, rather than each recording their part alone. It preserves natural interaction, overlaps, and timing between characters as the scene is re-voiced in the target language.','Ensemble dubbing means the voice actors record their lines together at the same time. Because they act off each other, the talk sounds more natural, like a real conversation.','It captures believable dialogue chemistry, overlaps, and reactions that are hard to recreate when actors are recorded separately, improving the naturalness of the dubbed scene.','A dubbing director schedules key dialogue scenes with the full group present so performers can react to each other, reserving solo booking for pickups or when schedules conflict.','Dubbing Workflow',ARRAY['Solo dubbing','ADR','Dubbing director','Isochrony','Loop group']::text[],ARRAY['Assuming ensemble recording is always better; tight lip-sync pickups are often still recorded solo for precision.','Confusing ensemble dubbing with group ADR or walla, which is background crowd voice rather than principal character dialogue.','Believing every production can afford to book the whole cast together, when scheduling and cost often force solo sessions.']::text[],ARRAY['Re-voicing a fast, overlapping argument where actors need to bounce off each other''s timing.','A comedy series dub where reaction timing between characters drives the humor.','Booking the lead trio together for an emotional scene, then recording minor pickups solo.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='987c1374-90a8-5dd8-9add-8d3e02d82b51' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ensemble dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '987c1374-90a8-5dd8-9add-8d3e02d82b51','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='987c1374-90a8-5dd8-9add-8d3e02d82b51' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '80519bd6-79aa-59ad-bb92-b880c40c511e','Entry tolerance','The permissible margin of timing error allowed at the start (entry) of a dubbed line relative to the moment the on-screen character''s mouth begins to move. It defines how early or late a re-voiced utterance may begin before the loss of lip-sync becomes noticeable.','Entry tolerance is how much wiggle room you get at the start of a dubbed line. If the new voice begins too far from when the mouth opens, viewers notice the sync is off.','It gives dialogue writers and editors a working target for how precisely a line''s opening must line up with the picture, since audiences notice sync errors most at the start of speech.','A dubbing editor nudges a recorded take earlier or later within the entry tolerance so the first syllable lands on the character''s mouth opening.','Synchronization',ARRAY['Exit tolerance','Isochrony','Lip synchrony','Flap coverage','Dubbing take']::text[],ARRAY['Treating the whole line''s timing as equally forgiving, when the entry point is one of the most sync-critical moments.','Fixing entry sync by time-stretching the audio so much that the voice sounds unnatural.','Ignoring the character''s mouth opening and syncing only to the previous line''s rhythm.']::text[],ARRAY['Aligning the first word of a dubbed reply to the exact frame a character starts speaking.','Reviewing a take that starts a few frames late and deciding whether it is within tolerance.','Training a new dubbing editor on how tight the entry must be for a close-up.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='80519bd6-79aa-59ad-bb92-b880c40c511e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Entry tolerance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '80519bd6-79aa-59ad-bb92-b880c40c511e','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
