INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c66a1429-e634-5524-8ee1-5a7987e4b884','Euphemistic substitution','A translation strategy in which offensive, taboo, or vulgar source dialogue is replaced with a milder, more socially acceptable target-language expression. It softens the register while attempting to preserve the communicative function of the original line.','Euphemistic substitution swaps a rude or taboo word for a gentler one when translating. It keeps the meaning but makes the language less shocking for the new audience.','It lets a dubbed version meet local broadcast rules, ratings, or cultural norms about strong language while still conveying the intent of the line.','A dub translator renders a strong expletive as a mild exclamation to fit a broadcaster''s content standards or a family time-slot.','Translation Strategy',ARRAY['Taboo language','Toning down','Dialogue adaptation','Censorship','Register']::text[],ARRAY['Over-softening so the character''s tone, aggression, or social class is lost.','Applying euphemism inconsistently, so one scene is toned down and a similar scene is not.','Assuming all markets require it, when some platforms want faithful strong language retained.']::text[],ARRAY['Dubbing a violent drama for a daytime television slot with strict language rules.','Localizing a comedy for a market where certain swear words are legally restricted.','Adapting slang insults so they land naturally without breaching a platform''s content policy.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c66a1429-e634-5524-8ee1-5a7987e4b884' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Euphemistic substitution'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c66a1429-e634-5524-8ee1-5a7987e4b884','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
