INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0002eb14-a04e-571c-b2f2-a2f4d4cb6da0','Exit tolerance','The permissible margin of timing error allowed at the end (exit) of a dubbed line relative to the moment the on-screen character''s mouth stops moving. It defines how much a re-voiced utterance may over- or under-run the visible mouth closure before sync appears broken.','Exit tolerance is the wiggle room you get at the end of a dubbed line. If the voice keeps going after the mouth closes, the sync looks wrong.','It sets how precisely a line''s ending must match the picture, since a voice that runs past a closed mouth is one of the most obvious sync errors.','A dubbing editor trims or tightens the tail of a take so the last sound ends as the character''s mouth closes, staying within exit tolerance.','Synchronization',ARRAY['Entry tolerance','Isochrony','Lip synchrony','Flap violation','Dubbing take']::text[],ARRAY['Letting the dubbed line trail on after the mouth has clearly closed.','Cutting the tail so hard that the last word sounds clipped or unnatural.','Focusing only on the line''s start and ignoring how it ends.']::text[],ARRAY['Checking that a dubbed sentence stops as the actor closes their lips in a close-up.','Deciding whether a take that runs two frames long is acceptable.','Editing overlapping lines so one voice does not spill past the speaker''s mouth movement.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0002eb14-a04e-571c-b2f2-a2f4d4cb6da0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Exit tolerance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0002eb14-a04e-571c-b2f2-a2f4d4cb6da0','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
