INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ec79f10-9d79-5437-9e18-5a73e66b7758','Fandubbing','The non-commercial, amateur dubbing of audiovisual content produced by fans rather than authorized studios, typically distributed online and often without rights-holder permission. It is a form of fan audiovisual translation and the dubbed counterpart to fansubbing.','Fandubbing is when fans, not a studio, re-voice a show in another language for free. They usually share it online, often without the owner''s permission.','It gives fan communities access to content in their own language when no official dub exists, and lets amateurs practice voice and translation work.','Fans record replacement dialogue at home over the original video and post the result on video-sharing platforms, with quality and legality varying widely.','Fan Translation',ARRAY['Fansubbing','Cyberdubbing','ADR','Audiovisual translation','Voice acting']::text[],ARRAY['Assuming fandubs meet the technical and legal standards of an official studio dub.','Ignoring copyright, since distributing a fandub of protected content can infringe rights.','Confusing fandubbing with fansubbing, which adds subtitles rather than replacing the voices.']::text[],ARRAY['A fan group re-voicing an anime episode that lacks an official dub in their language.','A voice-acting hobbyist building a demo reel by dubbing film clips.','An online community releasing a fandub before a licensed version becomes available.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ec79f10-9d79-5437-9e18-5a73e66b7758' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fandubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ec79f10-9d79-5437-9e18-5a73e66b7758','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ec79f10-9d79-5437-9e18-5a73e66b7758' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb74ce81-2721-592e-a384-8e2eb7b2dc5c','Fixed voice','A casting convention in which a single dubbing actor is consistently assigned to voice a particular foreign performer or character across multiple productions, so the target-language audience associates one recurring voice with that person. It is common in established dubbing cultures such as Italy and Germany.','A fixed voice is when the same dub actor always voices one foreign star or character. Local viewers get used to hearing that one voice for that person.','It builds audience familiarity and continuity, so a well-known actor sounds ''the same'' in every dubbed film, protecting the star''s recognizable identity in that market.','A dubbing house maintains a roster linking foreign actors to their official target-language voices and re-books the same performer for each new title.','Voice Casting',ARRAY['Franchise voice continuity','Voice casting','Dubbing director','Voice matching','Ensemble dubbing']::text[],ARRAY['Recasting a star''s established voice without warning, which breaks audience expectation.','Assuming a fixed voice is contractually guaranteed, when availability, cost, or death can force a change.','Confusing a fixed voice with simple voice matching on a single project.']::text[],ARRAY['Re-booking the long-standing target-language voice of a Hollywood star for their newest film.','A market where audiences complain when a familiar dubbed voice is replaced.','Casting a replacement carefully when a fixed-voice actor retires.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb74ce81-2721-592e-a384-8e2eb7b2dc5c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fixed voice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fb74ce81-2721-592e-a384-8e2eb7b2dc5c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
