INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cf8c7306-9c99-5613-9a3d-a90d0eba1eb8','Flap coverage','In animation dubbing, the degree to which the re-voiced dialogue fills a character''s visible mouth movements (flaps) across a line, so that speech is present whenever the mouth is open and absent when it is closed. Good flap coverage means the target line''s syllable count and rhythm map onto the drawn mouth articulations.','Flap coverage is how well the new dialogue fills a cartoon character''s mouth movements. When the mouth flaps open, there should be a matching sound.','It keeps animated lip-sync believable by ensuring the translated line has enough syllables in the right places to match the drawn mouth movements.','A dub writer counts a character''s mouth flaps and adapts the translation so its syllables cover them without leaving open mouths silent or closed mouths sounding.','Synchronization',ARRAY['Flap violation','Lip synchrony','Isochrony','Entry tolerance','Mouth chart']::text[],ARRAY['Writing a line with too few syllables, leaving mouths flapping with no sound.','Cramming in too many syllables so the voice keeps talking over a closed mouth.','Treating animated flap coverage exactly like live-action lip-sync, ignoring the stylized mouth shapes.']::text[],ARRAY['Adapting an anime script so the dialogue matches each character''s mouth flaps.','A dub writer reworking a line that leaves a visible open mouth silent.','Redoing a take in session because the words did not cover the animation.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cf8c7306-9c99-5613-9a3d-a90d0eba1eb8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flap coverage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cf8c7306-9c99-5613-9a3d-a90d0eba1eb8','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cf8c7306-9c99-5613-9a3d-a90d0eba1eb8' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8bed2f34-1ae1-5e56-950f-097a776d3f09','Flap violation','A lip-sync error in animation dubbing in which the re-voiced dialogue fails to match the character''s visible mouth movements — for example, audible speech continuing while the mouth is closed, or an open, moving mouth producing no sound. It is a specific breach of flap coverage.','A flap violation is a sync mistake in cartoon dubbing. The voice and the mouth do not match, like sound coming out while the mouth is shut.','Naming this error helps editors and reviewers flag and fix moments where dubbed audio breaks the illusion that the character is speaking the new language.','A quality-control reviewer marks a flap violation when a dubbed line is heard over a closed mouth, sending the take back for re-editing or re-recording.','Synchronization',ARRAY['Flap coverage','Lip synchrony','Exit tolerance','Foreign-version QC','Isochrony']::text[],ARRAY['Ignoring small flap violations on wide shots that are still visible to attentive viewers.','Fixing a violation by time-stretching audio so much it sounds robotic.','Confusing a flap violation with an isochrony error, which is about overall line length rather than mouth match.']::text[],ARRAY['Quality control catching dubbed dialogue that plays while a character''s mouth is closed.','A close-up where the voice ends but the mouth keeps moving, needing a fix.','Reviewing an animated dub for mouth-match errors before delivery.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8bed2f34-1ae1-5e56-950f-097a776d3f09' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flap violation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8bed2f34-1ae1-5e56-950f-097a776d3f09','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
