INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f43c718a-486e-5ab5-a49a-6ff7503f8c9b','Foreign dialogue stem','A discrete audio stem containing only the dubbed, foreign-language dialogue of a localized version, delivered separately from the music-and-effects (M&E). It lets the dubbed dialogue be archived, re-mixed, or conformed against the M&E without affecting other soundtrack elements.','A foreign dialogue stem is a separate audio track. It holds only the dubbed voices in the new language. Keeping it apart lets editors remix or store the voices without touching the music and effects.','It isolates the localized dialogue so it can be combined with the M&E, quality-checked, archived, and revised independently of the rest of the soundtrack.','A re-recording mixer delivers the dubbed dialogue as its own stem so the localized version can be rebuilt or corrected later without a full remix.','Audio Stems',ARRAY['M&E','Foreign-version mix','Dialogue stem','Foreign-language walla','Print master']::text[],ARRAY['Baking the dialogue into the final mix so it cannot be separated for later revisions.','Delivering the stem out of sync with the picture or the M&E.','Confusing the foreign dialogue stem with the M&E, which deliberately contains no dialogue.']::text[],ARRAY['Delivering a dubbed dialogue stem alongside the M&E for archival.','Fixing a mistranslated line later by editing only the dialogue stem.','Rebuilding a localized mix from separate dialogue and M&E stems.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f43c718a-486e-5ab5-a49a-6ff7503f8c9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Foreign dialogue stem'),'[^a-z0-9]','','g'));
