INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5605e531-feae-5f18-9f5c-2703e68296b0','Foreign-language walla','Background crowd murmur (walla) recorded in the target language to replace source-language crowd voices that are removed from the fully-filled M&E during localization. It restores realistic, language-appropriate ambient chatter to a dubbed version.','Foreign-language walla is background crowd chatter recorded in the new language. It replaces the original crowd voices so a dubbed scene sounds like it belongs in that country.','It keeps crowd and background voices consistent with the dubbed dialogue, since language-specific walla is stripped from the M&E and must be re-created for each localized version.','A loop group records target-language walla for a restaurant or street scene so the background voices match the language of the dub.','Loop Group',ARRAY['Walla','Loop group','M&E','Group ADR','Foreign-version Foley']::text[],ARRAY['Leaving the original-language walla in the mix, so the crowd speaks a different language than the leads.','Assuming generic non-verbal crowd beds are enough when the picture shows people clearly speaking.','Recording walla whose accent or dialect does not match the dubbed market.']::text[],ARRAY['Recording target-language crowd murmur for a busy market scene in a dub.','Replacing English background chatter with the dub language for a café background.','A loop group creating localized walla to fill an M&E that had crowd voices removed.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5605e531-feae-5f18-9f5c-2703e68296b0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Foreign-language walla'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5605e531-feae-5f18-9f5c-2703e68296b0','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
