INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1feb7bd4-6163-558a-9afc-560357b0ff29','Foreign-version Foley','Foley effects re-recorded or supplemented for a localized version, typically when the original Foley is missing from the delivered M&E or was captured together with source-language dialogue that must be removed. It restores footsteps, cloth, and prop sounds so the dubbed version matches the original soundtrack.','Foreign-version Foley is everyday sound effects, like footsteps and cloth, redone for a dub. It fills gaps left when the original effects were tied to the old dialogue.','It ensures the localized soundtrack has complete, in-sync performance effects when the delivered M&E is not fully filled, keeping the dub consistent with the original.','A Foley artist re-performs footsteps and prop sounds for scenes where those effects were lost when source-language dialogue was stripped out.','Sound Effects',ARRAY['Foley','M&E','Foreign-language walla','Foreign-version mix','PFX']::text[],ARRAY['Assuming every M&E is fully filled, then discovering missing Foley late in the mix.','Recording replacement Foley that does not match the timing or texture of the picture.','Confusing performed Foley with library sound effects; Foley is performed to picture in real time.']::text[],ARRAY['Re-recording footsteps for a dub after dialogue-linked Foley was removed from the M&E.','Filling missing prop sounds discovered during a foreign-version mix.','A Foley team supporting localization when the delivered M&E is incomplete.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1feb7bd4-6163-558a-9afc-560357b0ff29' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Foreign-version Foley'),'[^a-z0-9]','','g'));
