INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '292eda4f-94ac-56ec-b707-7d32d35f66b4','Foreign-version QC','The quality-control (QC) pass performed on a completed localized version, checking lip-sync, dialogue accuracy, mix balance, loudness compliance, and technical conformance to the original picture and delivery specifications before the dub is approved.','Foreign-version QC is the final check on a finished dub. Reviewers make sure the sync, translation, mix, and loudness are all correct before it ships. QC stands for quality control.','It catches sync errors, mistranslations, mix problems, and spec failures so the delivered dub meets both creative and technical standards.','A QC operator watches the dubbed version against the original, logging timecoded notes for sync, audio, and content issues to be fixed before delivery.','Quality Control',ARRAY['Foreign-version mix','Flap violation','Loudness','Lip synchrony','Delivery specification']::text[],ARRAY['Checking only the audio and missing on-screen text or graphics that still need localizing.','Spot-checking instead of a full-length review, so errors slip through.','Passing a mix that sounds fine in the room but fails the required loudness spec.']::text[],ARRAY['Reviewing a completed dub against the original before platform delivery.','Logging timecoded sync and audio notes for a dubbing studio to fix.','Verifying that a localized mix meets the platform''s loudness and true-peak targets.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='292eda4f-94ac-56ec-b707-7d32d35f66b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Foreign-version QC'),'[^a-z0-9]','','g'));
