INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '172dbfee-34a0-57d2-ae72-1d50b5091dc9','Foreign-version mix','The final re-recording mix that combines the dubbed dialogue stem with the original music-and-effects (M&E) to produce a complete localized soundtrack matching the original mix''s balance and meeting the platform''s delivery loudness and true-peak specifications.','A foreign-version mix blends the new dubbed voices with the original music and sound effects. The goal is a finished dub that sounds like the original and meets the delivery specs.','It re-balances localized dialogue against the M&E so the dubbed soundtrack matches the creative intent and loudness targets of the original-language mix.','A re-recording mixer sets dubbed dialogue levels, panning, and reverb against the M&E, then delivers to the required integrated loudness and true-peak limits.','Mixing',ARRAY['Foreign dialogue stem','M&E','Foreign-version QC','Loudness','Print master']::text[],ARRAY['Mixing the dubbed dialogue louder or drier than the original, so it sounds pasted on.','Ignoring the delivery loudness and true-peak spec until QC rejects the mix.','Assuming the M&E is complete and skipping checks for missing Foley or walla.']::text[],ARRAY['Combining a dubbed dialogue stem with the M&E to finish a localized episode.','Matching dubbed dialogue reverb and level to the original mix.','Delivering a dub mix to a streaming platform''s loudness specification.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='172dbfee-34a0-57d2-ae72-1d50b5091dc9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Foreign-version mix'),'[^a-z0-9]','','g'));
