INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae0305cc-8bb3-5703-943f-c12e9e9279f9','Franchise voice continuity','The practice of keeping the same target-language dubbing voice for a recurring character or performer across all installments of a franchise, so the localized voice remains consistent from film to film and across sequels, spin-offs, and tie-ins.','Franchise voice continuity means using the same dub actor for a character across a whole series. Fans keep hearing the same voice in every film or sequel.','It preserves audience recognition and brand consistency across a franchise, so a returning character sounds the same in every localized entry.','A localization producer tracks which dub actors voiced each character and re-books them for sequels, spin-offs, and crossovers.','Voice Casting',ARRAY['Fixed voice','Voice casting','Dubbing director','Voice matching','Continuity']::text[],ARRAY['Recasting a returning character''s dub voice between sequels, breaking audience continuity.','Failing to record or track voice data, so the original actor cannot be found for the next installment.','Assuming voice matching a new actor is as good as re-booking the original established voice.']::text[],ARRAY['Re-booking the same dub actor for a superhero across a multi-film franchise.','Maintaining a character''s localized voice when a series moves from film to a spin-off show.','Planning replacement casting when a franchise''s established dub voice is unavailable.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae0305cc-8bb3-5703-943f-c12e9e9279f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Franchise voice continuity'),'[^a-z0-9]','','g'));
