INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c42c891-256f-58b6-9dda-adb8b740b405','Full dubbing','A revoicing mode in which the entire original dialogue track is replaced by a new track in the target language, performed to fit the on-screen characters'' mouths and timing so the original voices are no longer heard. It combines lip synchrony, isochrony, and kinesic synchrony, and is the dominant localization mode in dubbing countries such as Spain, Italy, France, and Germany.','Full dubbing replaces every original spoken line with new lines in another language. The new voices are timed to match the actors'' mouths. Viewers hear only the new language, not the original voices.','It lets audiences watch foreign content in their own language without reading subtitles, by substituting a fully synchronized target-language performance for the original dialogue.','A dubbing studio casts target-language actors, adapts a lip-synced script, and records each role to picture, then mixes the new dialogue with the M&E track to deliver a complete localized version.','Dubbing Mode',ARRAY['Isochrony','Lip sync','Partial dubbing','Voice-over','M&E track','Indirect dubbing']::text[],ARRAY['Confusing full dubbing with voice-over, where the original voices stay audible under the translation.','Prioritizing exact translation over lip and timing sync, so the dubbed lines visibly drift from the mouths.','Assuming full dubbing needs no M&E track, when the localized dialogue must be laid over music and effects.']::text[],ARRAY['Localizing a US series into German for a market that expects lip-synced dubs.','Replacing all character dialogue in an animated feature for international release.','Deciding between full dubbing and subtitling for a streaming title''s target territory.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c42c891-256f-58b6-9dda-adb8b740b405' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Full dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9c42c891-256f-58b6-9dda-adb8b740b405','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c42c891-256f-58b6-9dda-adb8b740b405' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '250dc6f3-cca3-5a18-a939-36e1666770bf','Functional equivalence','A translation principle, associated with Eugene Nida, in which the translation aims to produce on its target audience an effect equivalent to the effect the source text had on its original audience, prioritizing the receptor''s response and communicative function over word-for-word formal correspondence. In dubbing and localization it guides adapting jokes, idioms, register, and cultural references so they work naturally for the target viewer.','This aims to make the translation feel the same to its audience. A joke should still be funny. A threat should still feel scary. It copies the effect, not the exact words.','It exists to keep the meaning, impact, and naturalness of a message intact across languages, rather than producing a literal rendering that feels foreign or falls flat.','A dubbing translator replaces an untranslatable pun or local reference with a target-culture equivalent that lands the same way for the viewer while still fitting the picture and timing.','Translation Strategy',ARRAY['Honorific adaptation','Full dubbing','Isochrony','Indirect dubbing','Localization','Adaptation','Dynamic equivalence (Nida''s earlier term; functional equivalence is his later name for the same concept)']::text[],ARRAY['Translating word for word and losing the humor, tone, or impact the original had.','Treating functional equivalence as license to rewrite freely, ignoring the source meaning.','Forgetting that a functionally equivalent line must still fit lip and timing constraints in a dub.']::text[],ARRAY['Adapting a culture-specific joke so it stays funny in the target language.','Choosing a local idiom that carries the same feeling as the original phrase.','Rendering a brand or food reference into something the target audience recognizes.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='250dc6f3-cca3-5a18-a939-36e1666770bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Functional equivalence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '250dc6f3-cca3-5a18-a939-36e1666770bf','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='250dc6f3-cca3-5a18-a939-36e1666770bf' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '20bfe51b-41f7-5182-b4ad-321855ae3494','Fundubbing','A form of fan-made revoicing (a blend of "fun" and "dubbing") in which amateurs replace a work''s original dialogue with a deliberately humorous, satirical, or parodic script that departs from the source meaning, rather than faithfully translating it. It is a parodic subtype of fandubbing, created by and for fan communities and distributed informally or online.','A fundub is a funny fake dub made by fans. They swap the real lines for silly or rude ones for laughs. It is a comedy remix, not a real translation.','It exists for entertainment and creative play within fan communities, using an existing video as raw material for comedy or satire rather than to accurately localize it.','A fan re-records new comedic dialogue over an anime clip or film scene and shares it online, ignoring the original meaning in favor of jokes.','Dubbing Mode',ARRAY['Fandubbing','Full dubbing','Voice-over','Localization','Gavrilov translation','Functional equivalence']::text[],ARRAY['Confusing a fundub with a faithful fan translation, when it intentionally changes the meaning for comedy.','Assuming fundubs meet professional sync or mix standards, which they usually do not.','Overlooking that fundubs of copyrighted works can raise rights issues despite being fan-made.']::text[],ARRAY['Fans posting a comedic redub of a popular anime scene online.','A parody revoicing of a movie trailer replacing serious lines with jokes.','Community creators making satirical versions of foreign clips for humor.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='20bfe51b-41f7-5182-b4ad-321855ae3494' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fundubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '20bfe51b-41f7-5182-b4ad-321855ae3494','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='20bfe51b-41f7-5182-b4ad-321855ae3494' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ce35e81e-a21c-5fd2-bba5-c982ac06f531','Gavrilov translation','A single-voice voice-over style, named after Russian interpreter Andrey Gavrilov, in which one narrator reads a translation of all characters'' lines over the still-audible original soundtrack, typically with minimal synchronization and a flat, uninflected delivery. It was widespread on videotape in Russia and post-Soviet countries in the 1980s and 1990s.','This is a Russian style of voice-over from the 1980s and 90s. One person reads all the lines in a flat voice. You can still hear the original actors underneath.','It provided a fast, low-cost way to make foreign films understandable to Russian-speaking audiences when full dubbing was unavailable, using a single interpreter over the original audio.','A technician encounters it on archival Soviet-era video releases, where one narrator voices every role above the original dialogue rather than a full cast dub.','Voice-over Mode',ARRAY['Voice-over','Full dubbing','Fundubbing','Indirect dubbing','Localization','Isochrony']::text[],ARRAY['Confusing Gavrilov-style voice-over with full dubbing, which fully removes the original voices.','Assuming the single narrator uses distinct character voices, when delivery is typically flat and uniform.','Treating its loose sync as a defect to fix, rather than a defining trait of the style.']::text[],ARRAY['Cataloging archival Russian VHS releases with one-voice narration.','Comparing Eastern European voice-over traditions with Western full dubbing.','Restoring an old single-voice narrated film for reissue.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ce35e81e-a21c-5fd2-bba5-c982ac06f531' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gavrilov translation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ce35e81e-a21c-5fd2-bba5-c982ac06f531','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ce35e81e-a21c-5fd2-bba5-c982ac06f531' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0aa7e6d7-ab67-5c52-94c2-c53e17e2ab18','Guide bleed','Unwanted leakage of the guide (cue) track — the original dialogue or timing reference fed to a performer''s headphones during dubbing or ADR — into the recording microphone, leaving faint traces of the original audio in the newly recorded clean take. It is a form of headphone/cue spill and contaminates a track that must be isolated for mixing.','In dubbing, actors hear the original lines through headphones. Guide bleed is when that sound leaks into the mic. It leaves faint traces of the old track in the new clean take.','Naming it helps engineers recognize and prevent contamination of the dubbing/ADR recording, keeping the new dialogue isolated from the original guide audio.','A recordist lowers headphone level, switches to closed-back or single-ear monitoring, and checks quiet moments for leakage so the recorded dub stays free of guide-track spill.','Recording Workflow',ARRAY['Guide-track dependency','ADR','Full dubbing','Room tone','Internal-sync error','M&E track']::text[],ARRAY['Monitoring the guide at high headphone volume, so the original dialogue leaks into the mic.','Not checking pauses and breaths for faint guide audio before approving a take.','Assuming guide bleed can always be removed later, when heavy leakage can ruin an otherwise good take.']::text[],ARRAY['Recording ADR where the actor cues off the original line in headphones.','Tracking a dub in a booth and hearing the reference track under the new voice.','Cleaning a recorded take that has picked up headphone spill.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0aa7e6d7-ab67-5c52-94c2-c53e17e2ab18' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guide bleed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0aa7e6d7-ab67-5c52-94c2-c53e17e2ab18','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0aa7e6d7-ab67-5c52-94c2-c53e17e2ab18' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '328b0f6d-1695-5978-9e34-610c7db165a2','Guide-track dependency','The extent to which a dubbing or ADR workflow relies on a guide (scratch/temp) track — the original dialogue or a rough timing reference — for pacing, sync, and performance cues. High dependency means errors or inaccuracies in the guide track are carried through into the final recorded dub.','A guide track is a rough version used for timing. Guide-track dependency means the work leans too much on it. If the guide is wrong, the final dub copies the same mistakes.','Recognizing it warns editors and directors that the quality of the final dub is only as good as the guide it follows, so the guide must be accurate and trustworthy.','A dubbing supervisor verifies that the guide track matches the locked picture and correct timing before actors record against it, to avoid propagating sync or timing errors.','Recording Workflow',ARRAY['Guide bleed','Isochrony','Internal-sync error','ADR','Full dubbing','Lip sync']::text[],ARRAY['Recording a whole session against a guide that is out of sync, so every take inherits the drift.','Trusting a temp guide''s timing without confirming it against the final locked picture.','Letting performers copy the guide''s rhythm so closely that the new performance feels unnatural.']::text[],ARRAY['Cueing ADR from a scratch guide before checking it matches the final cut.','Building a dub against a rough timing reference for a fast turnaround.','Diagnosing repeated sync errors traced back to a faulty guide track.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='328b0f6d-1695-5978-9e34-610c7db165a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guide-track dependency'),'[^a-z0-9]','','g'));
