INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'af4ef491-14da-52f3-b53c-753e06a48376','Honorific adaptation','The localization strategy for handling source-language honorifics and forms of address (such as Japanese -san, -sama, -kun, or formal/informal pronouns) in dubbing and subtitling, choosing among retention (keeping the original term), omission, or substitution with a target-language equivalent of politeness or register. The choice affects how social hierarchy, respect, and character relationships are conveyed to the target audience.','Some languages add respect words to names, like the Japanese word ''san''. Honorific adaptation decides how to handle these. The team may keep them, drop them, or swap in a polite word.','It exists to carry the politeness, social distance, and hierarchy encoded in honorifics into a target language that may mark respect differently, preserving character dynamics.','A localizer for an anime dub decides whether to keep -san, drop it, or replace it with a title like "Mr." so the dialogue sounds natural yet still signals the intended respect.','Translation Strategy',ARRAY['Functional equivalence','Localization','Full dubbing','Isochrony','Indirect dubbing','Adaptation']::text[],ARRAY['Dropping honorifics entirely and flattening the respect and hierarchy between characters.','Retaining every honorific untranslated, which can confuse audiences unfamiliar with them.','Choosing one substitute for all honorifics, erasing the distinctions between levels like -san and -sama.']::text[],ARRAY['Dubbing a Japanese anime where characters address elders with -sama.','Deciding how to render formal versus informal ''you'' when localizing a European drama.','Keeping or replacing honorifics consistently across a whole dubbed series.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='af4ef491-14da-52f3-b53c-753e06a48376' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Honorific adaptation'),'[^a-z0-9]','','g'));
