INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '99a6fffc-243c-5667-a9e3-46b598d12cff','In-territory QC','Quality control of a localized dub, subtitle, or version performed within the target territory by native-speaking reviewers, who check translation accuracy, cultural appropriateness, register, sync, and mix against the source and against local expectations. It catches linguistic and cultural problems that out-of-territory teams are likely to miss.','In-territory QC means checking the dub inside the country it is made for. Local native speakers review it. They catch odd wording, wrong tone, and timing errors that outsiders miss.','It exists to verify that a localized version reads as natural, accurate, and culturally appropriate to real target-audience viewers before release, reducing costly recalls or re-dubs.','A native reviewer in the target country watches the dubbed episode against the original, logging mistranslations, awkward phrasing, lip-sync slips, and mix issues for correction.','Quality Control',ARRAY['Full dubbing','Localization','Internal-sync error','Isochrony','Functional equivalence','M&E track']::text[],ARRAY['Skipping in-territory review and shipping a dub with unnatural phrasing native speakers would flag.','Treating QC as only a technical check, ignoring translation, register, and cultural accuracy.','Relying on non-native reviewers who miss idiom, slang, and tone errors in the target language.']::text[],ARRAY['A streaming platform commissioning native reviewers to vet each localized dub.','Catching a mistranslated idiom before a series launches in its target market.','Verifying loudness, sync, and language quality of a delivered dubbed track.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='99a6fffc-243c-5667-a9e3-46b598d12cff' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('In-territory QC'),'[^a-z0-9]','','g'));
