SELECT '99a6fffc-243c-5667-a9e3-46b598d12cff','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='99a6fffc-243c-5667-a9e3-46b598d12cff' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e5d567b4-9d7a-55a3-a9cd-f138c0d59a53','Indirect dubbing','Dubbing produced through an intermediate (pivot or relay) language or script rather than directly from the original, so the target dialogue is created from an already-translated mediating text — for example dubbing a Korean film into Polish from an English template. It is a form of indirect (pivot) audiovisual translation.','Sometimes a film is dubbed from a middle language, not the first one. For example, a Korean film is dubbed from an English script. This middle step can add or spread small errors.','It exists to make localization feasible and cheaper when few translators work directly between the original and target languages, using a common pivot language as a bridge.','A studio localizing a rare-language title works from an English pivot script and audio, adapting and recording the target-language dub from that intermediate version.','Dubbing Mode',ARRAY['Full dubbing','Functional equivalence','Localization','Gavrilov translation','Honorific adaptation','Isochrony']::text[],ARRAY['Assuming the pivot version is a perfect copy, so errors in it pass straight into the dub.','Losing source-language nuance and cultural detail that the pivot text already dropped.','Timing lines to the pivot rather than the original picture, causing sync drift.']::text[],ARRAY['Dubbing a Korean series into a smaller-market language via an English template.','Localizing an anime from an English script rather than the Japanese original.','Distributing a film to many territories using one pivot version as the source.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e5d567b4-9d7a-55a3-a9cd-f138c0d59a53' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Indirect dubbing'),'[^a-z0-9]','','g'));
