WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e5d567b4-9d7a-55a3-a9cd-f138c0d59a53' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ea8631a8-5abd-5862-9abc-be413f1ea83f','Internal-sync error','A synchronization fault contained within the program material itself, in which the dubbed dialogue is misaligned with the picture — for example lip-sync or isochrony drift baked into the recorded/mixed track — as distinct from an external playback offset introduced by a device or transmission chain. The mismatch travels with the file rather than depending on the viewer''s system.','This is when the new voices drift out of time with the picture. A mouth moves but the matching sound comes late or early. The mismatch lives in the file itself, not your player.','Distinguishing it from external A/V delay tells the technician the fault is in the edit or mix and must be fixed in the material, not corrected by adjusting playback.','An editor spots dubbed lines sliding off the mouths within a scene, then re-conforms or nudges the dialogue in the session to restore lip and timing sync.','Synchronization',ARRAY['Isochrony','Lip sync','Guide-track dependency','Full dubbing','In-territory QC','Guide bleed']::text[],ARRAY['Blaming the player or TV for a sync problem that is actually baked into the file.','Fixing only one scene when the whole dub has drifted from a bad conform or frame-rate error.','Adjusting a global audio delay to hide a drift that varies across the program.']::text[],ARRAY['Reviewing a dub where lip-sync slips progressively through a reel.','Diagnosing whether a sync fault is in the file or in the playback chain.','Correcting dialogue offset caused by a wrong frame-rate conform.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ea8631a8-5abd-5862-9abc-be413f1ea83f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Internal-sync error'),'[^a-z0-9]','','g'));
