INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54e5ab67-cf1b-5a63-adab-f71808342703','International Foley','Foley (hand-performed everyday sounds such as footsteps, cloth movement, and prop handling) created specifically to fully fill the international M&E (music and effects) track, so that when the original production dialogue is removed for dubbing, all synchronous non-dialogue sounds still exist. It replaces effects that were captured only on the production dialogue track and would otherwise be lost.','Foley is everyday sound made by hand, like footsteps and door knocks. International Foley rebuilds these for the dub. It fills sounds that were lost when the original voices were removed.','It ensures the dubbed version has complete, natural-sounding effects, because stripping the dialogue track also strips the incidental sounds recorded with it.','A Foley team performs footsteps, cloth passes, and prop sounds to picture so the M&E track is fully covered and a foreign-language dub sits over complete effects.','M&E Version',ARRAY['M&E track','International-version reconstruction','Full dubbing','Room tone','Localization','Indirect dubbing']::text[],ARRAY['Delivering an M&E that omits Foley, so the dub has silent footsteps and missing prop sounds.','Assuming production effects survive dialogue removal, when many are tied to the dialogue track.','Mismatching Foley level or perspective so the international version sounds unlike the original mix.']::text[],ARRAY['Building a fully filled M&E for a series licensed to dubbing territories.','Replacing footsteps and cloth lost when the production dialogue stem is muted.','Preparing a feature''s international version before foreign-language dubs are recorded.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54e5ab67-cf1b-5a63-adab-f71808342703' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('International Foley'),'[^a-z0-9]','','g'));
