SELECT '54e5ab67-cf1b-5a63-adab-f71808342703','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54e5ab67-cf1b-5a63-adab-f71808342703' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '799d056f-747f-5c92-bb13-c159d3ec563c','International-version reconstruction','The process of rebuilding a complete, fully-filled international (M&E) version of a title when the original music-and-effects track is missing, incomplete, or damaged, by recreating effects, Foley, backgrounds, and where needed music so the program can be dubbed into other languages. It is common in archival and catalog work where only a mixed final with dialogue survives.','This rebuilds a film''s music and sound-effects track when it is missing. Teams recreate the effects, Foley, and music. Then the film can be dubbed into other languages.','It exists so older or poorly delivered titles without a usable M&E can still be localized, since dubbing requires a dialogue-free bed of music and effects.','An audio post team recreates missing effects and Foley, sources or re-records music cues, and mixes a new fully-filled M&E so a legacy film can be dubbed.','M&E Version',ARRAY['M&E track','International Foley','Full dubbing','Room tone','Localization','Indirect dubbing']::text[],ARRAY['Assuming a stereo or final mix with dialogue can substitute for a true dialogue-free M&E.','Recreating effects that do not match the original''s level, tone, or perspective.','Leaving gaps where production effects were tied to dialogue, so the dub has missing sounds.']::text[],ARRAY['Preparing an old catalog film for streaming dubs when no M&E exists.','Restoring an archival title whose international track was lost or damaged.','Rebuilding effects and Foley so a legacy series can be localized worldwide.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='799d056f-747f-5c92-bb13-c159d3ec563c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('International-version reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '799d056f-747f-5c92-bb13-c159d3ec563c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='799d056f-747f-5c92-bb13-c159d3ec563c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c4fe341b-7e82-52b7-adca-ff56a87ce53b','Isochrony','A type of dubbing synchrony in which the translated utterance is made to match the duration of the original on-screen delivery, so the dubbed line begins and ends with the character''s speech and its internal pauses coincide. It is one of Chaume''s three synchronization constraints, alongside lip (phonetic) synchrony and kinesic synchrony.','Isochrony means the new line lasts as long as the old one. It starts and stops with the actor''s speech. Think of pouring new words into a cup that must not overflow.','It keeps the dub believable by ensuring translated lines fit the exact time the character''s mouth is moving, so voice and picture start and stop together.','A dubbing translator lengthens or shortens a line''s wording so it fills the same on-screen duration, and the actor delivers it to start and end with the original speech.','Synchronization',ARRAY['Lip sync','Full dubbing','Internal-sync error','Guide-track dependency','Functional equivalence','Kinesic synchrony']::text[],ARRAY['Writing a translation that is too long or short for the time the character speaks.','Matching only the start of a line and letting the end run past or fall short of the picture.','Ignoring pauses in the original, so the dubbed rhythm no longer lines up with the delivery.']::text[],ARRAY['Adapting a wordy source line to fit a short on-screen utterance.','Timing a dubbed reply to begin and end exactly with the actor''s speech.','Fitting translated dialogue to pauses and beats in the original performance.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c4fe341b-7e82-52b7-adca-ff56a87ce53b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Isochrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c4fe341b-7e82-52b7-adca-ff56a87ce53b','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c4fe341b-7e82-52b7-adca-ff56a87ce53b' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e4473c1b-34cf-5d73-880a-986f4c4b60a3','Kinetic synchrony','In dubbing, kinesic synchrony (also called gestural synchrony) is the type of synchronization that matches the translated, re-voiced dialogue to the on-screen actor''s body movements, gestures and performance, so the new dialogue does not contradict what the viewer sees. It is one of the three classic dubbing synchronies, alongside lip synchrony (phonetic sync) and isochrony. ''Kinetic synchrony'' is a non-standard variant name for the same concept.','Kinetic synchrony means the new voice track must fit what the actor''s body is doing. If a character shrugs or points, the dubbed words should match that action. It stops the sound and the picture from telling different stories.','It keeps the localized dialogue believable by aligning speech with visible actions, gestures and emotion, so viewers accept the dub as the character''s own voice.','An adapter and dub director shape line timing and stress so a nod, hand gesture or head turn lands on the matching word during recording.','Synchronization',ARRAY['Lip sync','Isochrony','Line-by-line dubbing','Linguistic director']::text[],ARRAY['Confusing kinetic synchrony with lip sync; lip sync matches mouth shapes while kinetic synchrony matches body movement and gesture.','Writing a line that fits the mouth but contradicts the actor''s visible gesture or emotion.','Ignoring reaction beats, so a gesture happens with no matching word or stress.']::text[],ARRAY['Adapting a line so a character''s pointing gesture lands on the right word.','Directing an actor to place a laugh or sigh where the on-screen body moves.','Reworking a translation because the first version clashed with a visible shrug.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e4473c1b-34cf-5d73-880a-986f4c4b60a3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kinetic synchrony'),'[^a-z0-9]','','g'));
