INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2b970c24-31a1-5861-9111-847acbeb4879','Kinship-term localization','The adaptation of words denoting family relationships or relationship-based forms of address (for example Japanese onii-san, Korean oppa, or Chinese ge/jie) when the target language lacks a direct equivalent, using strategies such as literal translation, substitution with a character''s name, or cultural naturalization.','Some languages have special words for family roles, like older brother or aunt. Other languages just use names instead. Kinship-term localization is choosing how to handle those words so the meaning still feels natural.','It preserves the social relationships, respect and hierarchy signalled by kinship words while keeping the target dialogue natural and easy to follow.','A translator or language supervisor decides whether to keep, replace or drop terms like ''senpai'' or ''oppa'' so the relationship reads clearly to the local audience.','Linguistic Adaptation',ARRAY['Language supervisor','Linguistic QC','Linguistic director','Line-by-line dubbing','Lip sync']::text[],ARRAY['Translating a kinship term literally when the target culture would simply use the character''s name.','Dropping the respect or hierarchy that the original term signalled.','Being inconsistent, translating the same relationship term differently across episodes.']::text[],ARRAY['Deciding how to render Japanese honorific kinship terms in an English or Spanish dub.','Keeping a character''s form of address consistent across a whole series.','Adapting a scene where a term of address reveals a plot twist about who is related.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2b970c24-31a1-5861-9111-847acbeb4879' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kinship-term localization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2b970c24-31a1-5861-9111-847acbeb4879','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2b970c24-31a1-5861-9111-847acbeb4879' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5dc063ad-76bd-54be-871e-5492a579b2df','Language supervisor','In dubbing and localization, the person responsible for overseeing the linguistic accuracy, consistency and quality of the translated and adapted dialogue across a title, aligning terminology, character voices and style with the client''s language guidelines.','A language supervisor checks that the translated dialogue is correct and consistent. They make sure names, terms and tone stay the same across every episode. Think of them as the language quality lead for the whole project.','The role exists to keep a large, multi-person localization consistent and accurate, catching translation errors and style drift before recording and delivery.','They review scripts and recordings, maintain glossaries and style guides, and give notes to translators, adapters and the dub director.','Localization Roles',ARRAY['Linguistic director','Linguistic QC','Kinship-term localization','Line-by-line dubbing','Lectoring']::text[],ARRAY['Confusing the language supervisor with the dub director; the director leads performance while the supervisor guards linguistic accuracy.','Skipping a central glossary, so terms and names drift between episodes.','Signing off on a script without checking it against the on-screen action and client style guide.']::text[],ARRAY['Keeping character names and invented terms consistent across a multi-season series.','Reviewing a translated script before it goes to the recording studio.','Resolving a disagreement between the translator and adapter over a key term.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5dc063ad-76bd-54be-871e-5492a579b2df' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language supervisor'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5dc063ad-76bd-54be-871e-5492a579b2df','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5dc063ad-76bd-54be-871e-5492a579b2df' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b82e0876-43f4-5eae-b4aa-8b3d81144d63','Language-bearing effort','In dubbing and dialogue post, a vocal ''effort'' (a short non-dialogue vocal sound such as a grunt, gasp, yell or exertion) that nonetheless carries language-specific or intelligible-word content, and therefore must be re-recorded or adapted in each localized version rather than reused from the original mix.','An ''effort'' is a small voice sound like a grunt, gasp or groan. A language-bearing effort has an actual word or language sound inside it. Because of that, each dubbed version has to record it again.','Identifying these efforts tells the team which small vocal sounds cannot simply be kept from the original, because they would sound foreign or wrong in the target language.','During spotting, the editor flags efforts that contain words or language-specific sounds so the dub actor re-records them instead of leaving the original.','Non-verbal Vocals',ARRAY['Language-neutral effort','Language-neutral vocalization','Line-by-line dubbing','Kinetic synchrony','Linguistic QC']::text[],ARRAY['Assuming every grunt or breath is language-neutral and reusable; some carry words and must be re-dubbed.','Leaving an original-language effort in the mix so it clashes with the dubbed voice.','Forgetting to spot and list these efforts before the recording session.']::text[],ARRAY['Spotting a fight scene where grunts contain short shouted words.','Deciding which vocal sounds a dub actor must re-record for a new language.','Checking that no original-language exclamations remain under the dubbed track.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b82e0876-43f4-5eae-b4aa-8b3d81144d63' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language-bearing effort'),'[^a-z0-9]','','g'));
