INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a96b1055-f0f0-54d4-add9-a34a896ac41c','Language-neutral effort','A vocal ''effort'' (a short non-dialogue vocal sound such as a breath, grunt, gasp or exertion) that carries no language-specific content and sounds the same across languages, so it can be retained from the original recording, typically living in the music-and-effects (M&E) track and inherited by every localized version.','This is a small voice sound, like a breath or grunt, that has no real words in it. Because it sounds the same in any language, the team can keep the original. It does not need to be dubbed again.','Recognizing language-neutral efforts saves recording time and preserves the original performance, since these sounds work in every language version.','The editor keeps these efforts in the M&E track so every localized dub inherits the same breaths, grunts and exertions without re-recording.','Non-verbal Vocals',ARRAY['Language-bearing effort','Language-neutral vocalization','Kinetic synchrony','Line-by-line dubbing','Linguistic QC']::text[],ARRAY['Re-recording breaths and grunts that could simply be kept from the original.','Placing language-neutral efforts on the dialogue stem instead of the M&E track.','Assuming a sound is neutral without checking that it contains no words.']::text[],ARRAY['Keeping a character''s breaths and grunts identical across all dubbed languages.','Building an M&E track that holds reusable non-verbal vocal sounds.','Deciding a laugh can stay from the original because it carries no words.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a96b1055-f0f0-54d4-add9-a34a896ac41c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language-neutral effort'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a96b1055-f0f0-54d4-add9-a34a896ac41c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a96b1055-f0f0-54d4-add9-a34a896ac41c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '80fd0677-7205-506d-b02a-fc3d7969c8a2','Language-neutral vocalization','A non-verbal vocal sound produced by a performer (such as a laugh, cry, scream, sigh, breath or grunt) that contains no language-specific words and is understood across cultures, so it generally needs no translation and can be retained from the original in a localized version.','This is a voice sound with no words, like a laugh, cry or scream. People everywhere understand it the same way. So it usually does not need to be translated or dubbed again.','Classifying these sounds as language-neutral lets the team decide what to keep from the original and what to re-record, protecting both performance and budget.','An editor or language supervisor marks laughs, cries and screams that can stay from the original rather than being re-voiced for each language.','Non-verbal Vocals',ARRAY['Language-neutral effort','Language-bearing effort','Kinetic synchrony','Lip sync','Linguistic QC']::text[],ARRAY['Treating every vocal sound as needing a dub, wasting session time on universal sounds.','Confusing a language-neutral laugh with a laughed word that carries meaning.','Removing original vocalizations and leaving gaps the dub never fills.']::text[],ARRAY['Keeping an original scream or laugh in every language version.','Deciding whether a sob carries a spoken word or is purely non-verbal.','Building a checklist of which vocal sounds to re-record versus retain.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='80fd0677-7205-506d-b02a-fc3d7969c8a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language-neutral vocalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '80fd0677-7205-506d-b02a-fc3d7969c8a2','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='80fd0677-7205-506d-b02a-fc3d7969c8a2' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69010c2e-71bb-5620-a6cd-fbb6129c543d','Lectoring','A voice-over translation mode, characteristic of Poland and several Eastern European countries, in which a single narrator (the ''lektor'') reads the entire translated dialogue in a neutral, unemotional tone over the audible, lowered original soundtrack, without attempting lip sync.','Lectoring is a way of translating film for TV. One narrator calmly reads all the lines over the original sound, which stays quiet in the background. You can still hear the real actors underneath.','It offers a cheaper, faster alternative to full dubbing while keeping the original performances audible, which many audiences in those regions prefer.','A studio records one lektor reading a timed script over the mixed original, then balances the two so both the narration and the original voices are audible.','Localization Mode',ARRAY['Language supervisor','Linguistic QC','Isochrony','Line-by-line dubbing','Linguistic director']::text[],ARRAY['Confusing lectoring with dubbing; lectoring keeps the original audible and uses one neutral narrator.','Having the lektor over-act; the delivery is meant to be neutral and even.','Covering the original dialogue completely instead of leaving it audible underneath.']::text[],ARRAY['Preparing a Polish TV version of a foreign film with a single narrator.','Timing a lektor script so narration starts just after each original line begins.','Choosing lectoring over dubbing to cut localization cost and time.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69010c2e-71bb-5620-a6cd-fbb6129c543d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lectoring'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69010c2e-71bb-5620-a6cd-fbb6129c543d','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69010c2e-71bb-5620-a6cd-fbb6129c543d' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1c1eeb26-5b88-5d0e-a71f-473dee86afa6','Line-by-line dubbing','A dubbing recording method in which the localized dialogue is recorded and synchronized one line (or short take/loop) at a time, the actor repeating and refining each line against the picture until sync and performance are correct before moving on to the next.','Line-by-line dubbing means recording just one line at a time. The actor repeats that line until it matches the picture and sounds right. Then they move on to the next line.','Working in small units gives tight control over lip sync, timing and performance, and makes retakes quick without redoing a whole scene.','In the booth, the dub director loops each line so the actor can nail sync and delivery before the engineer records the next one.','Recording Method',ARRAY['Kinetic synchrony','Lip sync','Isochrony','Linguistic director','Lectoring']::text[],ARRAY['Losing the emotional flow of a scene by recording lines in isolation without context.','Not checking each line against the picture, so sync drifts across the scene.','Failing to match energy between separately recorded lines, causing an uneven performance.']::text[],ARRAY['Recording a dialogue-heavy scene one line at a time for precise sync.','Punching in a single replacement line without redoing the whole take.','Directing an actor through short loops to match difficult lip movements.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1c1eeb26-5b88-5d0e-a71f-473dee86afa6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Line-by-line dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1c1eeb26-5b88-5d0e-a71f-473dee86afa6','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1c1eeb26-5b88-5d0e-a71f-473dee86afa6' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fbe138e0-02ac-53dc-bcc8-65fbcfd2f10a','Linguistic QC','Linguistic quality control (also called linguistic quality assurance, or LQA): the systematic review of translated and localized content against defined criteria (accuracy, terminology, grammar, style, consistency and adherence to client guidelines) to detect, classify and correct language errors before delivery.','Linguistic QC is a careful language check on the finished translation. Reviewers look for wrong meanings, spelling, tone and consistency. They fix the language problems before the work is delivered.','It exists to catch translation and adaptation errors and enforce consistency and client style, protecting the quality of the released localization.','A reviewer scores the localized script or dub against an error typology, logs issues by type and severity, and sends corrections back before sign-off.','Quality Control',ARRAY['Language supervisor','Linguistic director','Kinship-term localization','Lectoring','Language-bearing effort']::text[],ARRAY['Treating linguistic QC as only spell-checking rather than checking meaning, terminology and consistency.','Skipping QC against the on-screen context, so lines are correct on paper but wrong for the scene.','Not logging error type and severity, so the same mistakes repeat across a project.']::text[],ARRAY['Reviewing a translated dub script against a terminology glossary before recording.','Scoring a localized episode for accuracy and style before delivery to a streamer.','Catching an inconsistent character name across episodes during a final check.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fbe138e0-02ac-53dc-bcc8-65fbcfd2f10a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Linguistic QC'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fbe138e0-02ac-53dc-bcc8-65fbcfd2f10a','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fbe138e0-02ac-53dc-bcc8-65fbcfd2f10a' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fae3dc09-7f24-5df6-aa89-b2bba349b022','Linguistic director','In dubbing, the person who directs the linguistic and performance aspects of the localized recording, guiding voice actors on pronunciation, meaning, phrasing and delivery so the adapted dialogue is accurate, natural and well synchronized; in many workflows this role overlaps with the dubbing (artistic) director.','A linguistic director guides the actors during dubbing. They make sure the words are said correctly and sound natural. They also check the meaning is right while the lines are recorded.','The role protects linguistic accuracy and natural delivery in the booth, bridging the translated script and the actors'' performances.','During sessions they correct pronunciation, adjust phrasing for sync, and confirm that each line''s meaning matches the original.','Localization Roles',ARRAY['Language supervisor','Linguistic QC','Kinetic synchrony','Line-by-line dubbing','Lip sync']::text[],ARRAY['Assuming the linguistic director only fixes wording and ignores timing and sync.','Overriding the adapter''s carefully timed lines without checking lip and kinetic sync.','Failing to keep pronunciation of names and terms consistent across sessions.']::text[],ARRAY['Coaching a voice actor on the correct pronunciation of foreign names.','Adjusting a line in the booth so both the meaning and the sync work.','Ensuring consistent delivery of a recurring catchphrase across episodes.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fae3dc09-7f24-5df6-aa89-b2bba349b022' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Linguistic director'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fae3dc09-7f24-5df6-aa89-b2bba349b022','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fae3dc09-7f24-5df6-aa89-b2bba349b022' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b0625921-2400-5223-9afc-dcedd1f87309','Lip synchrony','In dubbing, the type of synchronization in which the translated, re-recorded dialogue is matched to the visible articulatory movements of the on-screen actor, particularly the bilabial consonants (/p/, /b/, /m/) and open vowels that are most conspicuous in close-ups and semi-close-ups. Also called phonetic synchrony, it is one of the visual synchronies of dubbing alongside isochrony and kinesic synchrony.','Lip synchrony means the dubbed voice fits the actor''s mouth. When the lips close on screen, the new words should use a closed sound too. It is like matching fresh speech to a silent clip of moving lips.','It preserves the illusion that the actor is really speaking the target language, keeping the audience immersed rather than distracted by a voice that visibly does not match the mouth.','A dialogue adapter and dubbing director reshape lines so that closed and rounded mouth shapes fall on the same frames as the original, especially in tight shots where the mouth is clearly visible.','Synchronization',ARRAY['Lip-sync adaptation','Isochrony','Kinesic synchrony','Lip-sync defect','ADR','Dubbing']::text[],ARRAY['Treating lip synchrony as the only synchrony and ignoring isochrony (line length) and gesture matching.','Chasing exact mouth shapes on wide or off-screen shots where the mouth is not clearly visible.','Sacrificing meaning or natural phrasing just to place a matching consonant on a single frame.']::text[],ARRAY['Adapting a translated close-up line so a bilabial lands where the character''s lips press together.','Directing a voice actor to match the open vowel in a shouted word seen in a tight shot.','Reviewing a dubbed take against picture to confirm mouth shapes align before printing it.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b0625921-2400-5223-9afc-dcedd1f87309' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b0625921-2400-5223-9afc-dcedd1f87309','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b0625921-2400-5223-9afc-dcedd1f87309' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a083edc4-73fc-5415-886c-5e345148d964','Lip-sync adaptation','The stage of the dubbing process in which a dialogue writer (adapter) reworks a literal translation into speakable target-language lines that satisfy the synchronies of dubbing — lip (phonetic) synchrony, isochrony (matching the duration of each utterance), and kinesic synchrony (matching gestures) — while preserving meaning, register, and natural delivery.','This is the step where a writer reshapes the translated lines. The new words must fit the actor''s mouth and the time on screen. It is like trimming a caption so it fits a fixed space.','It turns a raw translation into a performable dubbing script, so the recorded voice matches the picture in shape and timing and still sounds like real speech.','The adapter watches each take, counts syllables against the original, and swaps words or phrasing so line length and key mouth shapes line up before the actor records.','Synchronization',ARRAY['Lip synchrony','Isochrony','Kinesic synchrony','Dubbing','ADR','Loop preparation']::text[],ARRAY['Adapting for lip shapes so aggressively that the line stops sounding like natural speech.','Ignoring isochrony, so the dubbed line runs longer or shorter than the actor''s on-screen mouth movement.','Adapting only from the script without watching picture, missing pauses, breaths, and reactions.']::text[],ARRAY['Rewriting a translated sitcom scene so each line fits the actor''s mouth and timing.','Shortening a wordy translated sentence to match a brief on-screen utterance.','Handing a synced, speakable dubbing script to the studio before a recording session.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a083edc4-73fc-5415-886c-5e345148d964' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip-sync adaptation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a083edc4-73fc-5415-886c-5e345148d964','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a083edc4-73fc-5415-886c-5e345148d964' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf2ff2ea-a566-548f-9146-716547a00bda','Lip-sync defect','A perceptible loss of synchronization between an audio program and its picture, in which speech is heard noticeably earlier or later than the corresponding lip movement. Broadcast practice sets tolerance windows for this relative timing; ITU-R BT.1359 gives an acceptability range of roughly audio leading video by no more than about 90 ms to audio lagging by no more than about 185 ms, with detectability beginning near +45 ms lead to -125 ms lag.','A lip-sync defect is when the voice and the lips do not line up in time. The sound comes too early or too late for the mouth. Even a small gap can make a video feel wrong to viewers.','Naming and measuring the defect lets engineers set and check timing limits, so audio and video stay aligned through editing, encoding, and playout.','An operator measures A/V offset against standard tolerance windows and adds audio or video delay to bring speech back into alignment with the picture.','Synchronization',ARRAY['Lip synchrony','Isochrony','Timecode','Local-language mix','M&E check','Sync']::text[],ARRAY['Assuming any offset is fine because a single viewer did not notice it, ignoring standard tolerance limits.','Confusing a dubbing adaptation mismatch with a true timing offset in the signal chain.','Correcting only one direction of error and forgetting that audio can lead as well as lag.']::text[],ARRAY['Diagnosing why dialogue drifts ahead of the picture after a format conversion.','Checking a delivered file against broadcast A/V sync tolerances before air.','Adding audio delay to fix speech that lags the mouth on a live feed.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf2ff2ea-a566-548f-9146-716547a00bda' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip-sync defect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bf2ff2ea-a566-548f-9146-716547a00bda','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bf2ff2ea-a566-548f-9146-716547a00bda' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f1405d2-1390-5883-898e-0d6a95ad9bc6','Local-language mix','The final re-recorded soundtrack for a target territory, created by combining the fully-filled music-and-effects (M&E) stem with the newly recorded target-language dialogue so that the localized version matches the original mix in balance, level, and dynamics. It is delivered as the print master for that language.','This is the final sound mix in the new language. It blends the dubbed voices with the music and effects track. The goal is to sound just like the first mix, but in another language.','It produces a broadcast- or streaming-ready soundtrack in the target language, letting audiences hear the program in their own language with the original music and effects intact.','A re-recording mixer lays the dubbed dialogue over the M&E, matches its level and reverb to the original, and delivers the language print master to loudness spec.','Mixing',ARRAY['M&E check','Localization premix','Dubbing','Print master','Loudness normalization','Local-language dialogue']::text[],ARRAY['Mixing the dubbed dialogue louder or drier than the original, so it sits on top of the scene instead of in it.','Delivering without matching the program to the required integrated loudness target.','Forgetting to fill an M&E gap, so a hole appears where original production sound used to be.']::text[],ARRAY['Combining recorded German dialogue with the M&E to build the German print master.','Matching a dubbed line''s reverb to the room in the original scene.','Delivering a localized 5.1 mix that meets the platform''s loudness specification.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f1405d2-1390-5883-898e-0d6a95ad9bc6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Local-language mix'),'[^a-z0-9]','','g'));
