WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f1405d2-1390-5883-898e-0d6a95ad9bc6' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd619b94b-37c5-567d-a721-2ad879561c8c','Locale fallback','In localization and internationalization, the ordered rule by which a system substitutes a related locale when content or data for a requested locale is unavailable, traversing from the most specific identifier toward a parent or root (for example es-MX to es to a root default). Locale identifiers follow BCP 47 / ISO 639 conventions, and fallback chains are defined in resources such as the Unicode CLDR.','A locale is a language plus a region, like Mexican Spanish. Locale fallback is a backup rule. If the exact version is missing, the system uses the closest one instead.','It guarantees that a user always receives usable content by degrading gracefully to a broader or default locale rather than failing when an exact match is missing.','A localization engineer configures a fallback chain so a request for a specific regional dub or subtitle resolves to a parent language track when the exact locale is not available.','Localization Workflow',ARRAY['Locale splitting','Localization artifact','Language code','Subtitle track','Dubbing','Local-language mix']::text[],ARRAY['Assuming a regional locale will always fall back to the intended parent without configuring the chain.','Confusing language-only codes (es) with region-specific locales (es-MX) when building fallbacks.','Providing no root default, so a missing locale returns nothing instead of a safe substitute.']::text[],ARRAY['Serving European Portuguese to a viewer when a Brazilian Portuguese dub is not available.','Resolving a UI string to a parent language when the exact locale file is missing.','Mapping a rare regional request to a broader language track on a streaming platform.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d619b94b-37c5-567d-a721-2ad879561c8c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Locale fallback'),'[^a-z0-9]','','g'));
