INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6e092e78-0c52-5e0e-b7b2-08917e1a4177','Localization artifact','Any audible flaw introduced into a program by the dubbing or localization process rather than present in the original — for example residual original-language dialogue left in the M&E, a level or room-tone mismatch where dubbed lines replace production sound, or sync drift between the new dialogue and picture. It is a defect the audience can perceive that betrays the localized version as a replacement.','An artifact is a flaw left behind by the dubbing work. Examples are a bit of the old voice or a sudden change in room sound. It is a mistake the audience can hear.','Naming these flaws helps editors and QC staff listen for and remove the tell-tale signs of localization, keeping the dubbed version seamless.','A QC operator flags leftover original dialogue, mismatched backgrounds, or timing drift so the mix team can patch the M&E or re-align the dubbed line.','Quality Control',ARRAY['M&E check','Localization premix','Lip-sync defect','Local-language mix','Room tone','Dubbing']::text[],ARRAY['Assuming a fully-filled M&E has no leftover dialogue without listening through with the guide muted.','Leaving a room-tone or level jump where a dubbed line replaces the original production sound.','Blaming the recording when the flaw was actually created downstream in the localization mix.']::text[],ARRAY['Catching a word of the original language bleeding through a fully-filled M&E.','Hearing the background drop out under a dubbed line where production sound was removed.','Reviewing a localized episode for tone and level mismatches before delivery.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6e092e78-0c52-5e0e-b7b2-08917e1a4177' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Localization artifact'),'[^a-z0-9]','','g'));
