SELECT '6e092e78-0c52-5e0e-b7b2-08917e1a4177','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6e092e78-0c52-5e0e-b7b2-08917e1a4177' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd4e98517-05c7-5c89-834e-a20e79d8a1a2','Localization premix','An intermediate mix stage in the dubbing workflow in which the newly recorded target-language dialogue is edited, leveled, and balanced together as a group — with edits, EQ, de-essing, and reverb applied — before it is combined with the M&E stem in the final local-language mix. It parallels the dialogue premix of an original-language production.','A premix is a rough combine of sound done before the final mix. In dubbing, the new voices get balanced together first. This makes the last mixing step faster and cleaner.','It consolidates and smooths the dubbed dialogue so the final re-recording mixer receives clean, consistent voices to place against the music and effects.','A dialogue editor cleans and levels the dubbed lines, adds matching reverb, and delivers a dialogue premix that the mixer folds into the M&E.','Mixing',ARRAY['Local-language mix','M&E check','Dubbing','Dialogue premix','Room tone','Loop preparation']::text[],ARRAY['Skipping the premix and trying to balance raw dubbed takes during the final mix.','Baking heavy reverb or EQ into the premix that cannot be undone at the final stage.','Leaving edit clicks or level jumps in the premix that then surface in the finished mix.']::text[],ARRAY['Cleaning and leveling recorded dub takes before the final re-recording session.','Matching the reverb of dubbed lines to the original scene at the premix stage.','Delivering a consolidated dialogue premix to the mixer for a localized episode.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d4e98517-05c7-5c89-834e-a20e79d8a1a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Localization premix'),'[^a-z0-9]','','g'));
