SELECT 'd4e98517-05c7-5c89-834e-a20e79d8a1a2','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d4e98517-05c7-5c89-834e-a20e79d8a1a2' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a7d56171-e408-5b12-88bc-476230fc230f','Loop boundary','The in and out points that delimit a single recording loop (take) in ADR or dubbing — the frames at which a segmented unit of dialogue begins and ends. Boundaries are placed at natural speech breaks such as sentence ends, breaths, or pauses so each loop can be rehearsed and recorded cleanly.','A loop is one short chunk of dialogue for recording. The loop boundary is where that chunk starts and stops. Editors pick these points at natural pauses, like the end of a sentence.','Well-chosen boundaries let an actor start and stop on natural breaks, making each loop easy to perform, sync, and edit back into the scene.','An ADR editor sets loop in and out points at pauses, so the pre-roll cue and the recorded take fall on clean gaps rather than mid-word.','Looping/ADR',ARRAY['Loop unit','Loop length','Loop preparation','ADR','Timecode','Dubbing']::text[],ARRAY['Placing a boundary mid-word or mid-breath, making the take hard to sync and edit.','Making loops span too much dialogue so no clean start and stop points exist.','Ignoring picture cuts and overlaps when choosing where a loop begins and ends.']::text[],ARRAY['Setting in and out points for an ADR line at the surrounding pauses.','Splitting a long speech into loops that each end on a natural break.','Aligning loop boundaries with picture so cues land where the actor can start cleanly.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a7d56171-e408-5b12-88bc-476230fc230f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Loop boundary'),'[^a-z0-9]','','g'));
