SELECT 'a7d56171-e408-5b12-88bc-476230fc230f','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a7d56171-e408-5b12-88bc-476230fc230f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7263f742-ffed-5936-90e1-abe7d57103b5','Loop length','The duration of a single recording loop (take) in ADR or dubbing — how much dialogue, typically a phrase or a sentence or two, is grouped into one unit for the performer to watch, rehearse, and record in a single pass. Loops are kept short to keep the line easy to match to picture.','A loop is one short piece of dialogue set aside to record. Loop length is how long that piece is. Short loops are easier for an actor to watch and match.','Keeping loops short limits how much the performer must remember and sync at once, improving accuracy and speeding up the recording session.','An ADR editor sizes each loop to a manageable phrase, splitting long speeches so the actor can nail timing and lip sync take after take.','Looping/ADR',ARRAY['Loop unit','Loop boundary','Loop preparation','ADR','Isochrony','Dubbing']::text[],ARRAY['Making loops so long the actor cannot hold sync and performance across the whole take.','Cutting loops so short that natural phrasing and momentum are lost between takes.','Sizing loops by script line rather than by what the performer can comfortably match to picture.']::text[],ARRAY['Breaking a monologue into short loops for an ADR session.','Choosing loop length so a performer can match rapid dialogue to the mouth.','Estimating session time from the number and length of loops in a reel.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7263f742-ffed-5936-90e1-abe7d57103b5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Loop length'),'[^a-z0-9]','','g'));
