INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a8270943-016e-5181-9ca8-92cfbe4494f3','Loop preparation','The pre-session work of segmenting a program into recording loops for ADR or dubbing and building the cues that drive the session — dividing dialogue into units, setting loop boundaries, generating streamers/beeps or on-screen cues, and preparing the script and timecodes so the performer can rehearse and record each line to picture.','This is the setup work done before dubbing recording starts. The show is split into short chunks, each with a cue and a time. Good prep helps the recording session run fast and smoothly.','Thorough preparation lets a recording session flow efficiently, giving the performer clear cues and clean loops so time in the studio is spent recording, not organizing.','An ADR editor lists lines, sets loop in/out points, generates cue beeps or streamers, and prints a marked script before the actor arrives.','Looping/ADR',ARRAY['Loop unit','Loop length','Loop boundary','ADR','Lip-sync adaptation','Dubbing']::text[],ARRAY['Arriving at the session with loops and cues unprepared, wasting expensive studio time.','Setting cues with wrong or drifting timecode so the performer''s beeps do not match picture.','Failing to divide dense dialogue into workable loops before the actor starts recording.']::text[],ARRAY['Building an ADR cue sheet and loop list for an upcoming session.','Generating streamers and beeps so an actor knows exactly when to speak.','Preparing a marked dubbing script with timecodes ahead of a recording day.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a8270943-016e-5181-9ca8-92cfbe4494f3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Loop preparation'),'[^a-z0-9]','','g'));
