WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a8270943-016e-5181-9ca8-92cfbe4494f3' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '694e912b-060d-502c-b324-c9dc540a485c','Loop unit','A single segmented chunk of dialogue treated as one take in ADR or dubbing — the basic unit into which a reel or program is divided for recording, historically a short repeating film loop of the scene. The performer watches, rehearses, and records one loop unit at a time before moving to the next.','A loop unit is one short chunk of dialogue recorded at a time. The whole show is broken into many of these small pieces. Working in small pieces helps the actor match the picture.','Dividing dialogue into discrete units lets a performer focus on matching one short passage at a time, and lets editors track, record, and manage lines systematically.','An ADR editor numbers each loop unit on the cue sheet, and the actor records them one by one until the reel is complete.','Looping/ADR',ARRAY['Loop length','Loop boundary','Loop preparation','ADR','Dubbing','Lip synchrony']::text[],ARRAY['Confusing a loop unit with a whole scene rather than one short recording chunk.','Packing too many lines into one unit so it can no longer be matched in a single pass.','Losing track of which loop units are recorded, leaving gaps in the session.']::text[],ARRAY['Numbering each dialogue chunk as a loop unit on an ADR cue sheet.','Recording loop units one at a time until a reel is fully covered.','Splitting a long argument scene into many loop units for the dub session.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='694e912b-060d-502c-b324-c9dc540a485c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Loop unit'),'[^a-z0-9]','','g'));
