INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '43ae9200-be73-56e4-9863-6f724b3d2882','M&E check','A quality-control pass that verifies a music-and-effects (M&E) stem is complete and usable for dubbing — confirming it is fully filled (all music, effects, foley, backgrounds/walla, and production effects present), free of original-language dialogue, and plays without gaps when the original dialogue is removed and the stem is auditioned against picture.','M&E means music and effects, the sound without the talking. An M&E check makes sure this track is complete. You mute the old voices and listen for gaps or leftover words.','It ensures a foreign dub can be built on the M&E with no missing sounds and no original dialogue bleeding through, protecting the localized soundtrack''s quality.','A QC operator plays the M&E against the reference picture with the dialogue guide muted, listening for holes where production sound is missing and for any leftover original speech.','Quality Control',ARRAY['M&E checker','Localization artifact','Local-language mix','Local-language dialogue','Room tone','Print master']::text[],ARRAY['Assuming an M&E is fully filled without auditioning it against picture with the guide muted.','Missing leftover original dialogue riding under a loud music or effects cue.','Overlooking gaps where production effects were pulled out with the dialogue and never refilled.']::text[],ARRAY['Auditioning a delivered M&E against picture before sending it out for dubbing.','Confirming a fully-filled M&E has no holes where production sound was removed.','Checking an M&E for stray original-language words before localization begins.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='43ae9200-be73-56e4-9863-6f724b3d2882' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E check'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '43ae9200-be73-56e4-9863-6f724b3d2882','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='43ae9200-be73-56e4-9863-6f724b3d2882' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f81a3e04-6f8a-5eb4-9771-d8fa39e99728','M&E checker','The person or role responsible for performing the M&E check — auditioning a music-and-effects stem against picture to confirm it is fully filled, free of original-language dialogue, and gap-free, and flagging any missing sounds or leftover dialogue so they can be corrected before the stem is used for dubbing.','This is the person who checks the music and effects track. They make sure no old dialogue is left in and no sound is missing. Their work lets other countries dub the show cleanly.','The role provides a dedicated quality gate on the M&E, catching completeness and dialogue-leakage problems before they reach costly dubbing and mixing stages.','The M&E checker plays each reel with the dialogue guide muted, notes timecodes of holes or stray dialogue, and returns a report to the mix team for fixes.','Quality Control',ARRAY['M&E check','Localization artifact','Local-language mix','Dubbing','Print master','Room tone']::text[],ARRAY['Signing off an M&E after a fast listen instead of a full reel-by-reel check against picture.','Logging a defect without a precise timecode, so the mixer cannot locate the problem.','Checking only for gaps, and so missing leftover original dialogue hidden under effects.']::text[],ARRAY['Reviewing each reel of a delivered M&E and logging holes by timecode.','Flagging stray original dialogue in an M&E before a dub is commissioned.','Returning an M&E QC report to the re-recording mixer for corrections.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f81a3e04-6f8a-5eb4-9771-d8fa39e99728' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E checker'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f81a3e04-6f8a-5eb4-9771-d8fa39e99728','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f81a3e04-6f8a-5eb4-9771-d8fa39e99728' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bd0bd08b-6552-5562-a071-edb96e648aa6','M&E deficiency','A shortfall in a Music and Effects (M&E) track in which non-dialogue elements are missing, incomplete, or not fully recreated, so the track cannot stand alone beneath a replacement dialogue track. Typical deficiencies are absent dialogue-derived sounds such as vocal efforts, breaths, walla, footsteps, and prop foley that lived only under the original dialogue stem.','M and E stands for the music and effects track. It holds every sound except the spoken lines. A deficiency means some of those sounds are missing. Then the track cannot stand on its own for a new language.','Flagging a deficiency tells the post team that the M&E is not yet a fully-filled deliverable and will leave audible gaps once foreign dialogue replaces the original. It exists so localization problems are caught before dubbing rather than after.','A QC editor screens the M&E against the print master and lists each missing effort, footstep, or effect as a deficiency to be filled before the track ships for dubbing.','M&E Deliverables',ARRAY['M&E fill cue','M&E repair','M&E supplementation','Fully-filled M&E','Dialogue stem','Print master']::text[],ARRAY['Assuming a stereo or 5.1 M&E is complete without checking for dialogue-derived sounds that were never recreated.','Confusing a deficiency (missing content) with a level or panning error in an otherwise complete track.','Only checking under dialogue lines and missing efforts, walla, or foley hidden by the original speech.']::text[],ARRAY['QC of an archival M&E before a title is licensed for foreign-language dubbing.','Preparing a legacy film whose original M&E lacks recreated foley and efforts.','Vetting a nonfiction M&E where interview walla and room sound were left out.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bd0bd08b-6552-5562-a071-edb96e648aa6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E deficiency'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bd0bd08b-6552-5562-a071-edb96e648aa6','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bd0bd08b-6552-5562-a071-edb96e648aa6' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee92bf01-6266-5e22-a430-035f0082abb4','M&E fill cue','A marked point in the timeline indicating where a sound must be added to the Music and Effects (M&E) track to cover a non-dialogue element that originally existed only under the production dialogue. The cue directs an editor or foley team to recreate the missing effort, movement, or effect so the M&E is fully filled.','A fill cue marks a spot where a sound must be added to the M and E track. M and E means music and effects. The added sound covers a noise the original actor made. This keeps the track whole when new voices replace the old ones.','It communicates exactly where and what to fill so the M&E stands alone under any dubbed language. The cue turns a vague deficiency into an actionable spotting note for the fill session.','While spotting an M&E, the editor drops a fill cue at each on-screen footstep, kiss, or grunt that lives only under dialogue, then foley or library effects are cut to those cues.','M&E Deliverables',ARRAY['M&E deficiency','M&E supplementation','Foley','Walla','Spotting session','Fully-filled M&E']::text[],ARRAY['Placing a fill cue but not specifying which sound is missing, leaving the fill editor to guess.','Missing cues for subtle mouth or clothing sounds that only surface once the dialogue is muted.','Cueing a fill in the wrong spot so the added sound drifts out of sync with the picture.']::text[],ARRAY['Spotting an M&E for fill before a foley session.','Marking missing efforts on a fight scene for recreation.','Building a fill list to hand to a foley artist for a localization deliverable.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee92bf01-6266-5e22-a430-035f0082abb4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E fill cue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ee92bf01-6266-5e22-a430-035f0082abb4','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee92bf01-6266-5e22-a430-035f0082abb4' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '52929fe1-7804-5419-bf5b-46f05569d3b4','M&E repair','The corrective work of fixing a deficient Music and Effects (M&E) track by recreating or replacing missing, damaged, or dialogue-contaminated non-dialogue elements so it becomes a clean, fully-filled deliverable. Repair covers refilling gaps, removing bleed of original dialogue, and matching added material to the original mix.','This is the work of fixing a music and effects track that is missing sounds. M and E means music and effects. The team adds back the parts that are absent. This makes the track ready for dubbing into other languages.','It rescues an M&E that would otherwise leave holes or expose original dialogue when a new language is dubbed in. Repair exists to make older or faulty tracks usable for current localization needs.','A post house receives a legacy M&E with dialogue bleed and gaps, then re-foleys efforts, patches with library effects, and de-bleeds contaminated sections to restore it.','M&E Deliverables',ARRAY['M&E deficiency','M&E fill cue','M&E supplementation','Foley','Dialogue stem','Fully-filled M&E']::text[],ARRAY['Patching gaps with effects that do not match the perspective or reverb of the original mix.','Leaving traces of original dialogue bleed inside the repaired M&E.','Repairing levels but ignoring that key foley or walla is still absent.']::text[],ARRAY['Restoring an old M&E that contains dialogue leakage before re-licensing.','Fixing an M&E flagged with deficiencies during localization QC.','Rebuilding damaged effects passages on an archival title for streaming delivery.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='52929fe1-7804-5419-bf5b-46f05569d3b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E repair'),'[^a-z0-9]','','g'));
