INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0947f861-545b-5639-909a-7043510d55e7','M&E supplementation','The process of adding supplementary non-dialogue material to a Music and Effects (M&E) track so it fully covers every sound the original dialogue masked. It supplies recreated efforts, walla, foley, and effects, sometimes delivered as optional or fill tracks alongside the core M&E.','This means adding extra sounds to a music and effects track. M and E means music and effects. The new sounds fill gaps so nothing is missing. A full track then lets a show be voiced in many languages.','It brings an incomplete M&E up to a fully-filled standard so no gaps appear when foreign dialogue is placed over it. Supplementation exists to guarantee a seamless soundtrack in every dubbed version.','An editor builds optional fill tracks of efforts and walla, then folds them into the M&E so the track plays complete without the original voices.','M&E Deliverables',ARRAY['M&E deficiency','M&E fill cue','M&E repair','Walla','Optional tracks','Fully-filled M&E']::text[],ARRAY['Adding supplementary effects at levels that do not sit correctly against the existing music and effects.','Supplementing only obvious sounds and skipping quiet efforts, breaths, or clothing movement.','Delivering fill material out of sync with the reference picture.']::text[],ARRAY['Building optional fill stems for a title that needs a fully-filled M&E.','Adding crowd walla to a stadium scene missing from the original M&E.','Completing an M&E for a streaming platform''s dubbing pipeline.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0947f861-545b-5639-909a-7043510d55e7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E supplementation'),'[^a-z0-9]','','g'));
