INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '42a5c233-fb80-56a6-a9fc-38948903bb31','Market-specific versioning','The creation of distinct edited or localized versions of a title tailored to a particular territory or market, differing in content, language, censorship, or cultural adaptation from the original or from versions for other markets. Versions may vary in picture edits, on-screen text, dialogue adaptation, and delivered assets.','This means making a special version of a show for one region. Editors may cut or change scenes to fit local rules or taste. On-screen words and dialogue can be adapted too. Each market can get its own edit.','It lets one title meet different legal, cultural, and platform requirements around the world without changing the master for everyone. Versioning exists so content can ship globally while respecting local standards.','A localization producer tracks which shots, text cards, and dialogue lines change per territory and orders the matching picture and audio conforms for each market version.','Localization Workflow',ARRAY['Multilingual dubbing','M&E supplementation','Native-listener QC','Conform','Subtitling','Textless elements']::text[],ARRAY['Assuming one dubbed audio track fits every market when censorship or picture edits differ.','Letting version edits drift out of conform so audio no longer lines up with the altered picture.','Forgetting to re-version on-screen text and graphics along with the dialogue.']::text[],ARRAY['Preparing a broadcast cut with edits required by a specific country''s content rules.','Delivering airline and theatrical versions of the same film with different content.','Managing multiple regional edits of a series across streaming territories.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='42a5c233-fb80-56a6-a9fc-38948903bb31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Market-specific versioning'),'[^a-z0-9]','','g'));
