INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ac802e5c-86c0-5ba1-b303-ab74ee416c00','Mix-localization defect','A fault in a localized (dubbed) mix where the replacement dialogue is poorly balanced against the Music and Effects track, producing wrong levels, panning, perspective, or tonal match relative to the original. It is a mix-domain defect, distinct from translation or lip-sync errors.','This is a sound flaw in a dubbed mix. The new voices may be too loud, too soft, or badly blended. It makes the dubbed show sound wrong next to the music and effects.','Naming it as a mix defect directs the fix to the re-recording mixer rather than to the translator or dubbing director. It exists so localization QC can route problems to the right craft stage.','During dub QC a reviewer flags a scene where dubbed dialogue sits too far forward over the M&E, and the mixer rebalances the level and reverb to match the original.','Localization QC',ARRAY['Naturalness defect','Native-listener QC','M&E deficiency','Print master','Loudness normalization','Dialogue stem']::text[],ARRAY['Blaming the translation when the real problem is dialogue level and perspective in the mix.','Delivering a dub whose loudness does not conform to the platform''s target after localization.','Ignoring reverb and room match so the dubbed voice sounds detached from the scene.']::text[],ARRAY['QC of a dubbed episode where voices sit unnaturally loud over the score.','Fixing a localized mix that fails a platform''s loudness specification.','Reviewing perspective match on a dubbed exterior scene.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ac802e5c-86c0-5ba1-b303-ab74ee416c00' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mix-localization defect'),'[^a-z0-9]','','g'));
