SELECT 'ac802e5c-86c0-5ba1-b303-ab74ee416c00','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ac802e5c-86c0-5ba1-b303-ab74ee416c00' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9904197c-1c26-5378-a90d-6e9d72c73840','Mouth-closure violation','A lip-sync error in dubbing in which the replacement audio produces an open-mouth sound while the on-screen actor''s mouth is closed, breaking phonetic synchrony at bilabial articulations. It commonly occurs when a dubbed line fails to place a closed-mouth consonant (p, b, m) where the picture shows the lips meeting.','This is a lip-sync error in dubbing. The new voice makes an open-mouth sound while the actor''s mouth is shut on screen. The eye and ear do not match, so it looks fake.','The concept exists so adapters and dubbing directors respect the visible closed-mouth moments that anchor believable lip sync. Flagging a violation targets the exact frames where synchrony breaks down.','A dubbing director watching close-ups rejects a take whose vowel plays over a frame where the actor''s lips are pressed together, and asks the adapter to reword so a p, b, or m lands there.','Dubbing Sync',ARRAY['Nonverbal sync','Isochrony','Lip sync','Phonetic synchrony','Naturalness defect','Adaptation']::text[],ARRAY['Matching only line length (isochrony) while ignoring visible closed-mouth consonants in close-ups.','Assuming lip sync matters only for wide shots, so bilabial mismatches slip through on close-ups.','Rewording for meaning without checking where the actor''s lips actually meet on screen.']::text[],ARRAY['Directing a dub take over a tight close-up of a speaking actor.','QC of a dubbed scene where a word starts on a closed-mouth frame.','Adapting a script so bilabial consonants fall on visible lip closures.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9904197c-1c26-5378-a90d-6e9d72c73840' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mouth-closure violation'),'[^a-z0-9]','','g'));
