INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd37d3302-b28a-55c2-bee3-54276c1174aa','Multilingual dubbing','The production of dubbed versions of a single title in several target languages, each with its own translated and adapted script, cast of voice actors, and localized dialogue mix built over a shared Music and Effects track. It is a revoicing mode in which the original dialogue is fully replaced in every language served.','This means voicing one show in many languages. A separate cast records the lines for each language. They mix their voices over the same music and effects track. Viewers around the world hear the show in their own tongue.','It lets one title reach audiences across many territories in their native languages from a common set of localization assets. Multilingual dubbing exists to maximise global reach while preserving the original music and effects.','A streaming platform orders dubs in a dozen languages, each studio recording its cast against the same M&E and reference picture, then delivering a language-specific print master.','Dubbing Modes',ARRAY['One-voice dubbing','Narration replacement','Market-specific versioning','M&E deficiency','Native-listener QC','Isochrony']::text[],ARRAY['Believing every language dubs cleanly over the same M&E without checking each for deficiencies.','Reusing one language''s adaptation timing for another, causing sync problems.','Overlooking that each language needs its own native-listener QC pass.']::text[],ARRAY['Localizing a streaming series into many languages for a global launch.','Managing parallel dubbing studios working from one set of assets.','Delivering language-specific print masters for a worldwide film release.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d37d3302-b28a-55c2-bee3-54276c1174aa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Multilingual dubbing'),'[^a-z0-9]','','g'));
