INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd52ee4a6-10f4-5409-8198-f20d8c515abc','Narration replacement','The revoicing of a program''s narration or voice-over commentary into another language by recording a new narrator reading the translated script, while the picture and underlying Music and Effects remain unchanged. Unlike character dubbing, it typically has no on-screen lip movement to match, so timing follows the narration''s pacing and picture cues.','This means swapping a show''s spoken narration for a new language. A new voice reads the same guiding text. The pictures stay the same while the words change. Because you rarely see the narrator, exact lip sync is not needed.','It localizes documentaries, reality, and factual content where an unseen narrator carries information rather than character dialogue. Narration replacement exists so factual programming can be understood in any language without full character dubbing.','For a nature documentary, a localization studio times a new narrator to the picture cues and lays the read over the original M&E in place of the source narration.','Revoicing',ARRAY['Multilingual dubbing','One-voice dubbing','M&E deficiency','Isochrony','Native-listener QC','Voice-over translation']::text[],ARRAY['Letting the new narration drift off the picture cues it is meant to describe.','Ignoring pace so the translated read runs long and crowds the next shot.','Assuming no sync matters, when narration still must land on the events it references.']::text[],ARRAY['Localizing a wildlife documentary''s narration into several languages.','Replacing a reality show''s voice-over commentary for a foreign market.','Revoicing a museum or corporate video narration.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d52ee4a6-10f4-5409-8198-f20d8c515abc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Narration replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd52ee4a6-10f4-5409-8198-f20d8c515abc','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d52ee4a6-10f4-5409-8198-f20d8c515abc' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9f92c501-de94-58ea-80a7-359fcd0abd62','Native-listener QC','A quality-control pass on a dubbed or localized deliverable performed by a reviewer who is a native speaker of the target language, evaluating linguistic accuracy, naturalness, pronunciation, and audible sync from the perspective of the intended audience. It complements technical QC by catching errors a non-native ear would miss.','QC means quality control, a final check for mistakes. Here a person who grew up speaking the target language listens. They catch odd wording, wrong stress, and sync errors. A non-native ear would miss these.','It ensures the localized version reads as authentic to the audience it is made for, not just technically correct. Native-listener QC exists because fluency and cultural instinct are needed to judge naturalness and register.','A native-speaking QC operator screens a finished dub, logging mispronunciations, awkward phrasing, and noticeable sync as FYI, Issue, or Blocker notes for the studio to address.','Localization QC',ARRAY['Naturalness defect','Mix-localization defect','Multilingual dubbing','Market-specific versioning','Mouth-closure violation','Voice-over translation']::text[],ARRAY['Relying only on technical QC and skipping a native-speaker linguistic pass.','Using a fluent non-native reviewer who misses subtle register and idiom errors.','Treating every native note as a blocker instead of triaging by severity.']::text[],ARRAY['Final linguistic QC of a dub before a streaming platform accepts it.','Catching a mistranslated idiom that a non-native reviewer approved.','Reviewing pronunciation of names and places in a localized program.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9f92c501-de94-58ea-80a7-359fcd0abd62' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Native-listener QC'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9f92c501-de94-58ea-80a7-359fcd0abd62','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9f92c501-de94-58ea-80a7-359fcd0abd62' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4ee4f760-02c7-5720-822d-8990e14975df','Naturalness defect','A quality fault in dubbed dialogue where the delivery sounds stilted, mistranslated in register, or prosodically unnatural, breaking the audience''s acceptance of the performance. It reflects a failure of the dubbing''s ''prefabricated orality'' to read as credible speech, often from source-language interference or wrong stress and rhythm.','This is when dubbed speech does not sound natural. The lines may feel stiff, oddly worded, or wrongly stressed. Viewers notice it and it breaks the spell of the scene.','Naming it as a naturalness fault directs fixes to adaptation, performance, and direction rather than raw translation. The concept exists so QC can judge believability, not just literal accuracy.','In dub QC a native reviewer flags a line that is grammatically correct but sounds like translated text, and the studio reworks the adaptation or re-records the take.','Localization QC',ARRAY['Native-listener QC','Mix-localization defect','Mouth-closure violation','Isochrony','Adaptation','Prefabricated orality']::text[],ARRAY['Approving a line because it is accurate word-for-word while it sounds unnatural aloud.','Copying source-language sentence structure so the dub keeps foreign rhythm.','Ignoring wrong stress and intonation that make a correct translation sound wooden.']::text[],ARRAY['QC of a dub where dialogue reads like a literal translation.','Reworking stilted lines flagged by a native-listener review.','Directing a re-take to make delivery sound more spontaneous.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4ee4f760-02c7-5720-822d-8990e14975df' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Naturalness defect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4ee4f760-02c7-5720-822d-8990e14975df','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4ee4f760-02c7-5720-822d-8990e14975df' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a267eb6e-b618-52eb-9355-cc70bab0d139','Nonverbal sync','The alignment of non-lexical vocal sounds, such as breaths, efforts, grunts, laughs, sighs, and reactions, with the on-screen actor''s visible movements when dubbing a new language. These paralinguistic elements must fall exactly where the body produces them, since they are cued by picture rather than by translated words.','This is matching non-word sounds in dubbing. Things like breaths, grunts, laughs, and effort noises must line up. They should fall exactly where the actor makes them on screen.','It keeps a dubbed performance believable at moments where sound comes from the body, not from speech. Nonverbal sync exists because a mistimed grunt or breath reads as wrong even when the spoken lines are perfect.','When recording a dub, the voice actor watches the picture and places each effort and breath on the actor''s punch, fall, or gasp so the body and sound agree.','Dubbing Sync',ARRAY['Mouth-closure violation','Isochrony','Lip sync','Efforts','Kinesic synchrony','M&E fill cue']::text[],ARRAY['Focusing on spoken lines and letting breaths and efforts drift out of sync.','Skipping nonverbal sounds entirely so a physical scene feels lifeless.','Placing a reaction sound a beat off from the on-screen action that causes it.']::text[],ARRAY['Dubbing a fight scene full of grunts and impacts.','Recording breaths and efforts for a physically demanding performance.','Syncing laughter and reactions in a comedy dub.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a267eb6e-b618-52eb-9355-cc70bab0d139' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nonverbal sync'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a267eb6e-b618-52eb-9355-cc70bab0d139','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a267eb6e-b618-52eb-9355-cc70bab0d139' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '482d6ef9-bb61-5aef-996b-84af1a2dc882','One-voice dubbing','A revoicing mode in which a single narrator reads the translated lines for all characters over the original soundtrack, which remains faintly audible beneath the read. Known as lektor in Poland and related to Gavrilov-style voice-over, it makes little attempt at lip sync or character differentiation.','Here one narrator reads all the parts over the original sound. You still hear the first voices faintly underneath. Lip sync is not the goal. It is common on television in Poland and parts of Eastern Europe.','It offers a fast, low-cost way to localize content when full multi-actor dubbing is too expensive or not culturally expected. One-voice dubbing exists as an established alternative to both lip-sync dubbing and subtitling.','A broadcaster commissions a single lektor to record a flat, even read of the whole script, which an engineer lays over a duck of the original audio.','Dubbing Modes',ARRAY['Multilingual dubbing','Narration replacement','Voice-over translation','Isochrony','Subtitling','M&E deficiency']::text[],ARRAY['Confusing one-voice dubbing with full lip-sync dubbing that replaces the soundtrack entirely.','Ducking the original audio so far that its emotion and effects are lost.','Expecting character voices or tight lip sync from a mode that uses neither.']::text[],ARRAY['Localizing television films for Polish broadcast with a lektor.','Producing a low-budget voice-over translation for factual content.','Comparing localization options where subtitling or one-voice read is cheaper than full dubbing.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='482d6ef9-bb61-5aef-996b-84af1a2dc882' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('One-voice dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '482d6ef9-bb61-5aef-996b-84af1a2dc882','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='482d6ef9-bb61-5aef-996b-84af1a2dc882' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eb5fec41-3b5a-5e56-b2b6-04de90043f4e','Open-vowel matching','A lip-synchrony technique in dubbing in which the target-language adaptation is written and timed so that open vowels — those articulated with the jaw markedly lowered and the mouth visibly wide, such as /a/ and /ɑː/ — fall on the frames where the on-screen actor''s mouth is seen fully open. It exploits the fact that open vowels form a highly visible viseme, so aligning them helps preserve the illusion that the character is speaking the dubbed words.','Some vowels, like the ''ah'' sound, make the mouth open wide. This trick lines up those wide-mouth sounds with the moments the actor''s mouth looks open on screen. That helps the dub look real.','It targets the most visible mouth shapes so limited sync effort is spent where the audience most easily spots a mismatch, keeping close-up dialogue believable.','A dubbing adapter rewrites a line so a wide ''ah'' vowel lands on the frame where the actor''s mouth gapes open, rather than forcing a closed sound there.','Lip-sync technique',ARRAY['Phonetic synchrony','Isochrony','Phrase-sync dubbing','Overlength line','Viseme']::text[],ARRAY['Treating open-vowel matching as full lip-sync, when it only addresses the most open mouth shapes and must be combined with bilabial and timing sync.','Forcing an open vowel into the line at the wrong point, which distorts natural word choice and weakens the translation.','Ignoring open vowels in tight close-ups, where a mismatched mouth shape is glaringly obvious to viewers.']::text[],ARRAY['Adapting a shouted close-up line so the character''s wide-open mouth coincides with an ''ah'' vowel in the dubbed text.','Reworking a translated question in a facial close-up to place open vowels on visibly open-mouth frames.','Training dubbing adapters to spot open-vowel opportunities while writing to picture.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eb5fec41-3b5a-5e56-b2b6-04de90043f4e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Open-vowel matching'),'[^a-z0-9]','','g'));
