WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='eb5fec41-3b5a-5e56-b2b6-04de90043f4e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7b185158-df83-58d9-b120-9d283f10a436','Optional track','In localization audio delivery, a separate stem accompanying the fully-filled M&E (music and effects) mix that isolates valuable but language-specific material — such as source-language singing, vocalizations, walla, chants, on-screen source-language dialogue and processed voices — so the dubbing team can choose to retain, replace or omit each element in the target-language mix.','This is an extra audio track sent with a film for dubbing. It holds sounds tied to the first language, like singing, crowd shouts, or humming. The dub team can keep or swap each one.','It keeps language-specific vocal sounds apart from the clean music-and-effects mix, giving the dub mixer control to match the original without those sounds being baked in.','A dubbing mixer pulls a crowd chant or a hummed tune from the optional track to lay under the target-language dialogue when no dubbed replacement is needed.','Localization deliverable',ARRAY['Optional vocal','M&E track','Fully-filled M&E','Original-language guide','Walla']::text[],ARRAY['Confusing the optional track with the M&E; the M&E is meant to be language-neutral, while optionals hold source-language material.','Baking optional vocals into the M&E stem, which forces those source-language sounds into every dubbed version.','Discarding the optional track, then having no source-language singing or walla to fall back on for the dub.']::text[],ARRAY['Delivering a series to a streamer whose spec requires a fully-filled M&E plus a separate optional track.','A dub studio choosing whether to keep the original song vocal from the optional track or record a translated version.','QC checking that stray breaths and efforts sit on the optional track and not in the M&E.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7b185158-df83-58d9-b120-9d283f10a436' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optional track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7b185158-df83-58d9-b120-9d283f10a436','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7b185158-df83-58d9-b120-9d283f10a436' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '09118390-6200-5c67-9dba-d8cd8577354c','Optional vocal','A vocal element — typically source-language singing, humming, chants, or non-verbal vocalizations such as efforts, breaths, laughs and cries — supplied on the optional track of a localization delivery, flagged as ''optional'' because the target-language team decides case by case whether to keep the original vocal, replace it with a dubbed version, or drop it.','This is a voice sound, like singing or humming, sent as an extra. The dubbing team gets to choose what to do with it. They can keep it, redo it in the new language, or leave it out.','It gives the localization team a ready source-language vocal they can reuse or swap, so decisions about songs and vocal sounds are not locked in by the original mix.','When a character sings on screen, the dub supervisor decides whether the optional vocal stays in the original language or is re-recorded, depending on whether the lyrics carry story meaning.','Localization deliverable',ARRAY['Optional track','M&E track','Original-language guide','Partial dubbing','Walla']::text[],ARRAY['Assuming every optional vocal must be dubbed; many, like background singing, are best left in the original language.','Leaving story-critical sung lyrics undubbed, so target-language viewers miss plot information.','Filing optional vocals into the M&E instead of the optional track, removing the team''s choice to replace them.']::text[],ARRAY['Deciding whether an on-screen song''s optional vocal is translated or kept for a new dub.','Reusing crowd cheers from the optional vocals rather than recording fresh group ADR.','A QC operator verifying that character vocalizations were delivered as optional vocals.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='09118390-6200-5c67-9dba-d8cd8577354c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optional vocal'),'[^a-z0-9]','','g'));
