SELECT '09118390-6200-5c67-9dba-d8cd8577354c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='09118390-6200-5c67-9dba-d8cd8577354c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '522ddb0b-15e2-57a3-9b8c-298367a99b68','Original-language guide','A reference recording or track of the source-language dialogue and its timing supplied to the dubbing team so voice actors, adapters and the dubbing director can hear the original performance — its rhythm, intonation, pauses and sync points — while writing, cueing and recording the target-language replacement.','This is a copy of the original spoken lines, kept as a guide. Voice actors and the director listen to it while they work. It shows them the timing, feeling, and pace to match.','It preserves the original performance as a benchmark so the dub matches its pacing, emotion and sync rather than drifting into a free re-performance.','In the booth, a dub actor listens to the original-language guide on headphones to copy the timing and delivery of each line before their take is recorded.','Localization deliverable',ARRAY['Optional track','Phonetic synchrony','Isochrony','Performance-equivalence casting','Overlength line']::text[],ARRAY['Treating the original-language guide as the final mix reference; it is a performance guide, not a track meant to be heard in the dub.','Ignoring the guide''s pauses and rhythm, producing a dub that no longer matches the original timing.','Losing the guide''s sync points, so the replaced line drifts off the picture.']::text[],ARRAY['A voice actor matching breath and pace to the original-language guide during a dub take.','An adapter timing a translated line against the original-language guide to keep isochrony.','A dubbing director referencing the guide to preserve the emotional beats of the source performance.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='522ddb0b-15e2-57a3-9b8c-298367a99b68' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Original-language guide'),'[^a-z0-9]','','g'));
