SELECT '522ddb0b-15e2-57a3-9b8c-298367a99b68','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='522ddb0b-15e2-57a3-9b8c-298367a99b68' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '812cc965-2d49-5774-868c-f1c86d93bb08','Overlength line','In dubbing adaptation, a translated or adapted line whose spoken duration exceeds the time available in the original utterance — the interval between the character''s visible mouth opening and closing — thereby breaking isochrony and forcing the delivered line to run past the original''s start or end points.','This is a dubbed line that takes too long to say. The new words run past the moment the actor''s mouth stops moving. The adapter must cut or reshape it to fit.','Flagging a line as overlength signals that it breaks the timing fit required for believable dubbing, so it can be shortened before recording.','An adapter marks an overlength line, then trims words or picks shorter synonyms so the delivered take ends when the on-screen mouth closes.','Sync error',ARRAY['Isochrony','Phonetic synchrony','Phrase-sync dubbing','Open-vowel matching','Original-language guide']::text[],ARRAY['Prioritizing a complete literal translation over timing, leaving a line too long to sync.','Fixing overlength by speeding up delivery unnaturally instead of rewriting the line.','Assuming off-screen lines can be any length; even off-camera, an overlength line breaks isochrony with the scene.']::text[],ARRAY['Trimming an overlength translated sentence so it fits a short on-screen reaction.','A dubbing director rejecting a take because the line ran past the character''s mouth close.','Adaptation QC flagging overlength lines before the recording session.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='812cc965-2d49-5774-868c-f1c86d93bb08' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overlength line'),'[^a-z0-9]','','g'));
