INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4ea0d015-0234-50c1-be92-8f2da5605d89','Partial dubbing','A revoicing mode in which a spoken target-language translation is added to the original soundtrack to convey only the necessary information, without fully replacing the original dialogue; the added speech is typically fitted into the original''s silent or pause periods. Also called half-dubbing or concise synchronisation, it is a reduced form distinct from full (total) dubbing.','Here only some of the speech is dubbed, not all of it. A short translation is added over the original sound. It usually drops into the quiet gaps between the first-language lines.','It offers a cheaper, faster way to make content understandable in another language when full lip-synced dubbing is not needed or affordable.','A studio uses partial dubbing to voice only key lines of an interview or corporate video, slotting the translation into pauses while the original stays partly audible.','Revoicing mode',ARRAY['Voice-over','Pivot-language dubbing','Phrase-sync dubbing','Optional vocal','Original-language guide']::text[],ARRAY['Confusing partial dubbing with voice-over; partial dubbing uses the original''s silent gaps rather than talking over live dialogue.','Expecting lip-sync from partial dubbing, which does not aim to match mouth movements.','Using partial dubbing for drama, where its lower verisimilitude breaks immersion compared with full dubbing.']::text[],ARRAY['Localizing a documentary interview by adding translated speech in the original''s pauses.','A low-budget release using partial dubbing instead of full lip-sync dubbing.','Conveying only essential plot lines in a foreign-language insert via partial dubbing.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4ea0d015-0234-50c1-be92-8f2da5605d89' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Partial dubbing'),'[^a-z0-9]','','g'));
