SELECT '4ea0d015-0234-50c1-be92-8f2da5605d89','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4ea0d015-0234-50c1-be92-8f2da5605d89' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2d01cfd9-9ae5-541d-84f9-d11725e09fd5','Performance-equivalence casting','The practice of casting dub voice actors whose vocal qualities and acting match the original performers — voice age, gender, timbre, character and emotional delivery — so the target-language performance is perceived as equivalent to the original rather than merely a literal reading of the lines.','This means picking dub actors whose voices fit the original ones. The aim is a similar age, tone, and acting style. The goal is a match in feel, not just the words.','It preserves character believability and the original''s emotional impact, keeping audiences immersed in the dubbed version.','A dubbing director auditions and casts a voice actor whose timbre and acting range recreate the on-screen character''s presence in the target language.','Voice casting',ARRAY['Original-language guide','Phonetic synchrony','Isochrony','Pragmatic equivalence','Overlength line']::text[],ARRAY['Chasing an exact timbre clone at the expense of performance quality; a strong equivalent performance matters more than a perfect voice copy.','Casting a voice whose apparent age or gender clashes with the on-screen character.','Recasting a distinctive established character without checking the vocal match still holds.']::text[],ARRAY['Casting a target-language voice for a lead so it matches the original actor''s age and tone.','A dubbing director choosing between a closer voice match and a stronger performance.','Recasting a recurring character to keep performance equivalence across a series'' seasons.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2d01cfd9-9ae5-541d-84f9-d11725e09fd5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Performance-equivalence casting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2d01cfd9-9ae5-541d-84f9-d11725e09fd5','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2d01cfd9-9ae5-541d-84f9-d11725e09fd5' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6eec67c4-cd73-5030-b5f2-5385006dce47','Perspective defect','A flaw in which the acoustic perspective of a dubbed or replaced line — its apparent distance, room reflection and off-axis coloration — fails to match the shot''s framing and space, so a wide or distant shot carries close, dry, on-axis dialogue (or the reverse), breaking the illusion that the sound belongs in the pictured environment.','Sound should seem to come from where the person stands on screen. A far shot needs a more distant, roomy voice. When the voice sounds too close and dry for the picture, that mismatch is the defect.','Naming this defect flags a break in sound-to-picture realism so the mixer can add distance cues — level, reverb and tone — to reseat the voice in its space.','A re-recording mixer spots a perspective defect where booth-recorded dub dialogue sounds too close for a wide exterior, then adds room reflection and matching tone to place it in the scene.','Acoustic defect',ARRAY['Performance-equivalence casting','Phonetic synchrony','Original-language guide','Optional track','Room tone']::text[],ARRAY['Recording all dub lines dry and close, ignoring that distant or off-screen shots need matching perspective.','Adding reverb by ear without matching the original scene''s actual space, creating a new mismatch.','Fixing perspective with level alone, when tone and reflections also cue distance.']::text[],ARRAY['Matching a dubbed line to a wide shot where the character is far from camera.','Reseating booth-dry dialogue into a reverberant on-screen hallway.','QC catching a perspective defect where close dub audio sits on a distant framing.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6eec67c4-cd73-5030-b5f2-5385006dce47' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Perspective defect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6eec67c4-cd73-5030-b5f2-5385006dce47','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6eec67c4-cd73-5030-b5f2-5385006dce47' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1649b05f-61b0-5769-8ef1-9ef8adf09b77','Phonetic synchrony','Also termed lip synchrony, the type of dubbing synchronization concerned with matching the target-language dialogue to the articulatory (mouth) movements visible on screen, especially the most perceptible visemes — bilabial and labiodental consonants (/p/, /b/, /m/, /f/) and open vowels — so that the dubbed sounds appear to issue from the character''s lips.','This is matching the dub to the actor''s mouth shapes. It focuses on the clearest ones, like the lips pressing together for ''b'' or ''m'', and wide-open vowels. Done well, the words look like they fit the lips.','It sustains the illusion that on-screen characters speak the target language, which is essential in close-ups where mouth movements are clearly visible.','An adapter chooses target words placing a lip-closing consonant where the actor''s lips meet on screen, so a close-up reads as in sync.','Synchronization type',ARRAY['Isochrony','Kinesic synchrony','Open-vowel matching','Phrase-sync dubbing','Overlength line']::text[],ARRAY['Chasing phonetic sync on every phoneme instead of just the visible bilabials and open vowels.','Sacrificing accurate translation to force lip matches where the mouth is not clearly seen.','Applying strict phonetic sync to off-screen or distant lines, where isochrony matters more.']::text[],ARRAY['Adapting a close-up line so an ''m'' lands where the character''s lips close.','Reviewing a facial close-up dub for bilabial matches.','Teaching the difference between phonetic synchrony and isochrony in a dubbing course.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1649b05f-61b0-5769-8ef1-9ef8adf09b77' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phonetic synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1649b05f-61b0-5769-8ef1-9ef8adf09b77','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1649b05f-61b0-5769-8ef1-9ef8adf09b77' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b833ac8-81f0-51f1-9b7f-9a5590f06a30','Phrase-sync dubbing','A level of dubbing synchronization in which the target-language dialogue is aligned to the start points, end points and internal pauses of the original speaker''s phrases — matching overall duration and rhythm (isochrony) — without matching individual lip movements; used where lip-sync is not required, such as off-screen speech, distant shots and non-close-up framing.','Here the dub matches the whole phrase, not each mouth movement. The new lines start and stop when the original ones do. It is used when the speaker''s mouth is not shown up close.','It keeps the dub feeling natural and in time with the scene when strict lip-sync is unnecessary, saving effort where the audience cannot see the mouth.','For a narrator or an off-camera character, the adapter times the translated line to begin and end with the original phrase rather than chasing lip shapes.','Synchronization type',ARRAY['Isochrony','Phonetic synchrony','Kinesic synchrony','Partial dubbing','Overlength line']::text[],ARRAY['Applying phrase-sync to a close-up, where visible mouth movements demand phonetic sync.','Letting phrase timing drift, so the dubbed line no longer starts and ends with the original.','Assuming phrase-sync frees the adapter from isochrony; phrase duration still must match.']::text[],ARRAY['Dubbing an off-screen narrator by matching phrase starts and ends.','Syncing a distant-shot conversation where lips are not readable.','Localizing documentary voice segments at phrase level rather than lip level.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b833ac8-81f0-51f1-9b7f-9a5590f06a30' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrase-sync dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0b833ac8-81f0-51f1-9b7f-9a5590f06a30','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0b833ac8-81f0-51f1-9b7f-9a5590f06a30' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4ef74275-3acf-54d5-937d-aa729538e5f1','Pivot-language dubbing','Indirect dubbing in which the target-language version is produced from an intermediate ''pivot'' language template (commonly English) rather than directly from the original dialogue; the original is first translated into the pivot, then the pivot is adapted into each target language by different translators.','The dub is made through a middle language, often English, not straight from the original. First the original is turned into that middle version. Then each new language is made from it.','It lets studios localize into many languages at scale when direct translators for rare language pairs are scarce, by reusing one shared template.','A studio dubbing a Korean series into Polish works from an English pivot template because Korean-to-Polish adapters are hard to find.','Revoicing mode',ARRAY['Partial dubbing','Pragmatic equivalence','Original-language guide','Politeness recalibration','Overlength line','Relay translation']::text[],ARRAY['Trusting the pivot as if it were the original; errors in the pivot spread to every downstream dub.','Losing distinctions absent in the pivot, such as formal or informal address and grammatical gender.','Skipping a source-language check, so cultural nuance and context are misread through the pivot.']::text[],ARRAY['Localizing a Japanese title into many European dubs from an English pivot.','A target-language adapter guessing a politeness level the English pivot did not mark.','Cascading a pivot mistranslation into several dubbed versions.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4ef74275-3acf-54d5-937d-aa729538e5f1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pivot-language dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4ef74275-3acf-54d5-937d-aa729538e5f1','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4ef74275-3acf-54d5-937d-aa729538e5f1' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ed22a06f-361c-505d-91f7-ef2328d227c7','Politeness recalibration','In dubbing and localization, the adjustment of a line''s politeness level, register and forms of address — honorifics, T–V (formal versus informal ''you'') distinctions and deference markers — so that the target-language dialogue conveys the same social relationship and (im)politeness as the original within the norms of the target culture, rather than transferring the source forms literally.','Languages show respect and closeness in different ways. This is changing how polite or casual a line sounds to fit the new language. The goal is the same feeling between the characters.','It preserves character relationships and social nuance that a literal translation would distort, because politeness systems differ sharply between languages.','An adapter dubbing Japanese into English recasts honorific speech as tone, word choice and formality, since English lacks the same honorific system.','Adaptation strategy',ARRAY['Pragmatic equivalence','Pivot-language dubbing','Partial dubbing','Performance-equivalence casting','Original-language guide']::text[],ARRAY['Translating honorifics or formal pronouns literally, producing stilted or wrong social cues.','Flattening all register to neutral, erasing the shifts that mark changing relationships.','Ignoring how a pivot language dropped the original''s formality distinctions.']::text[],ARRAY['Recasting Japanese keigo into English politeness through wording and tone.','Choosing formal versus informal ''you'' when dubbing into a language that marks that distinction.','Marking a character''s shift from formal to familiar address across a dubbed scene.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ed22a06f-361c-505d-91f7-ef2328d227c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Politeness recalibration'),'[^a-z0-9]','','g'));
