WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ed22a06f-361c-505d-91f7-ef2328d227c7' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d059cd6-8d25-5013-9f93-d2751f7d881a','Pragmatic equivalence','In translation theory, equivalence at the level of implied and intended meaning: reproducing in the target text the communicative effect and implicature of the source — what is meant beyond the literal words, given context and convention — rather than only its lexical or grammatical content.','This is matching what a line really means, not just its words. Speech often hints at more than it says. Good translation carries that hidden meaning across, so the point still lands.','It ensures the target audience infers the same meaning, tone and intent as the source audience, which literal word-for-word translation can lose.','A dubbing adapter renders a sarcastic or indirect remark so target viewers grasp the implied meaning, even when the literal words change.','Translation concept',ARRAY['Politeness recalibration','Pivot-language dubbing','Partial dubbing','Performance-equivalence casting','Phonetic synchrony']::text[],ARRAY['Translating words literally and losing the implied meaning, such as irony or a hint.','Assuming pragmatic equivalence means adding explanations; it means recreating the same inference.','Ignoring cultural context, so the target audience draws a different conclusion than intended.']::text[],ARRAY['Adapting an idiom so the dub carries its intended force, not its literal image.','Rendering an indirect request so target viewers read it as a request.','Preserving a joke''s implicature when the literal wording will not work.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d059cd6-8d25-5013-9f93-d2751f7d881a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pragmatic equivalence'),'[^a-z0-9]','','g'));
