INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bce41956-3d8f-5527-81a2-9927e0b0efac','Pronunciation drift','In dubbing and localization, the inconsistent or gradually shifting pronunciation of a recurring proper noun, foreign word, or specialized term across a dubbed program, occurring between different voice actors, episodes, or seasons, so that the same name is voiced in more than one way. It is a continuity error in the target-language audio rather than an error in the translated text.','Pronunciation drift is when the same name is said in different ways across a dubbed show. One actor says a character name one way, and another says it a different way. It breaks the feeling that everyone lives in the same world.','Naming and tracking this problem exists so teams keep every recurring name, place, and term pronounced the same way, protecting continuity and audience immersion.','Dubbing supervisors keep a pronunciation guide and reference recordings so every actor voices recurring names identically across a series.','Continuity & Consistency',ARRAY['Recast continuity','Register drift','Register localization','Revoicing','Dubbing','Localization']::text[],ARRAY['Assuming pronunciation only matters in the written script, when it is the spoken audio that must stay consistent.','Failing to keep a pronunciation guide, so recurring names drift between actors and episodes.','Fixing one line''s pronunciation but leaving earlier recorded lines mismatched.']::text[],ARRAY['A long-running dubbed series where a character''s name is voiced two different ways across seasons.','Recording a new episode months later and matching the established pronunciation of a place name.','Localizing a franchise where invented names must be pronounced consistently across films and spin-offs.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bce41956-3d8f-5527-81a2-9927e0b0efac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pronunciation drift'),'[^a-z0-9]','','g'));
