WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bce41956-3d8f-5527-81a2-9927e0b0efac' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98f3da56-c659-53b3-ae56-9838d8291231','Prosodic phrase alignment','In machine and automatic dubbing, a technique that segments the target-language dialogue into prosodic phrases and positions their boundaries and pauses to match the phrasing and pause structure of the source speaker, so the synthesized or performed target speech follows the same rhythmic grouping as the original. In automatic dubbing it exploits the attention alignment of neural machine translation to find plausible phrase breaks that fit the source timing.','This lines up the pauses in the new language with the pauses in the first speech. The translated words get grouped into chunks that start and stop where the first actor chunks did. That keeps the timing natural against the picture.','It preserves the source utterance''s rhythm and pause placement so the dubbed speech fits the on-screen timing and sounds natural rather than rushed or dragging.','Automatic-dubbing pipelines use it to break a translated line into phrases and set pause lengths before text-to-speech synthesis, so the output matches the original''s cadence.','Synchronization',ARRAY['Prosodic synchrony','Isochrony','Quantitative synchrony','Lip sync','Revoicing','Dubbing']::text[],ARRAY['Confusing phrase alignment, which matches pauses and grouping, with word-for-word timing of every syllable.','Aligning phrase boundaries but ignoring the natural stress inside each phrase.','Assuming it guarantees lip sync, when it mainly handles phrasing and pause timing.']::text[],ARRAY['Building an automatic dubbing system that must match the source speaker''s pauses.','Segmenting a translated line into phrases before text-to-speech synthesis.','Tuning dubbed cadence so pauses land where the original actor paused.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98f3da56-c659-53b3-ae56-9838d8291231' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic phrase alignment'),'[^a-z0-9]','','g'));
