WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98f3da56-c659-53b3-ae56-9838d8291231' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a912d742-52f8-5c80-ab9b-1c6816f4ee53','Prosodic synchrony','Synchronization of the suprasegmental features of the dubbed voice, namely intonation, stress, rhythm, tempo, and pausing, with the on-screen performance and emotional content, so the target-language delivery matches the pitch contours, emphasis, and pacing implied by the original actor''s performance and visible body language.','Prosodic synchrony means matching the music of speech, not just the words. The new voice should rise, fall, stress, and pause like the first actor did. This makes the emotion feel true to what we see on screen.','It ensures the dubbed delivery carries the same emphasis, mood, and pacing as the original so the performance reads as believable and matches the actor''s visible emotion.','A dubbing director coaches actors to place stress, pitch rises, and pauses where the on-screen actor did, so an angry or excited line sounds angry or excited to match the picture.','Synchronization',ARRAY['Prosodic phrase alignment','Qualitative synchrony','Isochrony','Register localization','Dubbing','Revoicing']::text[],ARRAY['Matching the words and lip timing but flattening the intonation, so the emotion no longer fits the picture.','Copying the source pitch exactly instead of using the target language''s natural intonation for the same emotion.','Ignoring pauses and stress, producing a technically synced but lifeless read.']::text[],ARRAY['Directing a dubbed emotional scene so the new voice rises and falls like the original.','Matching a shouted or whispered line''s energy in the target language.','Reviewing a dub where lip sync is fine but the delivery sounds flat against the actor''s face.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a912d742-52f8-5c80-ab9b-1c6816f4ee53' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic synchrony'),'[^a-z0-9]','','g'));
