SELECT 'a912d742-52f8-5c80-ab9b-1c6816f4ee53','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a912d742-52f8-5c80-ab9b-1c6816f4ee53' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d9ac063-a3c0-5d45-85ac-edeb54ea8cfa','Qualitative synchrony','The dimension of phonetic (lip) synchrony concerned with matching the quality of visible articulation, aligning the target dialogue''s clearly visible phonemes, such as bilabials, labiodentals, and rounded or open vowels, with the mouth shapes the on-screen actor makes, especially in close-ups. Also called qualitative lip synchrony, it contrasts with quantitative synchrony, which concerns the number of syllables and duration.','Qualitative synchrony is about matching mouth shapes, not just timing. When a character''s lips press together, the new word should also use a p, b, or m sound. It matters most in close-up shots where we clearly see the mouth.','It keeps the dubbed sounds believable by making visible mouth shapes agree with what is heard, preventing the jarring mismatch of a closed-mouth sound over an open mouth.','A dialogue writer picks target words whose visible consonants and vowels fall on the same mouth shapes as the original, especially on close-ups with lip-closing sounds.','Synchronization',ARRAY['Quantitative synchrony','Prosodic synchrony','Isochrony','Lip sync','Revoicing','Dubbing']::text[],ARRAY['Worrying about visible mouth shapes in wide shots where the mouth is not clearly seen.','Matching timing while ignoring visible lip-closing sounds on close-ups.','Sacrificing the meaning of a line just to hit one visible mouth shape.']::text[],ARRAY['Adapting a close-up line so a lip-closing sound lands where the actor''s lips close.','Choosing target words with matching rounded vowels for a visible pucker.','Reviewing a dub for mismatches between heard sounds and seen mouth shapes.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d9ac063-a3c0-5d45-85ac-edeb54ea8cfa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Qualitative synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d9ac063-a3c0-5d45-85ac-edeb54ea8cfa','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9d9ac063-a3c0-5d45-85ac-edeb54ea8cfa' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00a66699-4f5b-5db8-bd75-f2fc209c6f1e','Quantitative synchrony','The dimension of phonetic (lip) synchrony concerned with matching the quantity of articulation, namely the number of syllables and the overall duration of the target utterance to the on-screen character''s mouth openings and speaking time, so the dubbed line begins and ends with the visible mouth movement. It is closely tied to isochrony and contrasts with qualitative synchrony, which concerns the specific visible phonemes.','Quantitative synchrony is about length and count, not mouth shapes. The new line should have about the same number of beats and last as long as the first. So the voice starts when the mouth opens and stops when it closes.','It makes the dubbed line fill the same on-screen speaking time as the original, so speech does not start before the mouth moves or run on after it stops.','An adaptor counts syllables and checks line length so the translated dialogue fits between the character''s mouth opening and closing.','Synchronization',ARRAY['Qualitative synchrony','Isochrony','Prosodic phrase alignment','Lip sync','Dubbing','Revoicing']::text[],ARRAY['Writing a target line far longer or shorter than the original, so it overruns or falls short of the mouth movement.','Matching syllable count but ignoring where pauses fall inside the line.','Treating it as full lip sync, when it ignores which specific sounds are visible.']::text[],ARRAY['Trimming a wordy translation so it fits the on-screen speaking time.','Matching syllable count to an off-camera or medium-shot line.','Checking that a dubbed line starts and ends with the character''s mouth movement.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00a66699-4f5b-5db8-bd75-f2fc209c6f1e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Quantitative synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '00a66699-4f5b-5db8-bd75-f2fc209c6f1e','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='00a66699-4f5b-5db8-bd75-f2fc209c6f1e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd1076d83-8b83-5b1a-aec0-78e25cc0df0c','Ratings-driven adaptation','Adaptation of dubbed or localized dialogue to meet the content-classification or age-rating requirements of a target territory, for example softening or removing profanity, sexual references, or other sensitive content so the localized version qualifies for a desired rating or complies with local broadcast standards. It is a commercially or ideologically motivated intervention in audiovisual translation.','This is changing dubbed dialogue to fit a country''s content rating. A team might soften strong language or cut adult parts so a show can reach a younger crowd. The goal is to meet the rules or the rating the release needs.','It lets a program meet a target market''s legal, broadcast, or commercial rating requirements so it can be shown to the intended audience.','A localization team softens swear words and adult references in the dubbed script so a film earns a lower age rating in a given country.','Adaptation Strategy',ARRAY['Register localization','Revoicing','Dubbing','Localization','Relay translation','Recast continuity']::text[],ARRAY['Toning down language so far that character voice and meaning are lost.','Assuming one territory''s rating rules apply everywhere instead of checking each market.','Editing the dubbed text but leaving matching on-screen action or subtitles inconsistent.']::text[],ARRAY['Softening profanity in a dub so a film qualifies for a teen rating.','Adjusting sensitive content to meet a national broadcaster''s standards.','Preparing a family-friendly localized version of an adult-oriented original.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d1076d83-8b83-5b1a-aec0-78e25cc0df0c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ratings-driven adaptation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd1076d83-8b83-5b1a-aec0-78e25cc0df0c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d1076d83-8b83-5b1a-aec0-78e25cc0df0c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c4b97c59-5b97-5dff-b5da-c3bc066d3222','Reaction vocal','A non-verbal vocal sound, such as a gasp, sigh, laugh, grunt, groan, or breath, performed and recorded to match an on-screen character''s reaction, as distinct from spoken lines. In dubbing and automated dialogue replacement these efforts and reactions are re-recorded so the target-language track carries the same non-verbal responses as the picture.','A reaction vocal is a sound a character makes that is not a word. Think of a gasp, a laugh, or a grunt when they get hit. Actors record these so the dubbed track still has every reaction we see.','It restores the non-verbal human sounds that sell a character''s reactions, keeping the dubbed track lively and matched to on-screen action.','In an ADR or dubbing session, actors watch the picture and perform breaths, laughs, and efforts so the localized track matches each visible reaction.','Voice Recording',ARRAY['ADR','Revoicing','Dubbing','Walla','Kinesic synchrony','Prosodic synchrony']::text[],ARRAY['Recording only spoken lines and forgetting the breaths, laughs, and efforts a scene needs.','Performing reactions that do not match the timing or intensity of the on-screen action.','Reusing generic reaction sounds that clearly do not fit the character or moment.']::text[],ARRAY['Recording grunts and breaths for a fight scene in a dubbed action film.','Adding a matching laugh or gasp where the original actor reacted.','Filling non-verbal reactions left in gaps between translated lines.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c4b97c59-5b97-5dff-b5da-c3bc066d3222' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reaction vocal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c4b97c59-5b97-5dff-b5da-c3bc066d3222','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c4b97c59-5b97-5dff-b5da-c3bc066d3222' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd5ab8a45-2693-527d-a0f3-7bd76d43b0de','Recast continuity','The maintenance of a consistent vocal identity for a character when the voice performer is replaced (recast) across seasons, sequels, or a franchise, so the new dubbing or voice actor preserves the established timbre, accent, delivery, and characterization closely enough that the audience still accepts it as the same character.','Recast continuity is keeping a character voice steady after the actor changes. A new performer tries to match the old voice tone and style. The goal is that fans still feel it is the same character.','It protects audience immersion and brand consistency when a voice must be replaced, preventing a jarring change in a familiar character''s sound.','When a dub actor leaves a series, the studio casts and coaches a replacement to match the original''s pitch, accent, and delivery across future episodes.','Continuity & Consistency',ARRAY['Pronunciation drift','Register drift','Revoicing','Dubbing','Localization','Register localization']::text[],ARRAY['Casting a replacement on talent alone without matching the established character voice.','Ignoring the original''s accent or speech quirks that fans strongly associate with the character.','Changing a character''s voice mid-season with no bridge, breaking audience belief.']::text[],ARRAY['Replacing a dubbing actor who has left a long-running animated series.','Matching a franchise character''s voice across a new film years later.','Coaching a new performer from reference clips of the original voice.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d5ab8a45-2693-527d-a0f3-7bd76d43b0de' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Recast continuity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd5ab8a45-2693-527d-a0f3-7bd76d43b0de','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d5ab8a45-2693-527d-a0f3-7bd76d43b0de' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82ae0605-15ee-54fa-ac0f-78e935f9e00f','Register drift','The unintended, gradual shift in the level of formality, tone, or style (register) of a character''s dubbed speech away from the register established for that character, so their language becomes inconsistently more formal or more casual over the course of a program. It is a consistency error in adaptation rather than a deliberate register choice.','Register drift is when a character slowly starts talking in a different style by mistake. Someone written as very formal begins using slang, or the other way round. It happens across a long show and makes the character feel off.','Naming this error helps adaptors keep each character''s level of formality steady, protecting characterization and continuity across a long or multi-writer production.','Dubbing script editors track each character''s register with style notes so a formal character does not drift into casual speech between episodes or writers.','Continuity & Consistency',ARRAY['Register localization','Pronunciation drift','Recast continuity','Dubbing','Localization','Ratings-driven adaptation']::text[],ARRAY['Letting a character''s formality change between episodes because different writers adapt them.','Focusing only on accuracy of meaning and overlooking consistency of tone.','Confusing a deliberate character arc in speech with accidental drift.']::text[],ARRAY['Adapting a long series where several writers must keep one character''s tone steady.','Catching a formal character slipping into slang in a later episode.','Reviewing a dub for tone consistency across a full season.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82ae0605-15ee-54fa-ac0f-78e935f9e00f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Register drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82ae0605-15ee-54fa-ac0f-78e935f9e00f','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='82ae0605-15ee-54fa-ac0f-78e935f9e00f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e413e0b8-24e7-5f64-9814-21a5c0003784','Register localization','The adaptation of the register, meaning the level of formality, tenor, style, and sociolect, of source dialogue to the conventions, norms, and audience expectations of the target language and culture, so that a character''s way of speaking produces an equivalent social and stylistic effect for the new audience. It reproduces field, tenor, and mode appropriately rather than translating literal meaning alone.','Register localization means fitting how a character speaks to the new culture. A polite or street-smart way of talking is remade so it feels the same to local viewers. It matches the style, not just the words.','It reproduces the social meaning of a character''s speech, how formal, rough, or refined they sound, for a target audience, so characterization survives translation.','A translator renders a slangy teenager or a formal official using the target language''s own equivalent slang or formal speech rather than a flat literal version.','Adaptation Strategy',ARRAY['Register drift','Ratings-driven adaptation','Localization','Relay translation','Dubbing','Revoicing']::text[],ARRAY['Translating literally and flattening a distinctive register into neutral, standard speech.','Borrowing target-culture slang so specific it feels out of place for the character.','Keeping formality levels from the source that do not carry the same meaning in the target culture.']::text[],ARRAY['Adapting a character''s heavy slang into believable target-language slang.','Localizing formal honorifics that have no direct equivalent.','Deciding how a regional accent''s social meaning should read for a new audience.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e413e0b8-24e7-5f64-9814-21a5c0003784' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Register localization'),'[^a-z0-9]','','g'));
