INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ff2c89bf-45e5-5188-8780-150481a867fc','Relay translation','Translation carried out not from the original source text but from an intermediate (pivot) translation in a third language, for example dubbing or subtitling a Korean film into Finnish by working from an English template rather than from Korean. Also called pivot or indirect translation, the intermediate version becomes the effective source for all downstream languages.','Relay translation means translating from a translation, not the first version. A show made in one language is first put into English. Other teams then work from that English version. It saves time but can lose meaning at each step.','It lets content reach many languages when direct translators for the original language are scarce, by routing every target language through one shared pivot version.','A streaming platform creates an English template from the original, then has translators localize into many languages from that template instead of the source.','Translation Method',ARRAY['Localization','Revoicing','Dubbing','Register localization','Ratings-driven adaptation','Prosodic phrase alignment']::text[],ARRAY['Assuming the pivot version is perfect and copying its errors into every target language.','Losing culture-specific meaning that the pivot version already stripped out or flattened.','Not annotating the pivot template with gender, formality, or plural cues the original had.']::text[],ARRAY['Localizing a Korean series into many languages from an English pivot template.','Dubbing a film whose original language has few available translators.','Building a pivot-language subtitle template as the shared source for all markets.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ff2c89bf-45e5-5188-8780-150481a867fc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Relay translation'),'[^a-z0-9]','','g'));
