INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0d3bc944-3204-53d7-978a-c3d485d4cf89','Revoicing','An umbrella term in audiovisual translation for the modes of oral language transfer that replace or overlay the original speech with a new soundtrack, including lip-sync dubbing, voice-over, narration, and free commentary, as opposed to written transfer such as subtitling. In its narrow sense it denotes substituting the original dialogue track with a newly recorded target-language track.','Revoicing is a general word for replacing the first speech with new spoken audio. It covers dubbing, voice-over, and narration. The other main choice, subtitling, uses written text instead of new voices.','It provides a spoken target-language version of a program for audiences who prefer or need to hear the content in their language rather than read subtitles.','A distributor choosing revoicing over subtitling books studios and actors to record dubbing or voice-over for the target market.','Translation Method',ARRAY['Dubbing','Voice-over','Relay translation','Localization','Register localization','Reaction vocal']::text[],ARRAY['Using revoicing to mean only lip-sync dubbing, when it also covers voice-over and narration.','Treating revoicing and subtitling as interchangeable rather than distinct transfer modes.','Forgetting that voice-over keeps the original audio audible underneath, unlike full dubbing.']::text[],ARRAY['Deciding between revoicing and subtitling for a new market.','Producing a voice-over version of a documentary.','Commissioning a lip-sync dub as one form of revoicing.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0d3bc944-3204-53d7-978a-c3d485d4cf89' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Revoicing'),'[^a-z0-9]','','g'));
