INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c5996e9d-702c-59b1-a0c7-899f39eff4aa','Rhythmographic detection','In the rhythmo-band (bande rythmo) dubbing tradition, the detection phase in which a detector transcribes the source dialogue and marks it, precisely aligned to picture, with dubbing symbols indicating lip movements, labial consonants, mouth openings and closings, breaths, and reactions onto a scrolling band that actors read while performing. It produces the timed rhythmo band used to achieve synchrony during recording.','This is the step that makes the scrolling text strip actors read while dubbing. A specialist writes the lines and marks every mouth move, breath, and pause in time with the picture. Actors then read the strip and stay in sync.','It converts the source performance into a timed, symbol-marked band so voice actors can hit lip movements, pauses, and reactions accurately in real time during recording.','A detector uses rhythmo-band software to lay dialogue and sync marks against the video, giving actors a scrolling guide for exact timing.','Dubbing Workflow',ARRAY['Isochrony','Lip sync','Quantitative synchrony','Dubbing','Revoicing','Reaction vocal']::text[],ARRAY['Treating detection as plain transcription and skipping the lip-movement and breath marks.','Misaligning the band to picture, so actors read slightly early or late.','Leaving out reaction and breath cues, so non-verbal sounds get missed in recording.']::text[],ARRAY['Preparing a rhythmo band for a feature dub in the French or Quebec tradition.','Marking labial consonants and breaths on the band before a recording session.','Using rhythmo-band software to sync a scrolling script to the video for actors.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c5996e9d-702c-59b1-a0c7-899f39eff4aa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rhythmographic detection'),'[^a-z0-9]','','g'));
