INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ee346aa7-b14e-5c29-8ca7-9fba100d5b87','Rushed delivery','A dubbing performance fault in which a translated line is spoken too quickly, usually because the target text is longer than the on-screen time allows and must be crammed to meet isochrony. The result is an unnatural, hurried cadence that fails to match the pacing, breaths, and emphasis of the original performance.','Rushed delivery is when a dubbing actor says a line too fast. They often do this to squeeze the words into a short time slot. The line then sounds hurried and less natural than the original.','Naming the fault helps adapters and directors flag lines that need to be shortened or re-timed, so the dub keeps the natural rhythm and breathing of real speech.','During recording or review, the director spots a crammed line, then trims or rewrites the adaptation so the actor can perform it at a believable pace that still fits the picture.','Performance',ARRAY['Isochrony','Adaptation','Lip sync','Dubbing director','Sync QC','Take']::text[],ARRAY['Writing an adaptation with more syllables than the on-screen time allows, forcing the actor to race.','Prioritizing a literal translation over a shorter phrasing that would fit the timing naturally.','Accepting a rushed take because the words are correct, ignoring that the pacing no longer matches the character.']::text[],ARRAY['A translated line runs long and the actor speeds up to fit the mouth movements.','A tight delivery schedule pressures a session, and hurried takes slip through review.','A fast comedic exchange is over-translated, so every line feels crammed and breathless.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ee346aa7-b14e-5c29-8ca7-9fba100d5b87' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rushed delivery'),'[^a-z0-9]','','g'));
