WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ee346aa7-b14e-5c29-8ca7-9fba100d5b87' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '46c879c8-3aac-5a20-95e5-09534f96a1ca','Selective dubbing','A partial revoicing approach in which only selected portions of a program are dubbed rather than the entire dialogue track — for example, only the main characters, only certain scenes, or only foreign-language passages within an otherwise untranslated soundtrack. It is a form of partial dubbing that sits between full lip-sync dubbing and voice-over.','Selective dubbing means only some voices in a show get dubbed. Maybe just the main characters, or just certain scenes, are redone in the new language. The rest is left as it was.','It lets producers localize the parts that matter most for understanding while saving the time and cost of dubbing every line, or while keeping some original audio for effect.','A studio dubs only the lead roles or the key plot dialogue of a low-budget release, leaving background or minor lines in the original language under the mix.','Revoicing Modes',ARRAY['Partial dubbing','Voice-over','Lip sync','Revoicing','Narration','M&E track']::text[],ARRAY['Confusing selective dubbing with full dubbing, where every character''s dialogue is revoiced.','Leaving essential plot dialogue in the original language, so target viewers miss key information.','Failing to balance dubbed and undubbed lines, producing jarring shifts in language mid-scene.']::text[],ARRAY['A documentary dubs only its on-camera interviews while leaving the narrator or crowd untouched.','A budget release revoices only lead characters and leaves minor roles in the source language.','A film dubs only the foreign-language passages spoken within an otherwise same-language soundtrack.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='46c879c8-3aac-5a20-95e5-09534f96a1ca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Selective dubbing'),'[^a-z0-9]','','g'));
