WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='46c879c8-3aac-5a20-95e5-09534f96a1ca' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0ae8ed3d-4bc7-5df8-b75e-f4aaacec43e8','Semantic drift','The gradual shift of meaning away from the source, in which successive small translation and adaptation choices accumulate so that the target dialogue conveys a sense noticeably different from the original. It borrows the linguistic notion of semantic change (a word''s meaning shifting over time) and applies it to meaning displacement across a localized work.','Semantic drift is when meaning slowly slides away from the original. In dubbing, many small wording choices can add up. Over a whole show, the translated sense can end up different from what was first meant.','Recognizing semantic drift helps translators and reviewers catch cumulative meaning loss, so a character''s intent, jokes, and plot points survive intact across the localized version.','A reviewer comparing the dub against the source spots that a running motif or a character''s stance has quietly shifted over episodes, and corrects the adaptation to restore the intended meaning.','Translation Adaptation',ARRAY['Adaptation','Semantic change','Localization','Register','Sociolect localization','Back-translation']::text[],ARRAY['Treating each line in isolation and missing how small changes accumulate across a whole program.','Assuming a technically correct translation cannot drift, when tone and intent still slide over time.','Confusing deliberate creative adaptation with unintended drift away from the source meaning.']::text[],ARRAY['A long series where a catchphrase is translated slightly differently each time until its meaning shifts.','A reviewer back-checks a dub and finds a character''s motivation has quietly changed from the original.','A franchise localized by different translators over years develops inconsistent, drifting terminology.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0ae8ed3d-4bc7-5df8-b75e-f4aaacec43e8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Semantic drift'),'[^a-z0-9]','','g'));
