SELECT '0ae8ed3d-4bc7-5df8-b75e-f4aaacec43e8','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0ae8ed3d-4bc7-5df8-b75e-f4aaacec43e8' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7e46238-9d82-5053-b856-305f146c52b8','Simil-sync','A revoicing mode positioned between lip-sync dubbing and voice-over, also called lector dubbing or phrase sync, in which the target dialogue respects isochrony — matching the length and timing of each source utterance — but does not attempt phonetic lip synchrony. Like voice-over, it keeps the original soundtrack clearly audible beneath the target-language track; unlike one-voice/lektor dubbing it uses one actor per role, and its phrase-level timing is the same isochrony idea covered by phrase-sync dubbing.','Simil-sync sits between full lip-sync dubbing and voice-over. The new voice matches how long each line lasts. But it does not try to match the exact lip movements on screen.','It offers a faster, cheaper alternative to full lip-sync dubbing while still replacing the original voices, useful where perfect mouth matching is not required.','A studio uses simil-sync for factual programming or lower-budget content, timing each replaced line to the original''s length without crafting phoneme-level lip matches.','Revoicing Modes',ARRAY['Isochrony','Voice-over','Lip sync','Lector dubbing','Kinesic synchrony','Revoicing']::text[],ARRAY['Confusing simil-sync with voice-over, where the original dialogue stays audible underneath.','Expecting phoneme-accurate lip sync from a mode that only matches utterance length.','Ignoring isochrony and letting replaced lines run longer or shorter than the source timing.']::text[],ARRAY['Revoicing a documentary or news report where full lip sync is unnecessary but voices are replaced.','Localizing lower-budget programming that cannot afford full lip-sync dubbing.','Dubbing a language pair where close lip matching is impractical but timing must be kept.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7e46238-9d82-5053-b856-305f146c52b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Simil-sync'),'[^a-z0-9]','','g'));
