INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1699fa2e-873c-5287-a5ca-088555083bc5','Single-character recording','A dubbing recording method in which each character''s lines are recorded separately, with one actor performing alone against the reference picture and guide track, rather than several actors performing together in the same session. Each voice is captured on its own isolated track for clean stems and flexible scheduling.','Single-character recording means one actor records alone. Each character''s lines are taped in a separate session. This keeps every voice on its own clean track and makes scheduling much easier.','It gives the mixer isolated, dialogue-only tracks per character and lets each actor be booked independently, improving control, editing flexibility, and studio logistics.','A dubbing studio schedules each cast member on a different day, recording their character''s loops solo to the picture, then hands the separate tracks to the editor and mixer.','Recording Workflow',ARRAY['Loop','Take','Dialogue stem','ADR','Dubbing director','Sync QC']::text[],ARRAY['Assuming solo recording removes the need to match another actor''s energy and timing in shared scenes.','Losing natural conversational overlap and reaction timing because actors never perform together.','Failing to keep consistent mic and room settings across separate sessions, so voices do not match in the mix.']::text[],ARRAY['A streaming dub records each lead on a separate day to fit talent availability.','A studio needs clean isolated dialogue stems per character for the final mix and delivery.','A two-hander scene is built by recording each actor alone and editing their lines together.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1699fa2e-873c-5287-a5ca-088555083bc5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Single-character recording'),'[^a-z0-9]','','g'));
