INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3dd94425-41fd-5758-bfd1-c8311acd528c','Sociolect localization','The adaptation of a source character''s sociolect — the speech variety marking their social class, group, education, or profession — into an equivalent variety in the target language, so that the character''s social identity reads believably for the new audience. It is a facet of handling language variation in audiovisual translation.','A sociolect is the way a certain group or class speaks. Sociolect localization swaps the source group''s way of talking for a fitting one in the new language. It keeps the sense of who a character is.','It preserves the social signals carried by how a character speaks — status, background, belonging — which plain word-for-word translation would flatten and lose.','A translator renders a working-class or street-slang speaker using a comparable register in the target language, rather than neutral standard speech that would erase the character''s background.','Translation Adaptation',ARRAY['Sociolinguistic mapping','Register','Dialect','Semantic drift','Adaptation','Standard variety']::text[],ARRAY['Flattening every character into neutral standard speech, erasing class and group identity.','Mapping a source accent onto a target regional accent that carries the wrong social associations.','Relying on stereotypes so the localized sociolect reads as caricature rather than authentic speech.']::text[],ARRAY['Dubbing a gang drama where characters'' street speech must sound authentic in the target language.','Localizing a period piece whose upper- and lower-class characters speak in distinct registers.','Adapting a comedy that mocks a specific social group''s manner of speaking.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3dd94425-41fd-5758-bfd1-c8311acd528c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sociolect localization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3dd94425-41fd-5758-bfd1-c8311acd528c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3dd94425-41fd-5758-bfd1-c8311acd528c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9e4c724c-9e4c-59fd-8fa3-23233fd0d6ba','Sociolinguistic mapping','The analytical step in localization of identifying and charting the sociolinguistic variation in a source work — accents, dialects, sociolects, registers, and code-switching — and planning how each will be represented in the target language. It produces a reference framework that guides consistent adaptation and casting choices.','Sociolinguistic mapping studies how each character speaks. It notes their accent, slang, and class markers. The team then plans matching speech styles to use in the new language.','It gives translators and directors an organized picture of who speaks how and why, so language differences among characters are handled consistently across the whole localized work.','Before adaptation, a localization lead charts each character''s speech markers in a table and decides the target-language strategy for each, keeping the treatment consistent through the project.','Translation Adaptation',ARRAY['Sociolect localization','Register','Dialect','Adaptation','Semantic drift','Localization']::text[],ARRAY['Skipping the mapping step, so different translators handle the same character''s speech inconsistently.','Noting accents but ignoring register and code-switching that also carry meaning.','Treating the mapping as fixed and never updating it as later episodes reveal new speech traits.']::text[],ARRAY['Planning a long series so every translator handles each character''s speech style the same way.','Preparing a multilingual film where characters switch languages for dramatic effect.','Briefing a dubbing team on which accents and registers to recreate and which to neutralize.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9e4c724c-9e4c-59fd-8fa3-23233fd0d6ba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sociolinguistic mapping'),'[^a-z0-9]','','g'));
