WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9e4c724c-9e4c-59fd-8fa3-23233fd0d6ba' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '90fdf79c-c005-56ce-938f-0b7022070e5f','Source-dialogue bleed','The unwanted presence of residual source-language dialogue in a mix intended to carry only the target language — either leaking through a music-and-effects (M&E) track that should be free of dialogue, or audible under the dubbed voices. It is a quality-control failure that breaks the illusion of a fully localized soundtrack.','The music-and-effects track should have no spoken words from the first language. Source-dialogue bleed is when bits of that old speech can still be heard. It slips through under the new dubbed voices.','Flagging bleed protects the localized mix: the M&E track must be dialogue-free and fully filled so the dub can fully replace the original voices without traces of the source language.','During QC the mixer or reviewer hears faint original dialogue under the dub, traces it to an incompletely filled M&E, and has the offending section refilled or re-edited.','Audio Deliverable',ARRAY['M&E track','Sync QC','Fill','Dialogue stem','Voice-over','Deliverables']::text[],ARRAY['Delivering an M&E track that still contains snippets of source-language dialogue.','Not fully filling backgrounds where dialogue was removed, leaving gaps or leftover speech.','Checking only for level and sync and missing faint source dialogue under the dubbed lines.']::text[],ARRAY['QC of an M&E deliverable reveals residual original dialogue that must be removed before dubbing.','A dubbed episode plays back with the original voices faintly audible beneath the new track.','A crowd or walla scene was not fully refilled, so source-language lines bleed through the mix.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='90fdf79c-c005-56ce-938f-0b7022070e5f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Source-dialogue bleed'),'[^a-z0-9]','','g'));
