WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='90fdf79c-c005-56ce-938f-0b7022070e5f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8049aabc-32c2-53cb-a703-4f8ec9afca26','Source-performance shadowing','A dubbing technique in which the voice actor closely follows the original actor''s performance in real time — mirroring its timing, rhythm, intonation, and emotional dynamics — while performing to the reference picture and guide track. It applies the general principle of shadowing (tracking a model utterance as it plays) to matching a screen performance.','Source-performance shadowing means copying the original actor''s timing and feeling. The dub actor watches and listens to the first performance and follows it closely. It is like tracing over a drawing to match it.','It helps the dubbed performance stay faithful to the original''s energy, breaths, and emphasis, so the new voice feels like the same character rather than a separate reading.','In the booth the actor plays the original line in an earpiece or on screen and delivers the target line locked to its rhythm and emotion, take after take, until it matches.','Performance',ARRAY['Guide track','Lip sync','Isochrony','Dubbing director','Rushed delivery','Take']::text[],ARRAY['Copying the surface rhythm but missing the emotional intent behind the original delivery.','Shadowing so rigidly that the target line sounds unnatural in its own language.','Matching the original''s pace on a longer translated line and ending up with a rushed delivery.']::text[],ARRAY['An actor performs to the original soundtrack in their ear to match its timing and feeling.','A director asks for another take to better track the source actor''s emotional build.','A dub of an intense scene must mirror the original''s breaths, efforts, and volume changes.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8049aabc-32c2-53cb-a703-4f8ec9afca26' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Source-performance shadowing'),'[^a-z0-9]','','g'));
