INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1df0737e-d93c-55f4-8458-136d64c14352','Start-sync error','A synchronization fault in which a dubbed line begins at the wrong moment relative to the picture — too early or too late against the character''s first mouth movement — breaking isochrony at the line''s onset. It is distinct from drift within a line and is judged against the reference image rather than the waveform alone.','A start-sync error is when a dubbed line begins at the wrong moment. It may start too early or too late against the picture. The words then do not line up with the mouth opening on screen.','Identifying start-sync errors keeps the dub locked to picture, since a wrong entry point is one of the most visible sync faults and immediately reads as out of sync to viewers.','An editor nudges a late-entering dubbed line earlier so it starts on the actor''s first mouth shape, checking against the reference image, not just the audio.','Synchronization',ARRAY['Isochrony','Lip sync','Sync QC','Timecode','Take','Conform']::text[],ARRAY['Aligning a dubbed line to the source waveform instead of the on-screen mouth movement.','Fixing sync at the end of a line while leaving its start point off the picture.','Ignoring a small start offset that becomes obvious in a close-up on the actor''s mouth.']::text[],ARRAY['A dubbed line enters a beat after the actor''s lips move in a close-up.','Conforming a dub to a re-edited picture shifts line start points out of sync.','Sync QC flags a scene where several lines begin too early against the image.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1df0737e-d93c-55f4-8458-136d64c14352' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Start-sync error'),'[^a-z0-9]','','g'));
