INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5a8017f7-e846-54cf-a480-555c202ac9d8','Swear-strength matching','The practice, in localizing taboo language, of choosing target-language profanity whose offensive load — its strength or shock value — is comparable to that of the source term, so the emotional impact is preserved without over- or under-shooting. It treats swearing on a scale of intensity rather than as literal vocabulary to be translated word for word.','Different languages have strong and mild swear words. Swear-strength matching picks a target swear that is about as strong as the first one. This keeps the same punch without going too far or too soft.','It preserves a character''s tone and the scene''s emotional charge, since a swear that is too tame or too crude for the moment misrepresents the original and can jar the audience.','A translator rates the source expletive''s force and selects a target equivalent of similar strength, adjusting for what counts as offensive in the target culture and any client content limits.','Translation Adaptation',ARRAY['Taboo language','Register','Sociolect localization','Censorship','Adaptation','Content rating']::text[],ARRAY['Translating a swear word literally and landing on an intensity that is far milder or harsher than intended.','Softening all profanity by default, draining a character''s edge and the scene''s impact.','Ignoring that the same word carries different offensive weight across cultures and contexts.']::text[],ARRAY['Localizing a crime drama where characters swear constantly and tone must be preserved.','Adapting comedy whose humor depends on the exact shock level of a taboo word.','Meeting a broadcaster''s content limits while keeping profanity''s dramatic force.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5a8017f7-e846-54cf-a480-555c202ac9d8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Swear-strength matching'),'[^a-z0-9]','','g'));
