WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5a8017f7-e846-54cf-a480-555c202ac9d8' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '47806f58-5402-51b8-bcaa-f26a336afaf7','Sync QC','The quality-control stage in which dubbed or revoiced audio is checked for synchronization against the picture — verifying lip sync, isochrony, and correct line entry and exit points — before the localized version is approved for delivery. It is performed against the reference image, and flags sync faults for correction.','Sync QC is a quality check on timing. A reviewer watches the dubbed scene against the picture. They look for lines that drift off the mouth or start at the wrong moment.','It catches synchronization faults before release, protecting the viewing experience, since visible sync errors are among the most noticeable flaws in a dub.','A QC operator plays the dubbed program against picture, logs start-sync errors, lip-sync slips, and drift, and returns time-stamped notes for the editor to fix.','Synchronization',ARRAY['Start-sync error','Isochrony','Lip sync','Conform','Deliverables','Dubbing director']::text[],ARRAY['Checking sync against the audio waveform alone instead of the on-screen mouth movement.','Reviewing only flagged key moments and missing sync drift elsewhere in the program.','Passing lip sync but overlooking source-dialogue bleed or wrong line entry points.']::text[],ARRAY['Final review of a dubbed series before it is delivered to the streaming platform.','A QC pass flags close-ups where the dub drifts off the actor''s lips.','Re-checking sync after a dub is conformed to a revised picture cut.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='47806f58-5402-51b8-bcaa-f26a336afaf7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync QC'),'[^a-z0-9]','','g'));
