SELECT '47806f58-5402-51b8-bcaa-f26a336afaf7','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='47806f58-5402-51b8-bcaa-f26a336afaf7' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a3cc3d3d-f6c3-5d98-a992-164cc7f2b0bb','Sync adaptation','The stage of dubbing in which a translated script is rewritten so each line fits the on-screen speech, meeting the constraints of lip synchrony (matching visible mouth movements, especially labials), isochrony (matching the duration of the original utterance between pauses), and kinesic synchrony (matching the actor''s gestures). It is carried out by a dialogue writer or adapter after the literal translation.','Sync adaptation reshapes the translated lines so they fit the actor on screen. The words must match the mouth, the timing, and the gestures. A writer rewrites the plain translation to make each line look natural.','It exists to make a dubbed line look as if it were really spoken by the on-screen actor, so the audience is not distracted by mismatched lips, length, or gestures.','A dialogue adapter takes the rough translation and rewrites each line against the picture, swapping words and phrasing until the line matches the mouth movements and fits the available screen time.','Synchronization',ARRAY['Isochrony','Lip synchrony','Kinesic synchrony','Sync window','Underlength line','Timbre matching']::text[],ARRAY['Treating adaptation as literal translation, so lines are accurate but do not match the mouth or the timing.','Focusing only on labial sounds and ignoring isochrony, leaving lines that end well before or after the mouth stops moving.','Rewriting so heavily to force sync that the original meaning or tone is lost.']::text[],ARRAY['Adapting a translated feature-film script so close-up lines match the actors'' lip movements.','Reworking a sitcom translation so each joke fits the on-screen speaking time.','Preparing a dubbing script from a rough translation before the voice recording session.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a3cc3d3d-f6c3-5d98-a992-164cc7f2b0bb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync adaptation'),'[^a-z0-9]','','g'));
