SELECT 'a3cc3d3d-f6c3-5d98-a992-164cc7f2b0bb','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a3cc3d3d-f6c3-5d98-a992-164cc7f2b0bb' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '50fa1a2f-9e2e-585c-82d2-5441bf369f05','Sync loss','A condition in which audio no longer aligns in time with the picture, so speech is heard before or after the matching lip movements. ITU-R BT.1359-1 sets perception thresholds for broadcasting: sync errors become detectable beyond about +45 ms (audio ahead of picture) to -125 ms (audio behind picture) and unacceptable beyond about +90 ms to -185 ms.','Sync loss is when the sound and the picture no longer line up. You hear the voice a little before or after the lips move. Small gaps are fine, but large ones look wrong and pull viewers out of the scene.','Naming and measuring sync loss lets technicians catch and correct audio-to-video timing errors before delivery, keeping speech locked to the picture.','A technician checks lip sync against picture and, if the audio has drifted, nudges the dialogue track earlier or later until mouths and sound match within the accepted tolerance.','Synchronization',ARRAY['Sync window','Sync adaptation','Lip synchrony','Time-sync dubbing','Sync-driven distortion','Technical QC']::text[],ARRAY['Assuming any offset is fine because small errors are hard to hear, then stacking delays until the total exceeds the acceptable window.','Fixing sync by ear on one device without confirming the whole program stays within tolerance.','Confusing a fixed whole-track offset with drift, where the error grows over the length of the program.']::text[],ARRAY['Checking a dubbed episode where the voices slowly drift ahead of the picture.','Diagnosing lip-sync complaints after a broadcast processing chain adds audio delay.','QC of a delivery to confirm sync stays inside broadcast tolerance.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='50fa1a2f-9e2e-585c-82d2-5441bf369f05' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync loss'),'[^a-z0-9]','','g'));
