SELECT '50fa1a2f-9e2e-585c-82d2-5441bf369f05','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='50fa1a2f-9e2e-585c-82d2-5441bf369f05' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0bc37290-8985-5056-bdc6-2c2888ad51d9','Sync window','The window of time into which a dubbed line must fit, defined by when the on-screen character starts and stops speaking, so the target line matches the length of the original utterance (isochrony). The term is also used for the tolerance range within which an audio-to-picture offset is still perceived as in sync.','The sync window is the slot of time a dubbed line has to fit. It starts when the actor''s mouth opens and ends when it closes. The new line must be short or long enough to fill that slot.','It gives the adapter and voice actor a clear time budget, so each translated line starts and ends with the on-screen speech instead of running short or long.','An adapter measures the on-screen speaking time for a line and writes a translation that can be spoken naturally within that window, trimming or padding wording as needed.','Synchronization',ARRAY['Isochrony','Sync adaptation','Underlength line','Sync loss','Time-sync dubbing','Lip synchrony']::text[],ARRAY['Writing a line that is accurate but too long to be spoken inside the on-screen window.','Ignoring pauses inside the window, so the delivery does not line up with the actor''s mouth.','Padding a short translation with filler that sounds unnatural just to fill the window.']::text[],ARRAY['Timing a translated line against the character''s mouth movement before recording.','Deciding whether a line must be shortened to fit a tight close-up.','Explaining to a voice actor how much screen time a line has to land in.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0bc37290-8985-5056-bdc6-2c2888ad51d9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync window'),'[^a-z0-9]','','g'));
