SELECT '0bc37290-8985-5056-bdc6-2c2888ad51d9','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0bc37290-8985-5056-bdc6-2c2888ad51d9' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1f243c16-d323-5d97-b144-9ebdc0658f1f','Sync-driven distortion','Alteration of the translated message caused by prioritizing synchronization over fidelity, where wording, meaning, register, or naturalness is changed so a line will fit lip movements, duration (isochrony), or gestures. It reflects the well-documented tension between synchrony and translation accuracy in dubbing.','Sometimes the translation gets bent to make it fit the mouth and timing. Words or even meaning may change just so the line matches the screen. This trade-off between a good fit and a faithful translation is the idea here.','The idea names a known trade-off, reminding adapters that forcing a line into sync can quietly damage meaning or tone, so they can weigh accuracy against fit.','An adapter facing a line that will not fit decides how much meaning to sacrifice for sync, and flags cases where a forced fit would distort the intent too far.','Synchronization',ARRAY['Sync adaptation','Isochrony','Sync window','Underlength line','Lip synchrony','Terminology drift']::text[],ARRAY['Always choosing a perfect lip match even when it twists the meaning of the line.','Assuming sync and accuracy never conflict, then delivering lines that read oddly in the target language.','Blaming the translator for wording that was actually forced by tight sync limits.']::text[],ARRAY['Rewriting a punchline to fit a close-up, at the cost of part of the joke.','Choosing a shorter, less exact word so a line ends when the mouth closes.','Reviewing a dub where meaning was lost to force a labial match.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1f243c16-d323-5d97-b144-9ebdc0658f1f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync-driven distortion'),'[^a-z0-9]','','g'));
