INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '46ce1574-52e0-5bd5-9d5f-97956f4cbd78','Taboo calibration','The deliberate adjustment of taboo, offensive, or profane language in a localized version to suit the target culture, audience, and broadcast or platform standards, using strategies such as retention, softening (euphemism), or omission. The chosen intensity is governed by regional norms, ratings, and client policy rather than a fixed rule.','Taboo calibration means deciding how strong to make rude or offensive words in the new language. Some markets keep them, some soften them, and some cut them. The choice depends on local rules and who will watch.','It exists to match a program''s strong language to what a given market and platform will accept, avoiding both needless censorship and content that breaks local standards.','A translator or adapter maps each swear word or taboo term to an equivalent that fits the target rating, keeping, toning down, or cutting it according to the client''s policy and local law.','Adaptation',ARRAY['Sync adaptation','Terminology drift','Technical QC','Two-voice dubbing','UN-style voiceover','Timbre matching']::text[],ARRAY['Softening all strong language by habit, even when the platform allows the original intensity.','Translating swear words literally without checking they carry the same force in the target culture.','Ignoring local broadcast rules and delivering language that must be re-edited.']::text[],ARRAY['Adapting a violent crime drama''s profanity for a broadcast slot with strict standards.','Deciding whether to keep or soften a slur that is far more offensive in the target culture.','Following a streaming client''s policy to keep profanity unless local law forbids it.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='46ce1574-52e0-5bd5-9d5f-97956f4cbd78' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Taboo calibration'),'[^a-z0-9]','','g'));
