WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='46ce1574-52e0-5bd5-9d5f-97956f4cbd78' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7fd616d7-4cc8-5e51-9673-f068cf6e9551','Technical QC','The technical quality-control pass that verifies a localized audio deliverable meets specification: lip sync and timing, audio levels and loudness (for example EBU R128 at a target of -23 LUFS with maximum true peak of -1 dBTP, measured per ITU-R BS.1770), absence of clicks, dropouts, distortion and unwanted noise, correct channel and track layout, and file conformance.','Technical QC is the final check that the dubbed audio meets the delivery rules. A technician confirms the sync, loudness, and channels are correct. They also listen for clicks, dropouts, and other faults before the file ships.','It exists to catch technical faults before delivery, so the localized audio plays correctly and meets the broadcaster''s or platform''s specification.','A QC technician runs loudness and true-peak meters, checks sync against picture, scans for artifacts, and confirms track layout and file format against the delivery spec, logging any failures for repair.','Quality Control',ARRAY['Sync loss','Terminology drift','Sync window','Time-sync dubbing','Vocal continuity break','Timbre matching']::text[],ARRAY['UNSAFE: Monitoring QC at high headphone or speaker levels for long shifts, risking noise-induced hearing loss; keep exposure within OSHA and NIOSH limits and take breaks.','Passing a file on program loudness alone without checking true peak, so inter-sample peaks clip on playback.','Checking sync on only one scene instead of across the whole program.','Trusting meters alone without also listening for clicks, dropouts, and distortion.']::text[],ARRAY['Final QC of a dubbed episode before it is delivered to a streaming platform.','Verifying a mix meets EBU R128 loudness before broadcast.','Rejecting a deliverable that has an audio dropout and returning it for repair.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7fd616d7-4cc8-5e51-9673-f068cf6e9551' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Technical QC'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7fd616d7-4cc8-5e51-9673-f068cf6e9551','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7fd616d7-4cc8-5e51-9673-f068cf6e9551' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da1b8976-6611-5be6-ad43-2f6354f95a7f','Terminology drift','The unwanted inconsistency that arises when a recurring name, place, title, or specialized term is translated differently across episodes, seasons, or translators, drifting from its approved rendering in the project glossary (such as a Key Names and Phrases list). It breaks continuity for the audience and signals a terminology-management failure.','Terminology drift is when the same name or term gets translated in different ways across a show. One episode says it one way, the next says it another. A shared glossary keeps everyone using the same agreed word.','Naming the problem drives use of a master glossary, so key names and terms stay identical across a whole title and every translator working on it.','Localization teams lock recurring names and terms in a glossary and check new episodes against it, correcting any line that has drifted from the approved translation.','Quality Control',ARRAY['Technical QC','Sync adaptation','Taboo calibration','Vocal continuity break','Timbre matching','Sync-driven distortion']::text[],ARRAY['Letting each translator invent their own rendering instead of following a shared glossary.','Not updating the glossary when a name''s translation changes, so old and new versions both appear.','Checking spelling but not consistency, so a character''s name shifts between episodes.']::text[],ARRAY['A character''s name is rendered two different ways across a dubbed season.','A recurring fictional place is translated differently by two subtitlers.','Auditing a series against its Key Names and Phrases glossary before release.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da1b8976-6611-5be6-ad43-2f6354f95a7f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Terminology drift'),'[^a-z0-9]','','g'));
