INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '420bccbd-a4ad-5f9e-a438-7008f42a4a70','Timbre matching','The casting and direction practice of choosing and coaching a dub voice actor whose vocal timbre - the tone colour and quality of the voice - closely resembles that of the original on-screen actor, alongside matching age, pitch range, and delivery, so the dubbed voice is believable for that character.','Timbre is the colour or texture of a voice, what makes two voices sound different at the same pitch. Timbre matching means casting a dub actor whose voice colour is close to the original actor''s. This helps the new voice feel like it belongs to the character.','It exists so the dubbed voice reads as the same character, keeping the audience''s belief in the performance instead of noticing a mismatched voice.','A dubbing director auditions candidates against the original track, picks the voice whose timbre and age best fit, then coaches delivery to bring it even closer.','Voice Casting',ARRAY['Vocal continuity break','Sync adaptation','Lip synchrony','Two-voice dubbing','UN-style voiceover','Isochrony']::text[],ARRAY['Matching only pitch or gender and ignoring the finer tone colour that identifies a voice.','Casting a technically skilled actor whose voice is clearly wrong for the character''s look and age.','Judging a match in isolation instead of against the original actor''s voice on the picture.']::text[],ARRAY['Casting a deep, gravelly dub voice to match a gravel-voiced lead actor.','Auditioning several actors against the original track to find the closest tone.','Recasting a role and needing a voice that matches the previous dub actor.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='420bccbd-a4ad-5f9e-a438-7008f42a4a70' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timbre matching'),'[^a-z0-9]','','g'));
