INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc670d47-01db-54be-96ed-3f0158445ed2','Time-sync dubbing','A dubbing approach in which the recorded target-language dialogue is time-aligned to the original on-screen speech, so each line starts, ends, and lasts as close as possible to the original utterance (isochrony) and, in close-ups, matches visible lip movement. It contrasts with voice-over, where the translation only loosely overlaps the original.','Time-sync dubbing means recording the new voice to line up in time with the original speech. Each line starts and ends when the actor''s does. This is the tight kind of dubbing you see in films, not the looser voice-over style.','It exists to replace the original dialogue seamlessly, so the audience hears their own language locked to the on-screen timing and mouth movements.','A voice actor watches the picture with cues and delivers each line to hit the same start and end as the original, while an editor fine-tunes the timing afterward.','Dubbing Mode',ARRAY['Sync adaptation','Isochrony','Lip synchrony','UN-style voiceover','Two-voice dubbing','Sync window']::text[],ARRAY['Confusing time-sync dubbing with voice-over, where exact lip match is not required.','Getting line length right but ignoring internal pauses, so the middle of the line drifts off the mouth.','Recording a great performance that does not hit the original timing and cannot be edited back into sync.']::text[],ARRAY['Dubbing a feature film so the target dialogue matches the actors'' mouths.','Recording a children''s animation where lines must land on each character''s mouth flaps.','Editing recorded dub takes to lock start and end points to the picture.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc670d47-01db-54be-96ed-3f0158445ed2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Time-sync dubbing'),'[^a-z0-9]','','g'));
