INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a27226cf-9398-5df0-b942-76ef8b20b9c4','Two-voice dubbing','A revoicing configuration, used mainly in voice-over localization, in which two voice talents - commonly one male and one female - cover all on-screen speakers, with roles split by the gender or type of the original speaker. It sits between single-voice voice-over (one narrator for everyone) and full dubbing (a distinct actor per character).','Two-voice dubbing uses just two voices to cover everyone on screen. Often one man and one woman split all the speakers between them. It is simpler and cheaper than giving every character its own actor.','It offers a middle option: clearer speaker identification than a single narrator, but at lower cost than casting a separate actor for every role.','A studio assigns male original speakers to one voice actor and female speakers to another, and both read their lines as voice-over above the lowered original track.','Dubbing Mode',ARRAY['UN-style voiceover','Time-sync dubbing','Timbre matching','Isochrony','Vocal continuity break','Sync adaptation']::text[],ARRAY['Confusing two-voice voice-over with full dubbing, which uses one actor per character.','Splitting speakers so poorly that the audience loses track of who is talking.','Expecting tight lip sync, when voice-over only needs loose overlap with the original.']::text[],ARRAY['Localizing a documentary with two narrators covering all the interviewees.','Voicing a reality show cheaply with one male and one female voice.','Revoicing factual content in a voice-over market such as Poland or Russia.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a27226cf-9398-5df0-b942-76ef8b20b9c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Two-voice dubbing'),'[^a-z0-9]','','g'));
