INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '355a3853-874c-5454-a4d3-72c7650b6687','UN-style voiceover','A voice-over revoicing technique, modelled on United Nations simultaneous interpreting, in which the original speaker is heard alone for a few seconds, then the translated voice is laid over the original at reduced volume while the original stays faintly audible, with the translation usually ending just before the original finishes. It is standard for interviews and documentary content.','UN-style voiceover copies how interpreters work at the United Nations. You hear the real speaker first for a second or two. Then a translated voice comes in over the top, while the original plays softly underneath. It is common in documentaries and interviews.','Leaving the original briefly audible creates an authenticity effect, signalling to viewers that the translation is faithful to what the real person said.','A studio records the translation to start a beat after the original, mixes the original down but still audible under it, and ends the translation before the speaker stops.','Dubbing Mode',ARRAY['Two-voice dubbing','Time-sync dubbing','Isochrony','Timbre matching','Sync adaptation','Vocal continuity break']::text[],ARRAY['Starting the translation at the same instant as the original, losing the authentic opening.','Mixing the original so low it disappears, which removes the authenticity effect.','Treating it like lip-sync dubbing and forcing exact mouth timing it does not need.']::text[],ARRAY['Voicing a foreign-language interview in a news documentary.','Localizing testimony in a factual program while keeping the speaker''s real voice under it.','Revoicing a reality contestant so viewers still hear the original emotion underneath.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='355a3853-874c-5454-a4d3-72c7650b6687' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('UN-style voiceover'),'[^a-z0-9]','','g'));
