WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='355a3853-874c-5454-a4d3-72c7650b6687' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '096f34ac-e787-5df8-9b94-68b771df8811','Underlength line','A translated or dubbed line whose spoken duration is shorter than the on-screen utterance it must cover, leaving the character''s mouth still moving after the line ends and breaking isochrony. It is the counterpart of an overlength line, which runs past the available screen time.','An underlength line is a dubbed line that is too short. The voice stops but the actor''s mouth is still moving. It leaves a gap that looks wrong, so the adapter must pad or reword the line.','Naming it flags a sync fault the adapter must fix by lengthening or rephrasing the line so it fills the on-screen speaking time.','When a line comes up short against picture, the adapter adds words, expands the phrasing, or adjusts pacing so the delivery lasts as long as the original.','Synchronization',ARRAY['Isochrony','Sync window','Sync adaptation','Time-sync dubbing','Sync loss','Lip synchrony']::text[],ARRAY['Leaving a short line as it is, so the mouth keeps moving after the voice stops.','Padding with filler words that sound unnatural just to reach the right length.','Fixing overall length but ignoring where the internal pauses should fall.']::text[],ARRAY['A translated line ends early while the character is still clearly speaking.','Adapting a wordy source line into a target language that says the same thing faster.','Reworking short lines during a dub recording to fill the on-screen time.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='096f34ac-e787-5df8-9b94-68b771df8811' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Underlength line'),'[^a-z0-9]','','g'));
