SELECT '096f34ac-e787-5df8-9b94-68b771df8811','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='096f34ac-e787-5df8-9b94-68b771df8811' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23d9fd62-14a3-5571-8ec5-a598d9ee5d7c','Vocal continuity break','A break in the consistency of a character''s dubbed voice, occurring when the voice changes noticeably across takes, scenes, episodes, or seasons - for example through recasting, or a shift in timbre, pitch, accent, or performance - so the audience no longer perceives one continuous voice for the character.','A vocal continuity break is when a character''s dubbed voice suddenly changes. Maybe a new actor takes over, or the tone shifts between scenes. The audience notices the voice no longer sounds like the same person.','Naming it drives efforts to keep one consistent voice per character, protecting the audience''s belief in that character across a whole production.','A dubbing supervisor tracks which actor voices each character and reviews new episodes so timbre and delivery stay consistent, re-recording or recasting carefully to avoid a jarring change.','Voice Casting',ARRAY['Timbre matching','Two-voice dubbing','Sync adaptation','Terminology drift','UN-style voiceover','Technical QC','Voice-continuity defect (near-synonymous: this term names the phenomenon, while that one frames it as the flagged QC fault)']::text[],ARRAY['Recasting a character mid-series without matching the previous voice.','Letting an actor''s delivery or accent drift between recording sessions.','Assuming viewers will not notice a changed voice, when voice is a key part of a character.']::text[],ARRAY['A lead character''s dub actor changes between seasons and sounds different.','Timbre and energy shift between two recording days for the same character.','Reviewing a series so each character keeps one consistent voice throughout.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23d9fd62-14a3-5571-8ec5-a598d9ee5d7c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal continuity break'),'[^a-z0-9]','','g'));
