SELECT '23d9fd62-14a3-5571-8ec5-a598d9ee5d7c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23d9fd62-14a3-5571-8ec5-a598d9ee5d7c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75124ec5-b7e2-5988-96af-2591f3b5a105','Vocal efforts','Non-verbal vocalizations produced by an actor — such as breaths, grunts, sighs, gasps, groans, laughs, cries, and exertion sounds — that carry no lexical (word) content but convey physical state, emotion, or effort. In dubbing and localization scripts they are notated apart from spoken lines, commonly in parentheses or brackets, so the dubbing actor reproduces them and the mix places them correctly.','Vocal efforts are the non-word sounds an actor makes, like grunts, sighs, and heavy breaths. They show feeling or effort but are not real words. A dubbing actor must record these too, so the new voice track feels alive.','They preserve the physical and emotional realism of a performance across languages, so the dubbed character breathes, reacts, and exerts like the original even when no words are spoken.','A dubbing actor records the efforts along with the dialogue and the editor syncs them to on-screen action; in the script they appear inside parentheses or brackets rather than as timed dialogue.','Voice Performance',ARRAY['Reactions','Automated dialogue replacement','Lip sync','Music and effects track','Isochrony','Walla']::text[],ARRAY['Timing a dialogue event to start or end on an effort instead of on the first and last spoken words.','Omitting efforts entirely, so the dubbed character sounds lifeless during physical action.','Confusing an effort with lexical dialogue and mistranslating a grunt or sigh as a word.']::text[],ARRAY['Annotating grunts and breaths in an as-recorded dubbing script.','Recording exertion sounds for a fight scene in the target language.','Deciding whether a character''s laugh stays in the music-and-effects track or is re-voiced.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75124ec5-b7e2-5988-96af-2591f3b5a105' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal efforts'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '75124ec5-b7e2-5988-96af-2591f3b5a105','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='75124ec5-b7e2-5988-96af-2591f3b5a105' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e711f9fb-cf31-5afb-b413-3d8c53c65532','Vocal-age matching','The casting and performance practice of selecting a dubbing voice whose perceived age — conveyed through timbre, pitch, and vocal maturity — matches the apparent age of the on-screen character, so that a child reads as a child and an elderly character reads as elderly.','Vocal-age matching means picking a dubbing voice that sounds the right age for the character. A young kid should sound young; an old person should sound old. The goal is a voice that fits the face on screen.','It keeps the dubbed voice believable by aligning vocal maturity with the character''s visible age, preventing the jarring mismatch of an adult-sounding child or a youthful-sounding elder.','During casting, the voice director auditions actors whose natural or acted vocal age suits each role and rejects takes where the voice sounds too old or too young for the picture.','Voice Casting',ARRAY['Voice casting equivalence','Vocal-weight matching','Voice-body congruence','Vocal-equivalence casting','Timbre']::text[],ARRAY['Casting on timbre alone and ignoring whether the voice reads as the character''s age.','Assuming a child character must be voiced by a child, when a skilled adult may match better and is easier to direct.','Letting an actor''s real age override the character''s on-screen age.']::text[],ARRAY['Casting the dubbed voice of a child character in an animated feature.','Matching an elderly narrator''s vocal age across a documentary series.','Re-auditioning a role because the first voice sounded too mature for the character.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e711f9fb-cf31-5afb-b413-3d8c53c65532' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-age matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e711f9fb-cf31-5afb-b413-3d8c53c65532','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e711f9fb-cf31-5afb-b413-3d8c53c65532' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c73b32a-79ae-5d5e-8b4a-6ae314a68551','Vocal-bearing ambience','Background or ambient sound that contains recognizable, language-specific voice content — such as distinct crowd lines, walla with intelligible speech, or public-address announcements — as opposed to neutral, non-verbal ambience. Because it carries language, it must be identified and routed to optional or dialogue tracks rather than left in the fully filled music-and-effects (M&E) bed, so it can be localized.','Some background sound has real spoken words in it, like a crowd, a loudspeaker, or a phone voice. That is vocal-bearing ambience. Because it has words, it must be pulled out. The team re-records it in the new language. It cannot stay in the background mix.','Flagging vocal-bearing ambience ensures every intelligible line in the mix, even in the background, can be translated, so no source-language speech survives in the localized version.','During music-and-effects preparation, the editor separates distinct crowd lines, PA announcements, and phone voices onto optional tracks so the localization team can re-record them in the target language.','Localization Prep',ARRAY['Music and effects track','Walla','Optional dialogue','Dialogue editing','Vocal efforts']::text[],ARRAY['Leaving intelligible crowd or PA lines in the music-and-effects bed, so source-language words remain in the dub.','Treating all crowd noise as neutral walla without checking for distinct, translatable lines.','Failing to separate overlapping background speakers, making clean re-recording impossible.']::text[],ARRAY['Preparing a music-and-effects track and finding a station announcement that must be re-voiced.','Splitting distinct background lines out of a crowd bed for a dub.','Auditing a mix to confirm no source-language speech hides in the ambience.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c73b32a-79ae-5d5e-8b4a-6ae314a68551' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-bearing ambience'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9c73b32a-79ae-5d5e-8b4a-6ae314a68551','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c73b32a-79ae-5d5e-8b4a-6ae314a68551' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b5e1bfe-f541-589b-8e64-a35323860aad','Vocal-equivalence casting','Casting a dubbing voice actor to achieve equivalence with the original performer''s vocal identity — matching qualities such as timbre, pitch range, texture, and character-defining traits — so the dubbed voice functions as the credible target-language counterpart of the original.','This means choosing a dubbing actor whose voice closely matches the original actor''s voice. The new voice should have a similar tone and feel. That way, viewers accept it as the same character speaking their language.','It maintains the character''s vocal identity across languages so audiences recognize and believe the dubbed voice as belonging to that character, supporting immersion.','Casting directors audition and shortlist actors whose vocal qualities align with the original, prioritizing performance while matching timbre where a specific vocal trait defines the character.','Voice Casting',ARRAY['Voice casting equivalence','Vocal-age matching','Vocal-weight matching','Voice-body congruence','Timbre']::text[],ARRAY['Prioritizing an exact voice match over acting quality, producing a similar but wooden performance.','Ignoring that vocal volume, pitch, and articulation naturally vary between languages.','Matching only pitch while missing the texture or trait that actually defines the character''s voice.']::text[],ARRAY['Casting the target-language voice of a well-known lead actor.','Shortlisting actors whose timbre matches a distinctive original voice.','Balancing voice similarity against acting ability during a dub audition.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b5e1bfe-f541-589b-8e64-a35323860aad' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-equivalence casting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0b5e1bfe-f541-589b-8e64-a35323860aad','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0b5e1bfe-f541-589b-8e64-a35323860aad' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '19b8de7c-b1fd-5aca-b62a-00f0b197f83a','Vocal-weight matching','Matching the perceived weight of a dubbing voice — its heaviness, body, density, and gravitas, arising from timbre, resonance, and intensity — to that of the original voice or the character''s physical presence, so a heavy, resonant character is not dubbed with a light, thin voice, or vice versa.','Some voices sound heavy and full; others sound light and thin. Vocal-weight matching means giving a character a voice with the right heaviness. A big, powerful character should not get a small, thin voice.','It preserves the sense of size, power, or presence a voice lends a character, keeping the dubbed performance congruent with the figure on screen.','The voice director selects and coaches an actor whose resonance and intensity give the character the same vocal heft as the original, adjusting mic technique and delivery to match.','Voice Casting',ARRAY['Vocal-equivalence casting','Vocal-age matching','Voice-body congruence','Timbre','Resonance']::text[],ARRAY['Matching pitch but not body, so a large character sounds thin and unconvincing.','Confusing loudness with vocal weight, which comes from resonance and timbre rather than level.','Casting a light voice for an imposing character because the pitch happened to match.']::text[],ARRAY['Casting the dub of a large, authoritative villain.','Matching a deep, resonant narrator across a series.','Coaching an actor to add body and gravitas to a lead role.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='19b8de7c-b1fd-5aca-b62a-00f0b197f83a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-weight matching'),'[^a-z0-9]','','g'));
