INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9136a14b-b60c-56fe-abe8-a7dd30d23a51','Vocative adaptation','The translation and adaptation of vocatives — forms of direct address such as names, titles, terms of endearment, and honorifics — when localizing dialogue, deciding whether to keep, replace, add, or omit each vocative to preserve its attention-getting, relational, and expressive functions in the target language and culture.','Vocatives are the words we use to address someone, like their name, ''sir,'' or ''honey.'' Vocative adaptation is choosing how to translate them. The translator may keep, change, or drop each one so it feels natural and keeps the right tone.','It carries the social and emotional relationship between characters across languages, since forms of address signal politeness, intimacy, and status that differ from culture to culture.','A dubbing translator decides how to render titles and terms of endearment, adjusting for target-language politeness systems and, in dubbing, for lip sync and line length.','Dialogue Adaptation',ARRAY['Isochrony','Lip sync','Dialogue adaptation','Honorifics','Localization']::text[],ARRAY['Translating every vocative literally, which can sound stiff or wrong in the target culture.','Dropping a vocative that actually carried the emotion or relationship of the line.','Ignoring target-language politeness levels, such as formal versus informal forms of ''you''.']::text[],ARRAY['Adapting Japanese honorifics for an English dub.','Deciding whether to keep a character''s nickname in the target language.','Adjusting a formal or informal form of address to match the characters'' relationship.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9136a14b-b60c-56fe-abe8-a7dd30d23a51' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocative adaptation'),'[^a-z0-9]','','g'));
