INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b53e4e45-24b5-5f44-b533-f7e9871c2874','Voice casting equivalence','The principle that a dubbing cast should collectively deliver target-language voices functionally equivalent to the original performances — in vocal identity, age, weight, and character fit — so the localized version produces the same character impressions and relationships as the source.','Voice casting equivalence means the whole dubbed cast should feel like the original cast. Each new voice should give the same impression as the voice it replaces. The audience should react to the characters the same way.','It sets the casting goal for a dub: not identical voices, but a set of voices that recreate the same character identities and dynamics for the target audience.','A voice director casts each role against the original, then checks the ensemble so contrasting characters stay distinct and relationships read the same as in the source.','Voice Casting',ARRAY['Vocal-equivalence casting','Vocal-age matching','Vocal-weight matching','Voice-body congruence','Voice continuity']::text[],ARRAY['Casting each role in isolation, so the ensemble loses the contrasts of the original.','Chasing identical voices instead of equivalent character impressions.','Overlooking that a strong performance can achieve equivalence even without a close voice match.']::text[],ARRAY['Casting an ensemble dub so each character stays distinct.','Reviewing a cast list against the original performances before recording.','Balancing voice similarity and acting across a full dubbed cast.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b53e4e45-24b5-5f44-b533-f7e9871c2874' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice casting equivalence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b53e4e45-24b5-5f44-b533-f7e9871c2874','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b53e4e45-24b5-5f44-b533-f7e9871c2874' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c244b3e-33ec-5aab-bd3e-6fb292ca93a0','Voice continuity','The maintenance of the same dubbing voice for a given character across all episodes, seasons, sequels, or related titles, so that a recurring or returning character is always heard with a consistent target-language voice.','Voice continuity means a character keeps the same dubbing voice every time. Across seasons or sequels, the same actor voices them. This stops the character''s voice from suddenly changing and confusing viewers.','It preserves character identity and audience recognition over time, since a changed voice can break the illusion that it is the same character.','Localization managers track which actor voices each recurring character and re-book that actor for new episodes or films, or arrange a careful recast when the actor is unavailable.','Voice Casting',ARRAY['Voice recast','Voice-continuity defect','Voice double','Voice casting equivalence','Voice-body congruence']::text[],ARRAY['Failing to log the original dubbing actor, so a later season is recast by accident.','Assuming any similar voice will do when audiences are attached to the established one.','Ignoring continuity across a franchise, so a returning character sounds different in a sequel.']::text[],ARRAY['Re-booking the same actor to dub a returning character in a new season.','Managing a franchise so a hero keeps one voice across films.','Handling a recast when the original dubbing actor is unavailable.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c244b3e-33ec-5aab-bd3e-6fb292ca93a0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice continuity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
