INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2bb7ee47-8ac4-5704-842d-f262498054c3','Voice double','A performer who supplies a replacement or matched voice for an on-screen or original character — for example dubbing another actor, providing a soundalike, or covering lines the original performer cannot deliver — so the character is heard with a voice other than the original recording.','A voice double is a performer who provides a voice for someone else. They may dub another actor or sound just like them. It is like a body double, but for the voice instead of the body.','It lets production replace or supply a character''s voice when the original is unavailable, unusable, or must be recreated in another language or style.','A voice double records lines to match an actor''s timbre and delivery, used in localization dubs, soundalike replacements, or when an actor''s own track must be redone.','Voice Performance',ARRAY['Voice recast','Automated dialogue replacement','Voice continuity','Vocal-equivalence casting','Voice-body congruence']::text[],ARRAY['Assuming a voice double only imitates, when the job also demands matching performance and timing.','Ignoring lip sync so the doubled voice drifts off the on-screen mouth.','Confusing a voice double with a stand-in who has no vocal role.']::text[],ARRAY['Providing a soundalike voice when an actor cannot return for reshoots.','Dubbing a foreign-language lead with a matched target voice.','Covering unusable production lines with a matched replacement voice.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2bb7ee47-8ac4-5704-842d-f262498054c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice double'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2bb7ee47-8ac4-5704-842d-f262498054c3','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2bb7ee47-8ac4-5704-842d-f262498054c3' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '91ab135c-3b56-5422-a3ee-779bb238e94a','Voice recast','The replacement of the actor who voices a character with a different actor, in original production or in a dub — for instance when the established dubbing actor is unavailable, retires, or is changed for creative or contractual reasons.','A voice recast is when a character''s voice actor is swapped for a new one. This happens if the first actor leaves or cannot return. The new actor then takes over the role.','It allows a production to continue a character when the current voice actor cannot or should not continue, though it risks breaking voice continuity.','When a recurring dubbing actor is unavailable, the studio auditions and casts a replacement, often coaching them to match the established voice as closely as possible.','Voice Casting',ARRAY['Voice continuity','Voice-continuity defect','Voice double','Voice casting equivalence','Vocal-equivalence casting']::text[],ARRAY['Recasting without trying to match the established voice, jarring loyal audiences.','Failing to smooth the change across a season boundary or prepare the audience.','Treating a recast as routine when a defining voice is central to the character.']::text[],ARRAY['Replacing a dubbing actor who has retired from a long-running series.','Recasting a character''s voice after a contract dispute.','Bringing in a new actor to match a beloved original voice.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='91ab135c-3b56-5422-a3ee-779bb238e94a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice recast'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '91ab135c-3b56-5422-a3ee-779bb238e94a','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
