INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bfc7b854-b65b-5f91-aa57-c86de7ffd25f','Voice-body congruence','The perceived match between a character''s voice and their visible body and physicality — size, build, age, movement, and gesture — so the voice seems genuinely to emanate from that on-screen figure. Related to kinesic synchrony, it fails when a voice seems too small, large, young, or old for the body shown.','Voice-body congruence means the voice fits the body we see. A large character should have a voice that suits their size. If the voice seems wrong for the body, viewers sense something is off.','It sustains the illusion that the dubbed voice belongs to the on-screen character, tying vocal qualities to the visible physical presence.','Voice directors cast and coach so the actor''s vocal weight, age, and energy suit the character''s body and movement, checking takes against the picture.','Synchronization',ARRAY['Kinesic synchrony','Vocal-weight matching','Vocal-age matching','Lip sync','Isochrony']::text[],ARRAY['Casting a voice that clashes with the character''s visible size or age.','Matching lip movements but ignoring whether the voice fits the whole body.','Assuming pitch alone decides fit, when weight and energy matter too.']::text[],ARRAY['Casting the voice for a physically imposing character.','Checking that a dubbed voice suits an actor''s movement and gestures.','Fixing a take where the voice sounds wrong for the body on screen.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bfc7b854-b65b-5f91-aa57-c86de7ffd25f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice-body congruence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bfc7b854-b65b-5f91-aa57-c86de7ffd25f','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bfc7b854-b65b-5f91-aa57-c86de7ffd25f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '57ae63a1-bf4f-5c3f-b5ad-899dd9d2aac3','Voice-continuity defect','A break or inconsistency in a character''s dubbing voice across a program or franchise — such as a mid-series recast, a returning character voiced by a new actor, or an audible change in an actor''s voice quality — that disrupts the audience''s recognition of the character as vocally continuous.','A voice-continuity defect is when a character''s dubbing voice does not stay the same. Maybe a new actor takes over, or the voice suddenly sounds different. Viewers notice the character no longer sounds like themselves.','Naming the fault helps localization teams catch and prevent voice changes that break character identity, so continuity can be protected or a recast handled carefully.','Quality checkers flag scenes or episodes where a recurring character''s voice changes unexpectedly, prompting a re-book of the original actor or a coached recast.','Voice Casting',ARRAY['Voice continuity','Voice recast','Voice double','Voice casting equivalence','Vocal-equivalence casting']::text[],ARRAY['Missing a mid-season recast during quality control, so the defect ships.','Assuming viewers will not notice a changed voice on a recurring character.','Confusing a deliberate in-story voice change with an accidental continuity defect.']::text[],ARRAY['Catching an episode where a recurring character was recast without matching.','Reviewing a franchise dub for voices that changed between films.','Flagging an audible shift in a lead''s dubbing voice mid-series.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='57ae63a1-bf4f-5c3f-b5ad-899dd9d2aac3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice-continuity defect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '57ae63a1-bf4f-5c3f-b5ad-899dd9d2aac3','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='57ae63a1-bf4f-5c3f-b5ad-899dd9d2aac3' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a563821d-65be-5192-94d0-aa703ef40c2f','Accentual synchrony','The matching of stressed and unstressed syllables in the dubbed dialogue to the accentual (stress and emphasis) pattern of the on-screen performance, so that prominent syllables coincide with the moments the original actor emphasises through articulation, gesture, or facial movement. It is a prosodic dimension of synchronisation that keeps the rhythm of emphasis aligned between source and target.','Every language stresses some syllables harder than others. Accentual synchrony means the dubbed voice puts its strong beats where the original actor did. The emphasis lands at the same on-screen moments.','It preserves the rhythm and emphasis of the original performance, so the dubbed delivery feels natural against the actor''s visible stress cues and does not clash with head nods, beats, or gestures.','A dubbing adapter and voice director reshape line wording and delivery so accented syllables fall on the actor''s emphatic moments, checking playback against picture during recording.','Synchronization',ARRAY['Isochrony','Attitudinal prosody','Kinesic synchrony','Breath-group matching','Adaptation pass']::text[],ARRAY['Assuming accentual synchrony only means matching line length, when it concerns where emphasis falls within the line.','Placing target-language stress on syllables that clash with the actor''s visible emphasis or gestures.','Confusing accentual synchrony with lip sync; it governs the rhythm of stress, not mouth shapes.']::text[],ARRAY['Adapting an emphatic argument scene so the dubbed stressed words land on the actor''s forceful head movements.','Rewriting a translated line whose natural stress pattern fought the original''s emphasis.','Directing a voice actor to shift emphasis to match an on-screen beat during recording.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a563821d-65be-5192-94d0-aa703ef40c2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Accentual synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a563821d-65be-5192-94d0-aa703ef40c2f','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a563821d-65be-5192-94d0-aa703ef40c2f' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6ef6d37e-b5f2-567d-9151-b7dcb753afa7','Action-locked vocal','A vocal element — a line, breath, reaction, or effort sound — whose timing is fixed to a specific on-screen physical action, so it must be performed and placed to coincide exactly with that visible movement rather than adjusted for wording or rhythm. The action, not the sentence, dictates the moment of delivery.','Some sounds must hit an exact moment on screen. An action-locked vocal is a grunt, breath, or word tied to a visible move, like a punch landing. The dub must place it right on that action.','It keeps physically driven sounds believable, ensuring a grunt of effort, a gasp, or an emphatic word aligns with the body movement that produces it on screen.','During ADR or dubbing the editor spots and locks these vocalisations to picture first, then fits the surrounding dialogue around them so the visible action stays convincing.','Synchronization',ARRAY['Kinesic synchrony','Breath-action synchrony','Automated dialogue replacement','Isochrony','Vocal efforts']::text[],ARRAY['Timing the sentence for smooth reading and letting the effort sound drift off the visible action.','Treating an action-locked grunt like ordinary dialogue that can be nudged for rhythm.','Recording the vocal without watching the picture, so the sync to the action is only guessed.']::text[],ARRAY['Locking a fighter''s exhale to the frame where a punch connects.','Syncing a character''s gasp to the moment they are grabbed on screen.','Placing an exertion grunt exactly as a heavy object is lifted.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6ef6d37e-b5f2-567d-9151-b7dcb753afa7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Action-locked vocal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6ef6d37e-b5f2-567d-9151-b7dcb753afa7','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6ef6d37e-b5f2-567d-9151-b7dcb753afa7' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e48b05fb-fd28-5fc0-aca5-b184fca06cd0','Adaptation pass','A distinct stage in the dubbing workflow in which a dialogue writer or adapter reworks the raw translation into performable target-language lines that fit synchronisation constraints — lip movements, utterance length, pauses, and register — while preserving meaning and style. It follows the literal translation and feeds the recording sessions.','After a rough translation, someone rewrites the lines so they fit the actor''s mouth and timing. This rewrite stage is the adaptation pass. It keeps the meaning but makes the words sync.','It converts an accurate but unspoken translation into natural dialogue an actor can perform in sync, bridging faithful meaning and the physical limits of the picture.','The adapter works line by line against the video, trimming or reshaping wording so each take matches lip sync and isochrony before the voice actors record.','Dialogue Adaptation',ARRAY['Isochrony','Lip sync','Bilabial correspondence','Attitudinal prosody','Breath-group matching']::text[],ARRAY['Assuming the literal translation can be recorded as-is without an adaptation pass.','Sacrificing meaning to force sync, or ignoring sync to keep a literal wording.','Skipping a picture check, so adapted lines look right on paper but fail against the actor''s mouth.']::text[],ARRAY['Reworking subtitle-style translated lines into lip-syncable dialogue for a feature dub.','Shortening a long target sentence so it fits the on-screen speaking duration.','Reshaping a line so a bilabial in the target lands on the character''s closed-mouth moment.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e48b05fb-fd28-5fc0-aca5-b184fca06cd0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adaptation pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e48b05fb-fd28-5fc0-aca5-b184fca06cd0','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e48b05fb-fd28-5fc0-aca5-b184fca06cd0' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3fbc6497-dfb0-5dd2-8b93-0ddaba5cf953','Affective synchrony','The alignment of the emotional tone of the dubbed performance with the affective state the original actor expresses on screen, so the dubbed voice''s emotion matches the visible facial expression, body language, and dramatic situation. It is a content and character dimension of synchronisation rather than a strictly temporal or articulatory one.','A dubbed voice must feel the same emotion the actor shows. Affective synchrony means the voice''s feeling matches the face on screen. A smiling scene should not sound angry.','It maintains the emotional credibility of the character across languages, preventing a mismatch between what audiences see the actor feeling and what they hear the dub voice conveying.','A voice director coaches the dub actor to match the original''s emotional intensity and colour while watching the performance, adjusting takes where the feeling drifts from the picture.','Synchronization',ARRAY['Attitudinal prosody','Kinesic synchrony','Body-voice fit','Accentual synchrony','Voice casting equivalence','Emotional synchrony (near-synonymous: affective = the character''s overall tone and mood, while emotional = matching feeling and intensity moment to moment)']::text[],ARRAY['Focusing on lip sync and word timing while letting the emotional tone slip out of step with the actor.','Flattening or exaggerating emotion so it no longer matches the visible performance.','Assuming a correct translation guarantees the right feeling without directing the delivery.']::text[],ARRAY['Matching a dub actor''s grief to an on-screen character''s tears.','Correcting a take that sounded neutral over a visibly panicked performance.','Preserving sarcasm in the dub so the tone fits the character''s smirk.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3fbc6497-dfb0-5dd2-8b93-0ddaba5cf953' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Affective synchrony'),'[^a-z0-9]','','g'));
