WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3fbc6497-dfb0-5dd2-8b93-0ddaba5cf953' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f3d61b4-e833-5cf0-b409-eda9dbd41f03','Aperture mismatch','A synchronisation error in which the degree of mouth opening (aperture) implied by the dubbed dialogue does not match the visible jaw and lip openness of the on-screen character — for example a closed or narrow-mouth sound placed over a wide-open vowel, or the reverse. Open and rounded vowels make aperture especially visible in close-ups.','Open sounds need a wide-open mouth; other sounds keep it nearly closed. An aperture mismatch is when the dubbed sound needs a different mouth opening than the one on screen. It looks wrong in close-ups.','Naming this error helps adapters and directors avoid pairing dialogue with the wrong mouth shape, which breaks the illusion that the character is speaking the dubbed words.','When reviewing a close-up, the adapter swaps words so an open vowel in the target falls where the actor''s mouth is open, avoiding a closed sound over a gaping mouth.','Synchronization',ARRAY['Lip sync','Bilabial correspondence','Closed-mouth frame','Closure anchor','Articulatory anchor']::text[],ARRAY['Watching only bilabials and ignoring wide-open vowels, which are just as visible.','Assuming aperture mismatch matters in every shot, not mainly in close-ups.','Choosing a target word for meaning alone when its mouth opening fights the picture.']::text[],ARRAY['Spotting a closed nasal sound placed over a character''s wide-open shout.','Adapting a close-up line so an open vowel lands on the open-mouth frame.','Reviewing a dub for scenes where lip rounding on screen clashes with the target words.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f3d61b4-e833-5cf0-b409-eda9dbd41f03' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Aperture mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f3d61b4-e833-5cf0-b409-eda9dbd41f03','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f3d61b4-e833-5cf0-b409-eda9dbd41f03' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e240d12a-4ce1-562c-8e98-7a2f91b8c48c','Articulatory anchor','A visually salient articulatory event in the source performance — typically a bilabial closure, a labiodental, or a wide-open vowel — that a dubbing adapter treats as a fixed reference point to which the target dialogue must correspond. These anchors mark the moments where lip sync is most visible and therefore least negotiable.','Some mouth movements are easy to see, like lips closing on a ''b'' or a wide-open ''ah''. An articulatory anchor is one of these clear moments. The dub must match its sound to that spot.','It gives the adapter concrete points to hit, focusing sync effort on the few highly visible articulations that most affect believability instead of every phoneme.','The adapter marks the source''s bilabials and open vowels, then builds the target line so matching sounds fall on those anchor frames while freer words fill the gaps between.','Synchronization',ARRAY['Bilabial correspondence','Closure anchor','Aperture mismatch','Lip sync','Closed-mouth frame']::text[],ARRAY['Trying to match every phoneme instead of prioritising the visible anchor points.','Missing a bilabial or open-vowel anchor and letting the target sound drift.','Treating off-camera or wide shots as if their weak anchors were as strict as close-ups.']::text[],ARRAY['Marking each bilabial in a close-up line as a sync anchor.','Building a dubbed sentence around the actor''s one visible open-mouth vowel.','Deciding which articulations must match and which can be freely reworded.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e240d12a-4ce1-562c-8e98-7a2f91b8c48c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Articulatory anchor'),'[^a-z0-9]','','g'));
