INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9dcab296-6374-5425-bb41-e8171e649a16','Attitudinal prosody','The use of prosodic features — intonation, pitch range, loudness, tempo, and rhythm — to convey a speaker''s attitude or stance toward the listener or the message, such as politeness, irony, doubt, or enthusiasm, as distinct from lexical content. In dubbing it is the prosodic layer a voice actor must reproduce so the target delivery carries the same attitude as the original.','How you say something shows your attitude, not just the words. Attitudinal prosody is the pitch, pace, and tone that signal feelings like doubt or sarcasm. A dub voice must copy it.','It carries meaning that words alone do not, so reproducing it keeps a dubbed character''s stance and interpersonal tone faithful to the original performance.','A voice director listens for the original''s rising, falling, or clipped delivery and guides the dub actor to reproduce the same attitudinal contours in the target language.','Voice Performance',ARRAY['Affective synchrony','Accentual synchrony','Isochrony','Kinesic synchrony','Body-voice fit']::text[],ARRAY['Reproducing the words and emotion but flattening the intonation that signalled attitude.','Copying the original''s pitch contour literally when target-language prosody expresses the same attitude differently.','Confusing attitudinal prosody with raw emotion; it also signals stance like politeness or irony.']::text[],ARRAY['Directing a dub actor to keep a sarcastic rise-fall on a seemingly polite line.','Preserving a doubtful, hesitant tone across a translated question.','Matching an enthusiastic, fast-tempo delivery in the target performance.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9dcab296-6374-5425-bb41-e8171e649a16' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Attitudinal prosody'),'[^a-z0-9]','','g'));
