SELECT '9dcab296-6374-5425-bb41-e8171e649a16','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9dcab296-6374-5425-bb41-e8171e649a16' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cc3f8e34-e1b8-5641-8184-b2397ab9e6f4','Bilabial correspondence','The matching of bilabial articulations — sounds made with both lips, the consonants /p/, /b/, and /m/ — between the source dialogue and the dubbed target dialogue, so the visible mouth closures on screen coincide with bilabial sounds in the target language. Because bilabials require a clearly visible lip closure, they are among the most constraining points for lip synchrony, especially in close-ups.','The sounds in ''p'', ''b'', and ''m'' close both lips, which viewers clearly see. Bilabial correspondence means the dub puts these lip-closing sounds where the original mouth closes. It keeps close-ups believable.','It preserves lip-sync credibility at the moments audiences most notice, ensuring the character''s visible lip closures line up with matching sounds in the dubbed words.','An adapter identifies the source''s bilabials in close-up and reworks the target line so a lip-closing consonant falls on each visible closure without inventing extra ones.','Synchronization',ARRAY['Lip sync','Articulatory anchor','Closure anchor','Closed-mouth frame','Aperture mismatch']::text[],ARRAY['Adding new bilabials in the target where the original mouth never closed, creating a visible mismatch.','Ignoring bilabials in close-ups where the lip closure is unmistakable.','Assuming any consonant will do, when only lip-closing sounds match a visible closure.']::text[],ARRAY['Reworking a close-up so the target word''s lip-closing consonant lands on the character''s closure.','Avoiding a target phrase that forces a bilabial where the on-screen mouth stays open.','Checking a dubbed name against the original actor''s visible bilabial articulations.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cc3f8e34-e1b8-5641-8184-b2397ab9e6f4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bilabial correspondence'),'[^a-z0-9]','','g'));
