SELECT 'cc3f8e34-e1b8-5641-8184-b2397ab9e6f4','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cc3f8e34-e1b8-5641-8184-b2397ab9e6f4' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ba1ddc3-d134-5737-b192-1019d1245d59','Body-voice fit','The perceptual match between a dubbing actor''s vocal qualities — timbre, weight, age, and energy — and the physical appearance and body of the on-screen character, so the voice sounds as though it plausibly belongs to that body. It is a casting and performance criterion within kinesic and character synchronisation.','A voice should sound like it belongs to the body on screen. Body-voice fit is how well a dub actor''s voice suits the character''s size, age, and look. A large character sounding tiny breaks it.','It sustains the illusion that the character is really speaking, since a voice that clashes with the visible body pulls audiences out of the story.','Casting directors audition dub actors against the picture, choosing voices whose weight and age read as a natural fit for each character''s on-screen body.','Voice Casting',ARRAY['Voice casting equivalence','Affective synchrony','Kinesic synchrony','Attitudinal prosody','Vocal-weight matching']::text[],ARRAY['Casting purely on acting skill while ignoring whether the voice suits the body.','Matching only age and missing timbre or physical-weight cues.','Assuming the original casting''s fit transfers automatically to every target-language voice.']::text[],ARRAY['Casting a deep, heavy voice for a large, imposing character.','Rejecting a take where a child character sounded like an adult.','Matching a frail elderly appearance with a suitably aged vocal quality.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ba1ddc3-d134-5737-b192-1019d1245d59' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Body-voice fit'),'[^a-z0-9]','','g'));
