SELECT '8ba1ddc3-d134-5737-b192-1019d1245d59','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ba1ddc3-d134-5737-b192-1019d1245d59' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fd35144f-e00b-5536-b05d-a802674f4078','Boundary synchrony','The alignment of the start and end points of dubbed utterances — and the pauses between them — with the corresponding boundaries in the on-screen performance, so the character is seen to begin and stop speaking at the same moments as the dubbed dialogue. It is closely tied to isochrony but focuses on the edges of speech rather than overall duration.','A dubbed line should start when the mouth starts and stop when it stops. Boundary synchrony means the speech begins and ends on the right frames. Pauses fall in the same places too.','It prevents the jarring effect of a character whose mouth moves in silence or stays still while the dub keeps talking, keeping the edges of speech aligned with picture.','The adapter and editor trim lead-ins and tails so each dubbed line''s onset and offset match the frames where the character opens and closes their mouth.','Synchronization',ARRAY['Isochrony','Breath-group matching','Closed-mouth frame','Lip sync','Adaptation pass']::text[],ARRAY['Getting overall line length right but starting or ending on the wrong frame.','Letting the dub continue after the character''s mouth has already stopped.','Ignoring where pauses fall, so silences land during visible speech.']::text[],ARRAY['Trimming a dubbed line so it stops exactly when the character closes their mouth.','Aligning a mid-line pause with the character''s on-screen breath break.','Fixing a take that began before the actor started speaking.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fd35144f-e00b-5536-b05d-a802674f4078' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boundary synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fd35144f-e00b-5536-b05d-a802674f4078','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fd35144f-e00b-5536-b05d-a802674f4078' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ce3c2d0e-d06d-564a-a1a9-70a827a57c92','Breath-action synchrony','The alignment of audible breaths in the dubbed track with the character''s visible breathing and physical exertion on screen, so intakes and exhalations coincide with the movements — running, lifting, gasping — that would produce them. It is a facet of kinesic synchronisation applied to non-verbal breath sounds.','People breathe harder when they move or strain. Breath-action synchrony means the dub''s breaths match what the body does on screen. A gasp should land when the character actually gasps.','It keeps a performance physically believable, tying the dub''s breaths to the visible effort and movement instead of leaving them floating or missing.','During dubbing the actor watches the picture and places breaths on the exertions, and the editor nudges them so each intake matches the on-screen action.','Synchronization',ARRAY['Kinesic synchrony','Action-locked vocal','Breath-group matching','Vocal efforts','Isochrony']::text[],ARRAY['Recording breaths for rhythm alone and letting them drift off the visible action.','Dropping breaths entirely, so a straining character sounds effortless.','Placing a calm breath over a scene of heavy physical exertion.']::text[],ARRAY['Syncing a runner''s panting to their on-screen strides.','Matching a sharp intake to the moment a character is startled.','Placing an exhale as a character sets down a heavy load.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ce3c2d0e-d06d-564a-a1a9-70a827a57c92' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath-action synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ce3c2d0e-d06d-564a-a1a9-70a827a57c92','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ce3c2d0e-d06d-564a-a1a9-70a827a57c92' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f3e985a-1435-5105-a2a2-b8f0c25d5b34','Breath-group matching','The alignment of breath groups — stretches of speech produced on a single exhalation between breaths — in the dubbed dialogue with those of the on-screen performance, so the dub takes breaths where the character does and phrases the target line into comparable spans. It supports natural phrasing and helps pauses and utterance boundaries fall on visible breath points.','We speak in chunks, pausing to breathe between them. Breath-group matching means the dub breaks its lines into the same chunks as the original. It breathes where the character breathes.','It makes the dubbed delivery sound naturally phrased and keeps breaths and pauses landing where the audience sees the character pause, reinforcing sync.','The adapter shapes the translated line so its phrases fit the character''s breath points, and the actor breathes at those same points during recording.','Synchronization',ARRAY['Boundary synchrony','Isochrony','Breath-action synchrony','Adaptation pass','Accentual synchrony']::text[],ARRAY['Writing one long unbroken target phrase where the original clearly breathed mid-line.','Placing breaths for the actor''s comfort instead of at the character''s visible breath points.','Ignoring phrasing and focusing only on total line length.']::text[],ARRAY['Splitting a long dubbed sentence to breathe where the character does.','Matching a dramatic mid-sentence breath in an emotional monologue.','Phrasing target dialogue so pauses fall on the original''s breath breaks.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f3e985a-1435-5105-a2a2-b8f0c25d5b34' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath-group matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0f3e985a-1435-5105-a2a2-b8f0c25d5b34','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0f3e985a-1435-5105-a2a2-b8f0c25d5b34' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '38874a88-2bbf-5cb0-9257-be68a9fd8e7d','Closed-mouth frame','A frame or short span of frames in which the on-screen character''s mouth is fully closed — typically at a bilabial articulation or between utterances — which constrains the dubbed dialogue to a matching closed-mouth sound or silence at that point. Adapters use these frames as strict reference points for lip synchrony.','A closed-mouth frame is a moment when the character''s lips are shut. The dub must have a lip-closing sound or silence there. You cannot put an open, loud vowel on a closed mouth.','It flags the points where only a closed mouth is believable, guiding word choice so the target sound does not contradict the visible lips.','The adapter notes closed-mouth frames in close-ups and ensures a bilabial or a pause falls there rather than an open vowel that would expose the mismatch.','Synchronization',ARRAY['Bilabial correspondence','Closure anchor','Aperture mismatch','Articulatory anchor','Lip sync']::text[],ARRAY['Placing an open vowel or loud shout on a frame where the mouth is clearly shut.','Overlooking closed-mouth frames in close-ups where they are most visible.','Assuming silence is the only option, when a bilabial sound also fits a closed mouth.']::text[],ARRAY['Ensuring a lip-closing consonant or a pause falls where the character''s lips are closed.','Rejecting a dubbed word that puts a wide vowel on a shut-mouth frame.','Marking closed-mouth frames before adapting a close-up dialogue exchange.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='38874a88-2bbf-5cb0-9257-be68a9fd8e7d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Closed-mouth frame'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '38874a88-2bbf-5cb0-9257-be68a9fd8e7d','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='38874a88-2bbf-5cb0-9257-be68a9fd8e7d' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '574be23c-e3d2-5845-b9c1-ec0317c45d23','Closure anchor','A visible oral closure in the source performance — most often a bilabial lip closure — that a dubbing adapter uses as a fixed anchor point to which a corresponding closed-mouth sound in the target dialogue must be matched. It is a specific type of articulatory anchor centred on moments the mouth shuts.','When lips close on screen, that moment is easy to see. A closure anchor is a lip-closing point the dub must hit. The target line needs a lip-closing sound right there.','It marks the least forgiving lip-sync points, so adapters can guarantee the target dialogue closes the mouth exactly where the picture does.','The adapter tags each visible lip closure as an anchor and reworks the target line so a bilabial lands on it, leaving freer wording between anchors.','Synchronization',ARRAY['Bilabial correspondence','Articulatory anchor','Closed-mouth frame','Aperture mismatch','Lip sync']::text[],ARRAY['Missing a visible lip closure and letting an open sound fall on it.','Creating new closure anchors in the target that the original mouth never made.','Treating every consonant as an anchor instead of the visible closures.']::text[],ARRAY['Anchoring a target bilabial to the frame where the character''s lips meet.','Building a close-up line around two visible lip closures.','Checking that no dubbed open vowel overrides an on-screen mouth closure.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='574be23c-e3d2-5845-b9c1-ec0317c45d23' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Closure anchor'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '574be23c-e3d2-5845-b9c1-ec0317c45d23','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='574be23c-e3d2-5845-b9c1-ec0317c45d23' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a14d4d70-1cc7-55a3-b82f-842662e4da5f','Closure mismatch','In lip-sync dubbing, a phonetic-synchrony error in which a visible lip closure on screen — the momentary sealing of the lips required to articulate a bilabial consonant (/p/, /b/, /m/) — is not matched by a corresponding closed-lip sound in the dubbed line at that moment, or in which a closed-lip sound is heard while the on-screen mouth stays open. Because bilabial closures are among the most conspicuous articulatory movements, such mismatches are readily noticed by viewers.','Some sounds, like ''p,'' ''b,'' and ''m,'' make the lips press shut. A closure mismatch is when the screen shows lips closing but the new voice has no such sound. It also counts when a closed-lip sound is heard yet the mouth stays open. These slips are easy to spot because we clearly see lips meet.','Naming this error helps dubbing writers and voice directors protect phonetic synchrony at the most visible points, so the dubbed voice stays believable in close-ups.','A dialogue writer rewrites a line so a target-language word with a bilabial sound falls where the actor''s lips visibly close, and a director flags takes where closures do not line up.','Synchronization',ARRAY['Lip sync','Phonetic synchrony','Isochrony','Kinesic synchrony','Dialogue adaptation']::text[],ARRAY['Ignoring bilabial closures in close-up shots, where a mismatch is most visible.','Matching overall line length but not the specific lip-closing sounds.','Remembering /p/ and /b/ but forgetting that /m/ also needs a visible closure.']::text[],ARRAY['Adapting a close-up line so a ''b'' or ''m'' lands on the visible lip closure.','Reviewing a dub take where the mouth shuts but no closed-lip sound is heard.','Choosing between synonyms to place a bilabial sound at the right frame.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a14d4d70-1cc7-55a3-b82f-842662e4da5f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Closure mismatch'),'[^a-z0-9]','','g'));
