INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5a359ff2-c74f-5720-b893-3e06481d43c3','Compression threshold','In dynamic range compression, the threshold is the signal level, set in decibels, above which a compressor begins to apply gain reduction. Signal that exceeds the threshold is attenuated according to the compressor''s ratio, while signal below the threshold passes through essentially unchanged in a hard-knee downward compressor.','A compressor makes loud sounds quieter. The threshold is the volume level where it starts working. Sounds louder than the threshold get turned down. Sounds below it pass through untouched.','The threshold sets where compression begins, letting an engineer control only the louder peaks while leaving quieter material alone, which is how a compressor evens out dynamics.','A dialogue mixer lowers the threshold so more of a performance is caught by the compressor, or raises it so only the loudest peaks are tamed, then sets ratio, attack, and release to suit the material.','Audio Processing',ARRAY['Ratio','Attack time','Release time','Gain reduction','Limiter']::text[],ARRAY['Confusing the threshold, which sets where compression starts, with the ratio, which sets how hard it compresses.','Setting the threshold so low that the whole signal is squashed and sounds lifeless.','UNSAFE: Adding heavy compression and make-up gain, then monitoring at high levels for a long session, which raises average loudness and risks noise-induced hearing loss.']::text[],ARRAY['Compressing a dubbed dialogue stem so levels sit consistently in the mix.','Dialing in a threshold on a vocal so only the loud words are controlled.','Setting threshold and ratio to help meet a delivery loudness specification.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5a359ff2-c74f-5720-b893-3e06481d43c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compression threshold'),'[^a-z0-9]','','g'));
