INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '53f8aeb8-298c-5ee8-94f7-64afbabcc97d','Deictic synchrony','A form of audiovisual synchrony in which the deictic elements of the target dialogue — words that point to people, objects, places, or moments, such as ''this,'' ''that,'' ''here,'' ''there,'' and ''now'' — are aligned with the on-screen gestures and referents they accompany, so a spoken pointing word coincides with the character''s pointing action or the object shown. It is closely related to kinesic synchrony and to the broader requirement of semiotic cohesion between soundtrack and image.','Some words point at things, like ''this,'' ''that,'' ''here,'' and ''there.'' Deictic synchrony means those words line up with what the character points at on screen. If an actor points and says ''that one,'' the new voice must point with words at the same moment.','It keeps the dubbed dialogue consistent with the picture, so verbal pointing matches visual pointing and the audience is not confused about what a character refers to.','A dubbing adapter positions the target-language pointing word to fall on the gesture or cutaway, and reworks a line when the reference would otherwise land on the wrong shot.','Synchronization',ARRAY['Kinesic synchrony','Lip sync','Isochrony','Dialogue adaptation','Semiotic cohesion']::text[],ARRAY['Translating a pointing word without checking what is shown or gestured on screen.','Letting ''this'' and ''that'' swap so the words no longer match the visible object.','Placing the reference on the wrong beat, so speech and gesture drift apart.']::text[],ARRAY['Adapting a line where a character points and says ''give me that.''','Timing a demonstrative word to a cutaway of the object being named.','Fixing a dub where ''here'' is spoken but the gesture points away.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='53f8aeb8-298c-5ee8-94f7-64afbabcc97d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Deictic synchrony'),'[^a-z0-9]','','g'));
