INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b720c0ab-00df-50b2-ba90-21d955a0cc48','Dialogue adaptation','The stage of the dubbing process in which a raw or literal translation of the source dialogue is rewritten into natural, speakable target-language lines that satisfy the technical constraints of dubbing — chiefly lip sync, isochrony, and kinesic synchrony — while preserving meaning, register, and characterization. It is often performed by a dedicated dialogue writer or adapter, separately from the initial translation.','Dialogue adaptation is reshaping a translation so actors can speak it naturally. The new lines must fit the timing and mouth movements on screen. A writer trims or rewrites words so the dub sounds real and stays in sync.','It bridges accurate translation and performable dubbing, so the target lines both carry the right meaning and fit the picture and timing.','A dialogue writer works line by line against the video, adjusting word choice and length so each take matches the actor''s mouth, pauses, and gestures.','Dialogue Adaptation',ARRAY['Dubbing adaptation','Isochrony','Lip sync','Kinesic synchrony','Dubbese','Dialogue calque']::text[],ARRAY['Translating literally without adjusting length, so lines run long or short against the picture.','Sacrificing meaning just to hit lip sync, when small rephrasing could keep both.','Ignoring register, so a casual character suddenly sounds formal.']::text[],ARRAY['Rewriting a subtitle-style translation into lip-synced dubbing lines.','Shortening a long target sentence to fit the on-screen speaking time.','Adjusting a joke so it works in the target language and still fits the mouth.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b720c0ab-00df-50b2-ba90-21d955a0cc48' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue adaptation'),'[^a-z0-9]','','g'));
