INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9cb416cf-5c71-589c-95e8-3db2309984a9','Dialogue calque','A calque appearing in dubbed dialogue: a target-language expression produced by translating a source expression word-for-word, reproducing its structure or idiom rather than using the natural target-language equivalent. Frequent calquing is a hallmark of ''dubbese'' and can yield stilted, source-flavoured lines.','A calque is a word-for-word copy of a foreign phrase. It follows the original wording instead of what people really say. In dubbing, too many calques make the lines sound odd and foreign.','The concept flags a common source-language interference in dubbing, helping writers spot lines that copy the original too literally instead of sounding native.','A reviewer catches calqued idioms in a dub script and replaces them with idiomatic target-language phrasing that still fits the sync.','Dubbing Language',ARRAY['Dubbese','Dubbing cliché','Dialogue adaptation','Dubbing adaptation','Isochrony']::text[],ARRAY['Keeping a literal calque because it fits the lip movements, at the cost of natural speech.','Not recognizing an idiom, so it is translated word-for-word.','Assuming a calque is always wrong, when some have entered normal usage.']::text[],ARRAY['Spotting a word-for-word idiom in a dub script during review.','Replacing a calqued greeting with a natural target-language one.','Deciding whether an established calque can stay or should be reworded.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9cb416cf-5c71-589c-95e8-3db2309984a9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue calque'),'[^a-z0-9]','','g'));
