SELECT '9cb416cf-5c71-589c-95e8-3db2309984a9','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9cb416cf-5c71-589c-95e8-3db2309984a9' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aab842a5-8187-5f15-9735-ab9dccb32f8b','Dialogue contamination','The unwanted presence of source-language dialogue within an audio stem that must be free of it — most often residual spoken lines or dialogue bleed remaining in a music-and-effects (M&E) stem. Because a fully-filled M&E must contain no original dialogue, contamination blocks clean localization until the offending speech is removed or re-created.','For dubbing, the background mix must have no original speech in it. Dialogue contamination is leftover talking that leaks into that mix. It has to be removed, or the new language cannot replace it cleanly.','The term identifies a defect that stops a title being dubbed, prompting teams to keep dialogue fully separated so the M&E can carry any language.','A quality checker auditions the M&E for stray original lines or bleed and sends contaminated sections back for cleanup or re-recording before localization.','Localization Prep',ARRAY['Music and effects track','Dialogue guide stem','Dialogue-free production effect','Optional dialogue','Stem']::text[],ARRAY['Leaving faint original dialogue in the M&E because it seems quiet, when the dub will expose it.','Confusing translatable crowd lines with neutral ambience and leaving them in the mix.','Assuming panning dialogue out is enough, when bleed still remains in other channels.']::text[],ARRAY['Auditing an M&E and finding a whispered original line left in.','Rejecting a stem where dialogue bled into the effects channels.','Cleaning production dialogue out of a mix before sending it for dubbing.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aab842a5-8187-5f15-9735-ab9dccb32f8b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue contamination'),'[^a-z0-9]','','g'));
