INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c1327c2-c1f6-5844-a1c7-d225deaced64','Dialogue guide stem','A reference audio track — typically the original-language dialogue stem, or a mono mixdown of it — delivered alongside a music-and-effects (M&E) package so the dubbing team can hear the original performances for timing, sync, and interpretation. It is a guide only and is not part of the final mixed M&E.','This is the original spoken track sent with the background mix. Dubbing teams listen to it as a guide. It shows the timing, tone, and feeling of each line. It is only a reference and is not mixed into the final sound.','It gives the dubbing translator, adapter, and actors the original delivery to match, so the new voices land on the same beats and carry the same intent.','A dubbing studio loads the dialogue guide against the picture and M&E, using it to place lines, copy pauses, and match emphasis while recording the target language.','Deliverables',ARRAY['Music and effects track','Dialogue contamination','Isochrony','Lip sync','Stem']::text[],ARRAY['Mistaking the dialogue guide for a track to be mixed into the M&E.','Ignoring the guide''s timing and pauses, so the dub drifts out of sync.','Deleting the guide before recording, losing the reference for performance.']::text[],ARRAY['Loading the original dialogue guide to time a dub session.','Checking a target line''s emphasis against the guide track.','Delivering an M&E package with the dialogue guide included for reference.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c1327c2-c1f6-5844-a1c7-d225deaced64' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue guide stem'),'[^a-z0-9]','','g'));
