WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3c1327c2-c1f6-5844-a1c7-d225deaced64' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c0317129-b9c2-5343-9e8c-13c199f2e017','Dialogue-free production effect','A sound effect captured live during filming (a production effect, or PFX) — such as footsteps, prop handling, doors, or object interactions — that contains no intelligible speech and can therefore be retained in, or lifted into, the music-and-effects (M&E) stem for use in every language version. Only production audio free of dialogue may remain in the M&E.','On set, microphones pick up real sounds like footsteps and doors. If a sound has no talking in it, it can stay in the background mix. These dialogue-free sounds work in every language. Sounds with speech cannot stay.','Keeping dialogue-free production sounds preserves authentic, synced effects in the M&E without adding source-language speech, reducing the need to rebuild them with foley.','An M&E engineer lifts clean prop and movement sounds from the production dialogue stem into the effects, while discarding or replacing any that carry speech.','Music & Effects',ARRAY['Music and effects track','Foley','Dialogue contamination','Dialogue guide stem','Production sound']::text[],ARRAY['Pulling a production effect into the M&E that still has faint dialogue under it.','Rebuilding every effect with foley when clean production sounds already exist.','Assuming all on-set sound is unusable, when dialogue-free effects are valuable.']::text[],ARRAY['Lifting clean footsteps from the dialogue stem into the M&E.','Deciding a prop sound is dialogue-free and can stay for all languages.','Replacing a production effect that has speech bleed with a foley version.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c0317129-b9c2-5343-9e8c-13c199f2e017' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue-free production effect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c0317129-b9c2-5343-9e8c-13c199f2e017','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c0317129-b9c2-5343-9e8c-13c199f2e017' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4a320b5c-b55b-5f9a-977b-23eb78461595','Discourse-prosody matching','In dubbing adaptation and performance, the practice of shaping the prosody of the target dialogue — its intonation, stress, rhythm, and pausing — so that it fits both the discourse function of each line (question, emphasis, contrast, turn-taking) and the prosodic contour of the original delivery, keeping the dubbed speech natural and consistent with the picture.','Prosody is the melody and rhythm of speech — how we stress words and raise or lower our voice. This practice matches that melody to the meaning of each line and to the original. A question should still sound like a question, with stress in the right place.','It prevents flat or misplaced delivery, so emphasis, questions, and emotion in the dub align with the scene and the source performance.','A voice director guides actors to put stress and intonation where the line and picture demand, and an adapter phrases lines so the natural stress falls in the right place.','Synchronization',ARRAY['Isochrony','Kinesic synchrony','Dialogue adaptation','Lip sync','Dubbing adaptation']::text[],ARRAY['Matching words and timing but delivering them with flat or wrong intonation.','Putting stress on the wrong word, so the line''s meaning shifts.','Copying the source melody so exactly that the target language sounds unnatural.']::text[],ARRAY['Directing an actor so a dubbed question rises like a question.','Placing emphasis on the correct word to match the scene.','Reworking a line so its natural stress fits the character''s delivery.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4a320b5c-b55b-5f9a-977b-23eb78461595' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Discourse-prosody matching'),'[^a-z0-9]','','g'));
