INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '727dd689-91a1-5fa6-b512-499ab0037d17','Domestic version','The version of a completed film or program mastered for distribution in its country and language of origin — carrying the original-language dialogue mix and domestic on-screen text — as distinguished from the international (or ''foreign/textless'') version, which is supplied with a music-and-effects track and without burned-in text so it can be localized and dubbed.','The domestic version is the cut made for the home country. It has the original language and the local on-screen text. A separate international version leaves room for other languages. That one comes with a music-and-effects track for dubbing.','Separating the domestic from the international version lets distributors serve the home market with the finished original while supplying a clean, textless base for dubbing and subtitling abroad.','A delivery manager provides the domestic version for local release and a textless international version with M&E so foreign territories can dub or subtitle without covering original text or speech.','Deliverables',ARRAY['Music and effects track','Textless elements','International version','Dialogue guide stem','Localization']::text[],ARRAY['Sending the domestic version abroad, forcing dubbers to work over original dialogue and text.','Forgetting to deliver the textless backgrounds needed for the international version.','Assuming one master serves all markets without a separate localization version.']::text[],ARRAY['Delivering the domestic cut for home-country broadcast or release.','Preparing a textless international version alongside the domestic one.','Localizing a title using the international version rather than the domestic mix.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='727dd689-91a1-5fa6-b512-499ab0037d17' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Domestic version'),'[^a-z0-9]','','g'));
