SELECT '727dd689-91a1-5fa6-b512-499ab0037d17','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='727dd689-91a1-5fa6-b512-499ab0037d17' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f85cc176-afc4-5b1e-8832-287ef1d9c38d','Dubability','The degree to which a given audiovisual text lends itself to dubbing, determined by factors such as dialogue density and speed, the frequency of tight lip-sync close-ups, the visibility of articulation, and the amount of culturally specific or wordplay-heavy content that resists timing-constrained translation.','Dubability is how easy a show is to dub. Lots of close-ups and fast talking make it harder. Heavy jokes and local references also make it harder. Content with fewer of these is easier to dub well.','The idea helps teams anticipate how much effort a title needs, since some content fits target-language lip sync and timing far more easily than others.','A localization producer scopes a title''s dubability to plan schedule and budget, flagging scenes with tight close-ups or dense, culture-bound dialogue as harder to sync.','Localization',ARRAY['Lip sync','Isochrony','Dialogue adaptation','Kinesic synchrony','Dubbese']::text[],ARRAY['Assuming every title dubs equally easily, ignoring close-ups and dialogue density.','Underbudgeting a hard-to-dub title because the script looked short.','Judging dubability from the script alone, without watching the picture.']::text[],ARRAY['Assessing a fast-talking comedy for how hard it will be to dub.','Scoping a title''s close-up-heavy scenes before quoting a dub schedule.','Comparing two shows to decide which needs more adaptation effort.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f85cc176-afc4-5b1e-8832-287ef1d9c38d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubability'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
