INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2d2766f9-ef12-5f6d-bfa5-37c0477bae0d','Dubbese','The distinctive, somewhat artificial language variety characteristic of dubbed dialogue: a form of ''prefabricated orality'' that sounds spoken and spontaneous but is actually planned and constrained by translation and synchrony, marked by recurrent calques, standardized phrasing, and stock expressions rarely heard in genuinely spontaneous speech.','Dubbese is the special way dubbed dialogue tends to sound. It seems like normal talking but is carefully planned. It often reuses set phrases and copies the original wording. Real conversation rarely sounds exactly like it.','Naming this variety helps writers recognize and avoid the artificial patterns that creep into dubbing, so target dialogue sounds more like real speech.','A dialogue writer edits out tell-tale dubbese — calqued idioms and stock lines — replacing them with phrasing a native speaker would actually use, within the sync limits.','Dubbing Language',ARRAY['Prefabricated orality','Dialogue calque','Dubbing cliché','Dialogue adaptation','Dubbing adaptation']::text[],ARRAY['Accepting stock dubbing phrases as normal because they are familiar from other dubs.','Copying source idioms directly, adding to the artificial dubbese sound.','Standardizing all speech, so distinct characters lose their own voice.']::text[],ARRAY['Editing a dub script to remove familiar dubbese phrases.','Spotting calqued idioms that mark a line as translated.','Coaching an actor away from a stiff, typical dubbing delivery.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2d2766f9-ef12-5f6d-bfa5-37c0477bae0d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbese'),'[^a-z0-9]','','g'));
