INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c26012f3-e09d-5d15-b81e-c256db826c28','Dubbing adaptation','The process of turning a translation of the source dialogue into a fully synchronized, performable dubbing script — adjusting wording, length, and phrasing to meet lip sync, isochrony, and kinesic synchrony while preserving meaning and character. In many workflows it is a distinct role (the adapter or dialogue writer) that follows the initial translation.','Dubbing adaptation turns a translation into a script actors can perform. The words are reshaped to fit the mouths, timing, and gestures on screen. It keeps the meaning while making each line land in sync.','It exists to make a translated script actually dubbable, closing the gap between accurate meaning and the strict timing and lip demands of dubbing.','An adapter reworks each translated line against the picture, changing word choices and length so takes match the actor''s mouth and the scene''s rhythm.','Dialogue Adaptation',ARRAY['Dialogue adaptation','Isochrony','Lip sync','Kinesic synchrony','Dubbese','Dialogue calque']::text[],ARRAY['Treating adaptation as simple translation and skipping the sync work.','Over-trimming lines until the meaning is lost.','Adapting to lip sync but ignoring the timing of pauses and gestures.']::text[],ARRAY['Turning a rough translation into a synced dubbing script.','Reworking line length to match on-screen speaking time.','Adjusting phrasing so a bilabial sound hits a visible lip closure.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c26012f3-e09d-5d15-b81e-c256db826c28' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing adaptation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c26012f3-e09d-5d15-b81e-c256db826c28','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c26012f3-e09d-5d15-b81e-c256db826c28' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '16314ea8-4375-5ab8-8846-3dee4c295a02','Dubbing cliché','A recurrent, formulaic expression characteristic of dubbese — often a calqued or standardized phrase, such as a fixed rendering of a source-language exclamation or idiom — that appears repeatedly across dubbed texts and marks the dialogue as translated rather than spontaneously spoken.','A dubbing cliché is a stock phrase that keeps showing up in dubs. It usually copies the original language too closely. People rarely say it in normal life. Hearing it hints that the dialogue was translated.','Identifying these clichés helps writers avoid worn, translation-flavoured phrasing and keep dubbed lines fresh and believable.','A reviewer flags repeated dubbing clichés in a script and swaps them for natural, varied target-language expressions that still fit the sync.','Dubbing Language',ARRAY['Dubbese','Dialogue calque','Prefabricated orality','Dialogue adaptation','Dubbing adaptation']::text[],ARRAY['Reusing a familiar dubbing phrase because it fits the timing, not because it sounds natural.','Not noticing a cliché because it is common across many dubs.','Replacing one cliché with another instead of with natural speech.']::text[],ARRAY['Catching a stock dubbed exclamation during script review.','Replacing an overused calqued phrase with natural wording.','Comparing a dub to real speech to spot tell-tale clichés.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='16314ea8-4375-5ab8-8846-3dee4c295a02' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dubbing cliché'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '16314ea8-4375-5ab8-8846-3dee4c295a02','39203cec-660c-4a27-972c-21f7a63623b9',true
