INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cbe55668-4c14-5b52-ba46-2b88f9ed2d0f','Effort synchrony','The alignment of a dubbed actor''s audible vocal efforts — breaths, grunts, gasps, and exertion sounds — with the physical effort visible in the original performance, so the non-verbal exertions land on the same on-screen actions. It is a component of overall performance synchrony rather than a match of spoken words.','Effort synchrony means matching grunts, breaths, and strain sounds to what the body does on screen. When a character lifts something heavy, the dubbed grunt must land at the same moment.','It keeps a dubbed performance physically believable, ensuring exertion sounds coincide with the visible movement that produces them.','A dubbing actor watches the picture and voices efforts on the exact frames of impact or strain, and the editor nudges them into sync with the on-screen action.','Synchronization',ARRAY['Vocal efforts','Kinesic synchrony','Isochrony','Automated dialogue replacement','Reactions','Lip sync']::text[],ARRAY['Recording efforts flatly without watching the picture, so grunts and breaths drift off the visible action.','Treating efforts as optional filler and omitting them, which flattens physical scenes.','Matching the word timing but ignoring where the exertion sound must actually hit.']::text[],ARRAY['Dubbing a fight scene where each punch needs a matching exertion sound.','Syncing a character''s breaths to visible running or climbing.','Placing a lifting grunt on the frame where the character strains.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cbe55668-4c14-5b52-ba46-2b88f9ed2d0f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Effort synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cbe55668-4c14-5b52-ba46-2b88f9ed2d0f','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cbe55668-4c14-5b52-ba46-2b88f9ed2d0f' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '22229e0d-4e4d-57d2-96f6-d0074231d5cb','Emotional synchrony','The matching of the emotional tone, intensity, and register of the dubbed vocal delivery to the emotion expressed in the original on-screen performance, so the target voice conveys the same feeling as the source at each moment.','Emotional synchrony means the dubbed voice must feel the same emotion as the actor on screen. If the face shows fear, the new voice has to sound afraid too.','It preserves the emotional meaning of a scene across languages, so viewers read the same feelings from voice and picture together.','The dubbing director guides the actor to match anger, joy, or grief to the visible expression, re-recording lines whose feeling does not fit the face.','Synchronization',ARRAY['Effort synchrony','Emotional-arc matching','Kinesic synchrony','Dialogue adaptation','Voice casting equivalence','Lip sync','Affective synchrony (near-synonymous: emotional = per-moment match of feeling and intensity, while affective = the character''s overall tone and mood)']::text[],ARRAY['Reading lines for correct words while ignoring whether the emotion matches the face.','Over-acting the target delivery so it exceeds the restraint of the original performance.','Assuming a literal translation carries the same emotional weight as the source line.']::text[],ARRAY['Directing a tearful monologue so the dubbed cry matches the visible grief.','Checking that a whispered threat stays menacing in the target language.','Re-recording a laugh that sounded forced against a genuinely amused face.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='22229e0d-4e4d-57d2-96f6-d0074231d5cb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Emotional synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '22229e0d-4e4d-57d2-96f6-d0074231d5cb','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='22229e0d-4e4d-57d2-96f6-d0074231d5cb' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4a785308-8a23-5938-8d0c-b08f6cab94b7','Emotional-arc matching','The practice of shaping a dubbed performance and adaptation so a character''s emotional progression across a scene, sequence, or whole work follows the same trajectory as the original, maintaining continuity of feeling from line to line and take to take.','An emotional arc is how a character''s feelings change over time. Emotional-arc matching keeps that same rise and fall in the dubbed version, scene after scene.','It ensures the dub preserves how emotion builds and resolves across the story, not just how single lines sound.','Adapters and directors track a character across episodes so early restraint and later outbursts land with the same build as the source, not as disconnected takes.','Performance Adaptation',ARRAY['Emotional synchrony','Voice continuity','Dialogue adaptation','Effort synchrony','Isochrony','Kinesic synchrony']::text[],ARRAY['Recording scenes out of order without tracking where the character is emotionally.','Matching each line in isolation so the overall arc feels inconsistent.','Letting a replacement voice actor reset a character''s tone mid-arc.']::text[],ARRAY['Dubbing a series where a character''s grief deepens over several episodes.','Keeping a villain''s slow shift from calm to rage consistent across scenes.','Coordinating multiple recording days so emotion builds coherently.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4a785308-8a23-5938-8d0c-b08f6cab94b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Emotional-arc matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4a785308-8a23-5938-8d0c-b08f6cab94b7','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4a785308-8a23-5938-8d0c-b08f6cab94b7' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '96605d2e-e054-5ddb-a470-d456223210ac','Emphasis displacement','A mismatch in which the stressed or emphasized element of a target-language line falls on a different word, syllable, or moment than the emphasis in the source, shifting the intended focus away from where the original placed it.','Emphasis is the word a speaker stresses to show what matters. Emphasis displacement is when the stress lands on the wrong word after translation, changing the point.','Naming this error helps adapters spot when a translated line technically fits but stresses the wrong idea, so they can rewrite it.','An adapter reorders words so the emphasized term aligns with the actor''s vocal stress and gesture, avoiding a line that highlights the wrong element.','Prosody & Emphasis',ARRAY['Emphasis preservation','Isochrony','Kinesic synchrony','Dialogue adaptation','Emotional synchrony','Lip sync']::text[],ARRAY['Translating word-for-word so the stressed word ends up mid-sentence instead of at the key point.','Ignoring the actor''s gesture that marks which word is emphasized.','Assuming target and source share the same natural stress position.']::text[],ARRAY['Fixing a dubbed line where a pointing gesture no longer matches the stressed word.','Reworking a joke whose punchline stress moved to the wrong word.','Aligning emphasis with a character''s raised voice on a specific term.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='96605d2e-e054-5ddb-a470-d456223210ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Emphasis displacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '96605d2e-e054-5ddb-a470-d456223210ac','39203cec-660c-4a27-972c-21f7a63623b9',true
