INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e6c0035-7125-5098-83cf-e312aa303cca','Emphasis preservation','The adaptation goal of keeping the emphasis of a line — which word or idea the original stresses — on the equivalent element in the target language, so the point the source foregrounds remains foregrounded in the dub.','Emphasis preservation means keeping the stress on the same important word after translation. If the original stresses ''you,'' the dubbed line should stress ''you'' too.','It protects meaning and intent, ensuring the dubbed line highlights the same idea the source did rather than shifting the focus.','Adapters choose word order and phrasing so the key word lands under the actor''s vocal stress and any matching gesture.','Prosody & Emphasis',ARRAY['Emphasis displacement','Isochrony','Dialogue adaptation','Kinesic synchrony','Emotional synchrony','Lip sync']::text[],ARRAY['Prioritizing lip-sync so heavily that the stressed word gets buried.','Assuming a literal rendering keeps the same emphasis automatically.','Overlooking gestures or cutaways that mark the emphasized word.']::text[],ARRAY['Rewriting a threat so the stressed pronoun stays stressed in the dub.','Keeping the emphasized number intact in a line of instructions.','Matching a shouted key word to the same word in translation.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e6c0035-7125-5098-83cf-e312aa303cca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Emphasis preservation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0e6c0035-7125-5098-83cf-e312aa303cca','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0e6c0035-7125-5098-83cf-e312aa303cca' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '496f538b-79c7-54fe-8314-2ecfc705d76d','Entry latitude','The timing tolerance available at the start of a line — how far the target line''s beginning may deviate from the frame the character''s mouth starts moving before the mismatch becomes noticeable. It widens when the mouth is off-screen or in a wide shot and narrows in close-ups.','Entry latitude is the wiggle room for when a dubbed line can start. If the mouth is far away or off screen, the line can begin a little early or late.','It tells the team how strictly a line''s opening must hit the mouth, letting them use looser shots to solve tricky timing.','An adapter exploits wider entry latitude in off-screen or wide shots to fit a longer translated phrase without breaking visible sync.','Sync Timing',ARRAY['Exit latitude','Isochrony','Lip sync','Phonetic synchrony','Dialogue adaptation','Flap']::text[],ARRAY['Assuming every line must start on the exact frame even when the mouth is off-screen.','Wasting available latitude and forcing an awkward literal phrasing.','Treating close-up entry timing as loosely as a wide shot.']::text[],ARRAY['Starting a line slightly early during an off-screen reaction.','Fitting a long translation by leaning on wide-shot entry room.','Tightening line starts once the shot cuts to a close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='496f538b-79c7-54fe-8314-2ecfc705d76d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Entry latitude'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '496f538b-79c7-54fe-8314-2ecfc705d76d','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='496f538b-79c7-54fe-8314-2ecfc705d76d' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '73aefa96-208c-5197-ba71-de2f1728b3a8','Exit latitude','The timing tolerance available at the end of a line — how far the target line''s finish may deviate from the frame the character''s mouth stops moving before it reads as out of sync. Like entry latitude, it is wider off-screen or in wide shots and tighter in close-ups.','Exit latitude is the wiggle room for when a dubbed line can end. If the face is not in close-up, the line can finish a bit early or late.','It shows how strictly a line''s ending must match the mouth closing, helping the team place longer or shorter phrases.','An editor uses exit latitude on a cutaway or wide shot to let a translated line run slightly past the visible mouth movement.','Sync Timing',ARRAY['Entry latitude','Isochrony','Lip sync','Phonetic synchrony','Dialogue adaptation','Flap']::text[],ARRAY['Cutting a line short to hit an exact end frame the shot does not require.','Letting a line run long in a close-up where the mouth has clearly stopped.','Ignoring a scene cut that ends the shot and frees the exit timing.']::text[],ARRAY['Letting a line trail slightly past a mouth close in a wide shot.','Trimming a line to end exactly on a close-up mouth close.','Using a cutaway to absorb extra syllables at a line''s end.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='73aefa96-208c-5197-ba71-de2f1728b3a8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Exit latitude'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '73aefa96-208c-5197-ba71-de2f1728b3a8','39203cec-660c-4a27-972c-21f7a63623b9',true
