INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b1bc6657-5fdd-5272-a861-f95c5c314487','Expansion threshold','In dialogue adaptation, the practical limit to which a target-language line may grow longer than the source (text expansion) before it no longer fits the available screen time and mouth movements, violating isochrony and sync.','Some languages need more words to say the same thing. The expansion threshold is the point where the longer dubbed line no longer fits the on-screen timing.','It flags when a translation has grown too long to sync, prompting the adapter to condense before the line breaks timing.','An adapter shortens or rephrases a line once it passes the expansion threshold, so it still starts and ends with the character''s mouth.','Dialogue Adaptation',ARRAY['Isochrony','Entry latitude','Exit latitude','Dialogue adaptation','Condensation','Flap count']::text[],ARRAY['Keeping a faithful but overlong translation that overruns the mouth movement.','Assuming spoken length matches written length across languages.','Solving expansion only by speeding delivery until it sounds unnatural.']::text[],ARRAY['Trimming a wordy translation so it fits the original line length.','Deciding a phrase must be condensed to stay in sync.','Comparing source and target line durations during adaptation.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b1bc6657-5fdd-5272-a861-f95c5c314487' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Expansion threshold'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b1bc6657-5fdd-5272-a861-f95c5c314487','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b1bc6657-5fdd-5272-a861-f95c5c314487' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '85e574d9-b7c3-5c6d-a9b0-e2fcf1131923','Flap','In dubbing, a single visible opening-and-closing movement of a character''s mouth, treated as the basic unit the dialogue writer fits sound to; an unmatched movement carrying no dubbed sound is an ''empty'' flap. The term is used especially in animation, where the mouth movements are drawn.','A flap is one open-and-close movement of a character''s mouth on screen. Dubbing writers fit sounds to each flap so the voice matches the moving mouth.','Flaps give the writer countable visual targets, so translated dialogue lands sound on each mouth movement and avoids gaps.','A dubbing writer counts the flaps in a line and shapes the target dialogue to fill them, leaving no mouth moving in silence.','Lip Sync',ARRAY['Flap count','Flap density','Lip sync','Phonetic synchrony','Isochrony','Rhythmic synchrony']::text[],ARRAY['Writing a line shorter than the flaps, leaving empty mouth movements on screen.','Confusing a flap with a syllable, since one flap may cover more than one sound.','Focusing on flaps in a wide shot where they are barely visible and timing is looser.']::text[],ARRAY['Counting mouth movements in an animated character''s line.','Spotting empty flaps left by a too-short translation.','Matching dialogue to a live-action close-up''s mouth openings.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='85e574d9-b7c3-5c6d-a9b0-e2fcf1131923' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flap'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '85e574d9-b7c3-5c6d-a9b0-e2fcf1131923','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='85e574d9-b7c3-5c6d-a9b0-e2fcf1131923' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a41800f0-699c-5a1b-b3c8-8d126555ace2','Flap count','The number of visible mouth flaps (open-close movements) in a given line or take, used by dubbing writers as a target for how many mouth movements the translated dialogue must cover.','Flap count is how many mouth movements a line has on screen. The dubbed words must roughly cover that same number of movements.','It quantifies the visual sync target for a line, guiding how long or short the adapted dialogue should be.','A writer notes the flap count while spotting and adjusts word choice so the target line matches that number of mouth movements.','Lip Sync',ARRAY['Flap','Flap density','Isochrony','Lip sync','Rhythmic synchrony','Phonetic synchrony']::text[],ARRAY['Equating flap count directly with the source language''s syllable count.','Writing far fewer sounds than flaps, leaving mouths moving silently.','Ignoring flap count and relying only on total line duration.']::text[],ARRAY['Logging mouth movements per line during animation dubbing.','Sizing a translated line to the counted mouth movements.','Comparing flap count against a proposed adaptation''s length.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a41800f0-699c-5a1b-b3c8-8d126555ace2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flap count'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
