WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a41800f0-699c-5a1b-b3c8-8d126555ace2' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05c30b55-eae8-5f39-95f8-59e48f0b6e53','Flap density','The rate of mouth flaps over time within a line — how tightly packed the visible mouth movements are — reflecting the original''s speech tempo and internal rhythm; matching it is part of rhythmic synchrony.','Flap density is how fast the mouth movements come in a line. Quick, packed movements mean the dubbed words must come fast too.','It captures the pace of the mouth movements so the dub matches the original''s rhythm, not just its total length.','A writer feels high flap density in a fast line and picks short, quick words so the target keeps the same tempo.','Lip Sync',ARRAY['Flap','Flap count','Rhythmic synchrony','Isochrony','Lip sync','Phonetic synchrony']::text[],ARRAY['Matching total line length but ignoring how fast the mouth moves inside it.','Filling a fast, dense line with long words that cannot keep pace.','Assuming even spacing when the flaps cluster in bursts.']::text[],ARRAY['Adapting a rapid-fire line so the tempo still fits the mouth.','Spotting a dense run of mouth movements in an argument scene.','Choosing clipped words to match closely spaced flaps.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05c30b55-eae8-5f39-95f8-59e48f0b6e53' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flap density'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '05c30b55-eae8-5f39-95f8-59e48f0b6e53','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='05c30b55-eae8-5f39-95f8-59e48f0b6e53' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dd63595f-a5fa-5ffe-91e5-07a86fa5df40','Fully filled M&E','A music-and-effects (M&E) deliverable containing every non-dialogue sound present in the final mix — music, backgrounds, foley, and all production effects, including those normally masked by dialogue — so that when the original dialogue is removed and replaced, no sonic gaps remain. It is distinguished from a partial M&E that omits effects hidden under dialogue.','A fully filled M&E is a music-and-effects track with every sound except the talking. It has no holes, so a new-language voice can drop right in.','It lets a dubbing team replace dialogue in any language without missing footsteps, props, or backgrounds that were hidden under the original speech.','A re-recording mixer fills every effect that sat under dialogue in the original, then delivers the M&E so foreign-language mixes have complete backgrounds.','M&E Deliverables',ARRAY['Music and effects track','Fully undipped stem','Dialogue stem','Foley','Automated dialogue replacement','Walla']::text[],ARRAY['Leaving gaps where an effect was only present under the original dialogue.','Including story-important dialogue or narration in the M&E by mistake.','Assuming the theatrical mix''s M&E is complete without checking under-dialogue effects.']::text[],ARRAY['Preparing an M&E so a series can be dubbed into many languages.','Filling missing footsteps that were buried under a conversation.','Delivering an M&E to a distributor''s localization vendor.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dd63595f-a5fa-5ffe-91e5-07a86fa5df40' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fully filled M&E'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dd63595f-a5fa-5ffe-91e5-07a86fa5df40','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dd63595f-a5fa-5ffe-91e5-07a86fa5df40' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1f9ce022-2706-5396-b8ba-c01c2fc227c4','Fully undipped stem','A mix stem in which the effects, backgrounds, or music are held at full level throughout, with no dips (level reductions) applied under the original dialogue. Undipped stems preserve continuous element levels so a dubbed dialogue track can be laid over them without audible holes.','Dipping means lowering background sounds under the talking. A fully undipped stem never lowers them, so the sounds stay steady and full the whole time.','It keeps background and effect levels consistent so localization teams can place new dialogue on top without hearing dips left by the original mix.','A mixer delivers undipped effects and music stems so the foreign-language mix, not the original ducking, controls how sounds sit under the new dialogue.','M&E Deliverables',ARRAY['Fully filled M&E','Music and effects track','Dialogue stem','Ducking','Foley','Automated dialogue replacement']::text[],ARRAY['Delivering stems still dipped under the original dialogue, leaving audible dips when new dialogue is added.','Confusing an undipped stem with a fully filled M&E, since a stem can be undipped yet still missing sounds.','Applying original-mix automation to stems meant to stay at full level.']::text[],ARRAY['Delivering undipped music and effects stems for archival and versioning.','Rebuilding a foreign mix where the dub, not old ducking, sets levels.','Checking that no level dips remain under the removed dialogue.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1f9ce022-2706-5396-b8ba-c01c2fc227c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fully undipped stem'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1f9ce022-2706-5396-b8ba-c01c2fc227c4','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1f9ce022-2706-5396-b8ba-c01c2fc227c4' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05e01182-3ee3-5688-92b1-958512fa63e6','Gesture anchoring','In dubbing adaptation, the practice of tying a translated line to a specific on-screen gesture, so that the word or stress connected to that gesture falls at the same moment in the dub. It is an application of kinesic synchrony, in which the dialogue must respect the meaning and timing of the character''s visible body movements.','A gesture is a body movement like a shrug or a pointing finger. Gesture anchoring means matching the dubbed words to that movement. If the actor points while saying a word, the dubbed word must land at the same time.','It keeps the dubbed dialogue in step with visible body movements, so a gesture and the words it belongs to still line up and make sense together.','An adapter watches where a character gestures and places the matching target word or stress at that exact point, rewording the line so the timing holds.','Synchronization',ARRAY['Kinesic synchrony','Gesture synchrony','Isochrony','Gesture-loaded utterance','Head-turn synchrony','Lip synchrony']::text[],ARRAY['Translating the words correctly but letting the key word drift away from the gesture that belongs to it.','Syncing only to the mouth and ignoring gestures, so a point or nod no longer matches the line.','Forcing a word onto a gesture so rigidly that the sentence sounds unnatural.']::text[],ARRAY['A character taps the table on a stressed word that must stay on the same beat in the dub.','Adapting a line where the actor points at an object exactly as they name it.','Reworking dialogue so a shrug still lands on the matching word after translation.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05e01182-3ee3-5688-92b1-958512fa63e6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gesture anchoring'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '05e01182-3ee3-5688-92b1-958512fa63e6','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='05e01182-3ee3-5688-92b1-958512fa63e6' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f0c9b5ec-58ac-5a03-a054-35dc10d3f657','Gesture synchrony','A form of kinesic synchrony in which the translated dialogue is matched to the gestures and body movements of the on-screen character, so the words do not contradict what the body is doing and coincide in timing with prominent gestures.','Gesture synchrony means the dubbed words fit the actor''s body movements. When someone waves goodbye, the words should sound like a goodbye. The speech must agree with what the body shows.','It stops the dubbed dialogue from clashing with visible gestures, keeping the character believable when words and body language are seen together.','During adaptation, the writer checks each strong gesture and shapes the line so its meaning and stress agree with the movement on screen.','Synchronization',ARRAY['Kinesic synchrony','Gesture anchoring','Gesture-loaded utterance','Isochrony','Head-turn synchrony','Lip synchrony']::text[],ARRAY['Assuming gestures carry the same meaning across cultures and translating the words without checking the picture.','Matching only the mouth and timing while ignoring what the hands and body are doing.','Keeping a source idiom whose gesture no longer fits the reworded target line.']::text[],ARRAY['Dubbing a scene where a character counts on their fingers while listing items.','Adapting dialogue for an actor who gesticulates heavily throughout a monologue.','Matching a dismissive hand wave to a dismissive line in the target language.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f0c9b5ec-58ac-5a03-a054-35dc10d3f657' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gesture synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f0c9b5ec-58ac-5a03-a054-35dc10d3f657','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f0c9b5ec-58ac-5a03-a054-35dc10d3f657' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '504ab851-2a8e-5313-8b22-74d1e7752d65','Gesture-loaded utterance','An on-screen utterance closely tied to visible gestures or body movements, so its translation is constrained not only by timing but by the need to keep the words consistent with the accompanying gestures. Such lines demand careful kinesic synchrony.','This is a line spoken with strong body movements, like pointing or a big shrug. The gestures are part of the message. The dubbed words must still fit those movements, which limits the translator''s choices.','Naming it flags lines where gestures restrict the wording, warning the adapter that a free translation could clash with what the body is doing.','When an adapter spots a gesture-loaded line, they choose target wording that keeps the link between the words and the visible movement instead of translating freely.','Synchronization',ARRAY['Kinesic synchrony','Gesture synchrony','Gesture anchoring','Isochrony','Head-turn synchrony','Sync adaptation']::text[],ARRAY['Treating the line as ordinary dialogue and translating the words without regard to the gestures.','Losing a gesture''s meaning because the target wording no longer supports it.','Preserving the source phrasing so rigidly that timing or naturalness breaks.']::text[],ARRAY['A character shrugs and spreads their hands while saying they do not know.','Adapting a threat delivered with a pointing finger jabbing on each beat.','Dubbing a line where the speaker mimes an action as they describe it.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='504ab851-2a8e-5313-8b22-74d1e7752d65' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gesture-loaded utterance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '504ab851-2a8e-5313-8b22-74d1e7752d65','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='504ab851-2a8e-5313-8b22-74d1e7752d65' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f693f1d2-9bcb-574e-b397-cf4f4f8df5a6','Head-turn synchrony','A form of kinesic synchrony in which the translated dialogue is aligned with the character''s head movements, especially head turns, which often mark the start or end of a line, a change of addressee, or a point of emphasis. The dub must respect these visible movements.','This means matching the dubbed line to the actor''s head turns. A head turn often marks where a line starts, stops, or changes who is spoken to. The dub should respect those moments.','It keeps line boundaries and emphasis tied to the visible head movements, so the dubbed dialogue still looks driven by the same on-screen cues.','The adapter notes where a character turns their head and shapes the line so a break or stress falls on that turn rather than in the middle of a phrase.','Synchronization',ARRAY['Kinesic synchrony','Gesture synchrony','Isochrony','Internal timing anchor','Gesture anchoring','Lip synchrony']::text[],ARRAY['Placing a pause or line break away from a clear head turn, so the movement no longer matches the speech.','Ignoring a head turn that signals the character now speaks to someone else.','Focusing only on lip movements and missing head movements that shape the delivery.']::text[],ARRAY['A character turns to a second person exactly as a new sentence begins.','Adapting a line where the speaker looks away on the final words.','Matching a sharp head turn to an emphasized word in the target line.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f693f1d2-9bcb-574e-b397-cf4f4f8df5a6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-turn synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f693f1d2-9bcb-574e-b397-cf4f4f8df5a6','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f693f1d2-9bcb-574e-b397-cf4f4f8df5a6' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9a9d5d41-c0b3-538b-812f-75f41fa81871','Hesitation matching','In dubbing adaptation, the reproduction of a speaker''s hesitations, pauses, and filled pauses (such as ''um'' or ''er'') in the target line so they fall at the same points as in the original, preserving both the timing dictated by isochrony and the character''s manner of speaking.','People pause and say things like ''um'' when they speak. Hesitation matching keeps those pauses and fillers in the dubbed line at the same spots. This keeps the timing right and the character sounding natural.','It preserves the rhythm and personality of the original delivery while keeping the line''s pauses lined up with the picture and the character''s mouth.','The adapter marks where the original hesitates and writes matching pauses or fillers into the target line so the delivery pauses at the same moments.','Synchronization',ARRAY['Isochrony','Internal timing anchor','Internal synchrony','Intonational equivalence','Sync adaptation','Kinesic synchrony']::text[],ARRAY['Smoothing out every hesitation, so a nervous or thinking character sounds unnaturally fluent.','Adding fillers that were never in the original just to fill time.','Keeping the words but shifting the pauses so they no longer match the picture.']::text[],ARRAY['Dubbing a character who stammers while lying.','Matching a thoughtful pause before a difficult answer.','Keeping an ''um'' that coincides with a visible mouth movement on screen.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9a9d5d41-c0b3-538b-812f-75f41fa81871' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hesitation matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9a9d5d41-c0b3-538b-812f-75f41fa81871','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9a9d5d41-c0b3-538b-812f-75f41fa81871' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '76ce7dba-bca1-5db3-82e7-67e3c079fe8c','Impact synchrony','A form of kinesic synchrony in which a stressed syllable or word in the translated line is aligned with a visible physical impact or abrupt action on screen, such as a blow, a slam, or a stamp, so the accent of the speech coincides with the accent of the movement.','Sometimes a line lands on a physical hit, like a fist on a table. Impact synchrony puts the stressed word right on that hit. The strong word and the strong movement happen together.','It ties the emphasis of the dialogue to a strong visible action, so the moment feels sharp and the words and picture reinforce each other.','The adapter spots the on-screen impact and rewrites the line so its stressed word falls exactly on that beat.','Synchronization',ARRAY['Kinesic synchrony','Gesture anchoring','Internal timing anchor','Isochrony','Information-focus matching','Head-turn synchrony']::text[],ARRAY['Letting the stressed word drift off the visible impact so the emphasis lands on empty screen time.','Ignoring the action and stressing a different word for grammar reasons alone.','Reordering the line so the key beat no longer coincides with the movement.']::text[],ARRAY['A character slams a door on the final word of a line.','Matching an emphasized insult to a punch landing on screen.','Aligning a stamped foot with the stressed syllable of the dubbed line.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='76ce7dba-bca1-5db3-82e7-67e3c079fe8c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Impact synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '76ce7dba-bca1-5db3-82e7-67e3c079fe8c','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='76ce7dba-bca1-5db3-82e7-67e3c079fe8c' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '039610da-b1d9-598b-858a-3b34349b7243','Information-focus matching','In dubbing adaptation, matching the placement of information focus, the element of an utterance that carries the main new or emphasized information and is usually marked by stress, between the source and target lines, so the emphasis falls on the intended element and stays consistent with the picture and context.','Every sentence has a most important word that gets the stress. Information-focus matching keeps that stress on the right word in the dub. This makes sure the dubbed line highlights what the original did.','It preserves what the original line highlights, so the dubbed dialogue points the audience''s attention to the same key idea.','The adapter finds the stressed, focal word in the source and orders the target line so the same idea carries the stress, often changing word order to do so.','Synchronization',ARRAY['Intonational equivalence','Intonational rephrasing','Impact synchrony','Isochrony','Internal timing anchor','Sync adaptation']::text[],ARRAY['Translating word for word so the natural stress lands on the wrong element in the target language.','Changing word order for sync and accidentally shifting the emphasis to a minor word.','Assuming both languages mark emphasis the same way and leaving focus in the source position.']::text[],ARRAY['Rewording a target line so the emphasis stays on ''today'' rather than ''meeting''.','Adapting a reply where the contrast falls on a specific pronoun.','Keeping a punchline''s key word in the stressed position after translation.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='039610da-b1d9-598b-858a-3b34349b7243' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Information-focus matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '039610da-b1d9-598b-858a-3b34349b7243','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='039610da-b1d9-598b-858a-3b34349b7243' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0063fc79-82e3-52df-90f4-b62ab559b935','Internal synchrony','Synchrony of the internal features of a line, its pauses, stresses, and rhythm, with the picture, rather than matching only the overall start and end of the utterance. It ensures that events within the line, such as a mid-line pause, coincide with the corresponding on-screen moments.','A line is not just one block of sound. It has pauses and stresses inside it. Internal synchrony makes those inside moments match the picture, not just the start and end.','It stops a line that starts and ends on time from drifting in the middle, keeping pauses and stresses lined up with mouth movements and actions throughout.','The adapter checks that mid-line pauses and stressed words fall on the right frames, adjusting phrasing so the inside of the line stays in step, not just its edges.','Synchronization',ARRAY['Isochrony','Internal timing anchor','Hesitation matching','Isochronic constraint','Information-focus matching','Kinesic synchrony']::text[],ARRAY['Matching only the start and end of a line while the middle drifts out of sync.','Placing a pause for grammar where the picture has none, breaking the internal timing.','Assuming correct overall length guarantees the inside of the line is in sync.']::text[],ARRAY['A line with a mid-sentence pause that must match a character''s breath on screen.','Adapting a two-part sentence where the break falls on a visible head turn.','Keeping a stressed word on its frame even after the line is reworded.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0063fc79-82e3-52df-90f4-b62ab559b935' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Internal synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0063fc79-82e3-52df-90f4-b62ab559b935','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0063fc79-82e3-52df-90f4-b62ab559b935' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ded9a74-5a4b-573f-a47f-f7ab833c1e95','Internal timing anchor','A reference point inside an utterance, such as a pause, a stressed syllable, a visible mouth opening, or a gesture, that an adapter uses to keep the translated line synchronized along its full length rather than only at its start and end. Anchors divide the line into sections that must each stay in sync.','An internal timing anchor is a fixed point inside a line, like a pause or a clear mouth movement. The adapter lines the dubbed words up to these points. They act like pegs that hold the timing in place.','It gives the adapter fixed points to sync against, so a long line stays matched to the picture from beginning to end instead of only at its edges.','The adapter marks strong beats, a pause, a labial, or a gesture, and fits target words around each so every section of the line lands on time.','Synchronization',ARRAY['Isochrony','Internal synchrony','Hesitation matching','Head-turn synchrony','Lip synchrony','Isochronic constraint']::text[],ARRAY['Syncing only the first and last words and ignoring anchor points in between.','Overwriting a natural pause that served as a reliable timing anchor.','Choosing a weak, barely visible point as an anchor instead of a clear mouth or gesture beat.']::text[],ARRAY['Using a visible bilabial closure mid-line as a fixed sync point.','Anchoring a long line to a pause where the character takes a breath.','Splitting a sentence at a gesture and syncing each half separately.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ded9a74-5a4b-573f-a47f-f7ab833c1e95' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Internal timing anchor'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ded9a74-5a4b-573f-a47f-f7ab833c1e95','39203cec-660c-4a27-972c-21f7a63623b9',true
