INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '83d05a6d-1876-5c37-aa45-28ef8197f297','Intonational equivalence','The achievement of an equivalent intonation contour in the target line, so the pattern of pitch rises and falls conveys the same attitude, sentence type, and emphasis as the original delivery, even when the words differ. It is a prosodic dimension of dubbing quality.','Intonation is the tune of speech, the way the voice rises and falls. Intonational equivalence means the dubbed line carries the same tune and feeling as the original. A question should still sound like a question.','It keeps the emotional tone and sentence type of the original, so a dubbed question, order, or sarcastic remark still sounds like one.','The adapter and voice director shape wording and delivery so the target line rises and falls in a way that matches the original''s attitude and stress.','Synchronization',ARRAY['Intonational rephrasing','Information-focus matching','Hesitation matching','Isochrony','Kinesic synchrony','Sync adaptation']::text[],ARRAY['Producing a flat delivery that loses the rises and falls of the original.','Keeping the words accurate but letting a sarcastic or questioning tone disappear.','Assuming the target language marks questions and emphasis with the same melody as the source.']::text[],ARRAY['Making sure a rhetorical question keeps its rising tone in the dub.','Preserving a sarcastic melody that carries the joke.','Matching the falling tone of a firm command in the target line.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='83d05a6d-1876-5c37-aa45-28ef8197f297' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intonational equivalence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '83d05a6d-1876-5c37-aa45-28ef8197f297','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='83d05a6d-1876-5c37-aa45-28ef8197f297' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'af03fe21-64fb-52a8-9e96-fa845fb5ba87','Intonational rephrasing','A dubbing adaptation strategy in which the target line is reworded or reordered so its natural intonation contour matches the melody, stress, and phrasing of the original delivery. It is used to reach intonational equivalence when a literal translation would carry the wrong prosody.','Sometimes a direct translation puts the stress and tune in the wrong place. Intonational rephrasing changes the wording so the tune fits. The idea stays the same but the line is rebuilt to sound right.','It lets the adapter reach the intended melody and emphasis when a straight translation would give the line an unnatural or wrong-sounding tune.','When a literal line would stress the wrong word or break awkwardly, the adapter rewrites it so its natural rhythm and pitch match the original delivery.','Synchronization',ARRAY['Intonational equivalence','Information-focus matching','Isochronic adaptation','Isochrony','Sync adaptation','Hesitation matching']::text[],ARRAY['Keeping a literal word order that forces an unnatural stress or melody.','Rephrasing for tune but drifting away from the original meaning.','Fixing the intonation but breaking isochrony or lip sync in the process.']::text[],ARRAY['Reordering a target sentence so its rise falls on the same word as the original.','Rewriting a line so the emphasis sounds natural rather than forced.','Adapting an exclamation so its melody matches the actor''s delivery.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='af03fe21-64fb-52a8-9e96-fa845fb5ba87' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intonational rephrasing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'af03fe21-64fb-52a8-9e96-fa845fb5ba87','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='af03fe21-64fb-52a8-9e96-fa845fb5ba87' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '52e083fa-92d2-574b-8464-418b9867c4e3','Isochronic adaptation','The adaptation of a translated line so its spoken duration equals that of the on-screen utterance it replaces, fitting between the character''s mouth openings and closings and matching the timing of internal pauses. It is the practical work of satisfying isochrony.','Isochronic adaptation makes the dubbed line last exactly as long as the original speech. The words are trimmed or padded to fit the time. It also keeps the pauses in the same spots.','It ensures the dubbed line neither runs past nor falls short of the on-screen speech, so the voice matches the length of the moving mouth.','The adapter times each line against the picture and adds, cuts, or reshapes words until the delivery lasts as long as the original and pauses in the same places.','Synchronization',ARRAY['Isochrony','Isochronic constraint','Internal synchrony','Underlength line','Sync adaptation','Lip synchrony']::text[],ARRAY['Matching total length but placing the pauses in the wrong spots.','Padding with filler words that sound unnatural just to reach the right duration.','Cutting meaning to save time instead of rephrasing more concisely.']::text[],ARRAY['Trimming a wordy translation so it fits a short on-screen line.','Expanding a concise target phrase to fill a longer original utterance.','Adjusting internal pauses so a reworded line still matches the picture.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='52e083fa-92d2-574b-8464-418b9867c4e3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Isochronic adaptation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '52e083fa-92d2-574b-8464-418b9867c4e3','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='52e083fa-92d2-574b-8464-418b9867c4e3' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c52e2cd8-8f50-55ff-a353-24df1f064f63','Isochronic constraint','The requirement that a translated utterance match the duration of the source utterance it replaces, fitting between the openings and closings of the on-screen character''s mouth. Framed as a constraint, it limits how long or short the target line may be, regardless of how the source content could otherwise be expressed.','The isochronic constraint is the rule that the dubbed line must last as long as the original. It limits how many words the translator can use. Each line has a fixed time slot to fill.','It defines the fixed time budget for each line, forcing translation choices that fit the available on-screen speaking time.','An adapter treats each line''s on-screen duration as a hard limit, choosing wording that can be spoken naturally within exactly that time.','Synchronization',ARRAY['Isochrony','Isochronic adaptation','Internal synchrony','Underlength line','Sync window','Lip synchrony']::text[],ARRAY['Writing a line that is accurate but too long or short to fit the on-screen speech.','Treating the time limit as flexible and letting the voice run past the mouth.','Meeting the total time but ignoring where the internal pauses must fall.']::text[],ARRAY['Choosing a shorter synonym so a line fits a brief on-screen utterance.','Rejecting an accurate but overlong translation that breaks the time budget.','Planning target phrasing around the fixed length of a close-up line.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c52e2cd8-8f50-55ff-a353-24df1f064f63' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Isochronic constraint'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c52e2cd8-8f50-55ff-a353-24df1f064f63','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c52e2cd8-8f50-55ff-a353-24df1f064f63' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '019ed3cb-9727-5d23-90ba-94f5c052a6b1','Kinesic synchrony','The type of dubbing synchronization concerned with matching the translated dialogue to the body movements, gestures, and facial expressions of the on-screen character, so the words agree in meaning and timing with the visible performance and do not contradict it. It is one of the three classic synchronies alongside lip synchrony and isochrony.','Kinesic means body movement. Kinesic synchrony makes the dubbed words match the actor''s gestures and expressions. If the body says one thing, the words must not say the opposite.','It keeps the dubbed dialogue believable by making sure the words never clash with the character''s visible gestures, nods, or facial expressions.','The adapter watches the actor''s body language and shapes the translation so its meaning and emphasis fit each visible movement on screen.','Synchronization',ARRAY['Isochrony','Lip synchrony','Gesture synchrony','Head-turn synchrony','Gesture anchoring','Impact synchrony']::text[],ARRAY['Focusing only on the mouth and timing while ignoring gestures and expressions.','Assuming a gesture means the same thing in the target culture and mistranslating around it.','Writing an accurate line whose meaning contradicts a visible nod, shrug, or point.']::text[],ARRAY['Adapting a line so it agrees with a character shaking their head ''no''.','Dubbing a heavily gesturing actor whose movements must match the new words.','Keeping an affirmative line positive when the character nods on screen.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='019ed3cb-9727-5d23-90ba-94f5c052a6b1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Kinesic synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '019ed3cb-9727-5d23-90ba-94f5c052a6b1','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='019ed3cb-9727-5d23-90ba-94f5c052a6b1' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc705bd2-f665-5295-92c3-e59224d70b85','Labial synchrony','In dubbing, the branch of lip synchrony that matches the target-language dialogue to the visible labial articulations of the on-screen actor — chiefly the bilabial consonants (/p/, /b/, /m/) and labiodental consonants (/f/, /v/) that force a visible closing or biting of the lips, plus rounded vowels — so the translated words fit the mouth shapes seen in close-up shots.','Labial synchrony means matching the new dialogue to how the actor''s lips look. Some sounds, like "p," "b," and "m," make the lips shut. The dubbed words should use similar lip shapes in close-up shots.','It preserves the visual believability of a dub by ensuring that where the audience can clearly see the lips close or round, the replacement dialogue produces the same visible mouth positions.','A dubbing translator or adapter rewrites lines so a bilabial or labiodental sound in the original falls on a matching sound in the target language wherever the actor''s mouth is shown in close-up.','Lip Sync',ARRAY['Lip synchrony','Isochrony','Kinesic synchrony','Labiodental correspondence','Lip-rounding mismatch','Mouth-open interval']::text[],ARRAY['Trying to match labials in wide or off-camera shots, where lip movements are not clearly visible and the effort is wasted.','Preserving a bilabial sound at the cost of a natural, meaningful line, when a small rewording would read better.','Assuming every vowel must match, when only visibly rounded vowels and closed-lip consonants are noticeable to viewers.']::text[],ARRAY['Adapting a close-up line so an original /m/ lands on a target word that also closes the lips.','Reviewing a dub take where the actor''s lips close but the new audio has an open-mouth sound.','Prioritizing which lines in a scene need strict labial matching based on shot framing.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc705bd2-f665-5295-92c3-e59224d70b85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Labial synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bc705bd2-f665-5295-92c3-e59224d70b85','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bc705bd2-f665-5295-92c3-e59224d70b85' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '43343613-4ba1-5ff4-b728-db9b32b6a1f5','Labiodental correspondence','The matching, in dubbing adaptation, of labiodental consonants — sounds such as /f/ and /v/ produced by pressing the lower lip against the upper teeth — between the source performance and the target-language line, so the visibly distinctive lip-to-teeth gesture on screen coincides with a labiodental sound in the dub.','This is about the "f" and "v" sounds. You make these by touching your top teeth to your bottom lip. In a dub, the new words should keep that same lip-and-teeth move where the camera shows it.','Because the lip-to-teeth contact of /f/ and /v/ is highly visible, matching it keeps close-up dubbing convincing and avoids an obvious clash between what is seen and heard.','When adapting a close-up line, the writer tries to place a target /f/ or /v/ on the same frames where the original actor bit the lip, or reshapes the sentence so no labiodental is left exposed.','Lip Sync',ARRAY['Labial synchrony','Lip synchrony','Lip-rounding mismatch','Isochrony','Mouth-open interval','Mouth-flap matching']::text[],ARRAY['Ignoring labiodentals because they seem minor, even though the teeth-on-lip shape is very easy to see in close-up.','Treating /f/ and /v/ as interchangeable with bilabials like /p/ or /b/, which look different on the mouth.','Forcing a labiodental match in a shot where the face is not clearly visible.']::text[],ARRAY['Adapting a close-up word so the original ''v'' lands on a target sound made the same way.','Spotting a dub where the actor''s lip touches the teeth but the audio has no ''f'' or ''v''.','Choosing target vocabulary that keeps a visible labiodental in a hero close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='43343613-4ba1-5ff4-b728-db9b32b6a1f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Labiodental correspondence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '43343613-4ba1-5ff4-b728-db9b32b6a1f5','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='43343613-4ba1-5ff4-b728-db9b32b6a1f5' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69fd50aa-7092-5d7b-83f5-bfd2d48f0a3c','Language-neutral vocal','A non-verbal vocal sound — such as a grunt, groan, cough, gasp, cry, laugh, or heavy breath — that carries no discernible language content and can therefore remain in the Music and Effects (M&E) track unchanged, being usable across all dubbed language versions without re-recording.','A language-neutral vocal is a mouth sound with no real words, like a grunt, gasp, or cough. Because it is not tied to any language, every dubbed version can keep it. It stays in the music-and-effects track.','Keeping these sounds in the M&E lets every language version share the same non-verbal performance, saving re-recording and preserving the original actor''s physical reactions.','When building the M&E, an editor leaves clearly non-lexical vocalizations in the effects bed, while moving anything that sounds like a specific word to a dialogue or optional track.','M&E Deliverables',ARRAY['Music and Effects','Language-specific effort','Vocal efforts','M&E fill','Walla','Optional stem']::text[],ARRAY['Leaving a vocalization that contains a recognizable word in the language-neutral M&E, which then cannot be localized.','Stripping out breaths and grunts that should have stayed, leaving dubbed action scenes lifeless.','Assuming all crying or laughing is language-neutral, when some carries language-specific coloring.']::text[],ARRAY['Deciding whether a character''s pained groan stays in the M&E or moves to an optional track.','Preparing an M&E where baby cries and crowd gasps remain shared across all dubs.','Reviewing a delivery to confirm no lexical words hide inside supposedly neutral vocals.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69fd50aa-7092-5d7b-83f5-bfd2d48f0a3c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language-neutral vocal'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69fd50aa-7092-5d7b-83f5-bfd2d48f0a3c','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69fd50aa-7092-5d7b-83f5-bfd2d48f0a3c' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd147f911-c66d-504e-a7d3-74a7fcf82ede','Language-specific effort','A non-verbal vocal exertion — a breath, effort grunt, sigh, hum, or reaction — tied closely enough to the spoken performance or language that it must be re-recorded for each dubbed version, and is therefore delivered on a separate optional track rather than left in the language-neutral Music and Effects body.','A language-specific effort is a sound like a breath, grunt, or sigh that goes with a spoken line. Because it belongs to that actor''s voice, each dub records its own. It is kept on a separate track, not in the shared music-and-effects.','Separating these efforts lets the dubbing mixer swap in the new actor''s breaths and exertions so the voice performance stays consistent across a line, rather than mixing two different voices.','During M&E creation, efforts that sit on or beside dialogue are placed on an optional efforts track so the dub stage can choose the original or the newly recorded version.','M&E Deliverables',ARRAY['Language-neutral vocal','Vocal efforts','Music and Effects','Optional stem','M&E fill','Automated dialogue replacement']::text[],ARRAY['Baking language-specific efforts into the main M&E, forcing dubs to mix a foreign-sounding breath with the new voice.','Confusing a language-specific effort with true dialogue and omitting it from the recording script.','Failing to deliver the optional efforts track, leaving the dub mixer without material near dialogue lines.']::text[],ARRAY['Placing an actor''s strained breath next to a line onto the optional efforts stem.','A dub studio recording new efforts so they match the target-language voice.','QC of a delivery checking that on-dialogue breaths are on the optional track, not the M&E body.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d147f911-c66d-504e-a7d3-74a7fcf82ede' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Language-specific effort'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd147f911-c66d-504e-a7d3-74a7fcf82ede','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d147f911-c66d-504e-a7d3-74a7fcf82ede' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3a258d9a-03e4-58d6-bb9f-568f909bd6db','Linguistic condensation','A dialogue-adaptation strategy that shortens the target-language rendering — cutting redundancy, discourse markers, or non-essential words — so the translated line fits within the source utterance''s on-screen duration and mouth movements while preserving its essential meaning.','Linguistic condensation means making the translated line shorter. You cut extra or repeated words but keep the main meaning. This helps the dub fit the time the actor''s mouth is moving.','It exists to satisfy isochrony when the target language would otherwise run too long, letting the dub start and end with the on-screen speech.','An adapter trims filler, merges clauses, or picks shorter synonyms so a wordy translation collapses to the length of the original line.','Dialogue Adaptation',ARRAY['Linguistic expansion','Isochrony','Labial synchrony','Mouth-open interval','Music and Effects','Kinesic synchrony']::text[],ARRAY['Cutting so much that important plot or character information is lost, not just filler.','Confusing condensation with subtitling reduction, which follows reading-speed limits rather than mouth timing.','Shortening a line that already fits, making the dub feel clipped or unnatural.']::text[],ARRAY['Trimming a long target sentence to end when the character''s mouth stops moving.','Removing a redundant discourse marker so a dubbed line matches the pause structure.','Adapting a language that runs longer than the source for a tight close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3a258d9a-03e4-58d6-bb9f-568f909bd6db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Linguistic condensation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
