WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3a258d9a-03e4-58d6-bb9f-568f909bd6db' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b22f2e96-456b-5099-a706-421ccfccd3f0','Linguistic expansion','A dialogue-adaptation strategy that lengthens the target-language rendering — adding words, repetitions, discourse markers, or elongated phrasing — so a shorter translation fills the full on-screen duration and mouth movements of the source line without leaving dead air.','Linguistic expansion means making the translated line longer. You add small words or repeats so the speech lasts as long as the actor''s mouth moves. The extra words must not change the meaning.','It satisfies isochrony when the target language is naturally shorter than the source, preventing a gap where the mouth still moves but no dialogue is heard.','An adapter adds a natural filler, repeats a word, or stretches phrasing so a brief translation keeps pace with the character''s visible speech.','Dialogue Adaptation',ARRAY['Linguistic condensation','Isochrony','Labial synchrony','Mouth-open interval','Music and Effects','Kinesic synchrony']::text[],ARRAY['Padding a line with words that add new meaning or contradict the scene, instead of neutral filler.','Over-expanding so the delivery sounds rushed as the actor races to fill the time.','Adding text that leaves the target line still short, so the mouth moves with no sound.']::text[],ARRAY['Adding a natural discourse marker so a short translation reaches the end of the mouth movement.','Repeating a word to fill a pause the original actor spoke through.','Adapting a concise language to match a longer source line in close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b22f2e96-456b-5099-a706-421ccfccd3f0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Linguistic expansion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b22f2e96-456b-5099-a706-421ccfccd3f0','39203cec-660c-4a27-972c-21f7a63623b9',true
