INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13db4341-807c-5322-ab9c-0b0b1bfb692b','Lip-rounding mismatch','A lip-sync error in which the visible lip rounding or protrusion of the on-screen actor — produced by rounded vowels such as /o/ and /u/ — does not coincide with the dubbed audio, so the mouth appears rounded while the replacement dialogue carries an unrounded sound, or vice versa, breaking the visual match in close-up.','Lip-rounding mismatch is a lip-sync problem. Vowels like "o" and "oo" push the lips out into a round shape. In a mismatch, the actor''s lips look rounded but the dubbed word has no rounded sound, or the reverse. When the audio and the lips disagree, close-ups look wrong.','Naming this mismatch helps adapters and QC spot one of the most visible sync faults, since rounded lips stand out clearly and draw viewer attention.','A reviewer flags shots where a rounded-vowel mouth shape lands on a flat target sound so the line can be reworded before the final mix.','Lip Sync',ARRAY['Labial synchrony','Labiodental correspondence','Lip synchrony','Isochrony','Mouth-open interval','Mouth-flap matching']::text[],ARRAY['Overlooking lip rounding because attention is on consonants, even though rounded vowels are very visible.','Fixing a rounding mismatch in a wide shot where the lips cannot really be seen.','Assuming any vowel substitution is safe, when swapping a rounded vowel for a flat one is obvious on screen.']::text[],ARRAY['Catching a close-up where the actor says a rounded ''o'' but the dub has a flat ''a''.','Rewriting a target line so a rounded vowel falls on the rounded mouth shape.','QC review of a dub for visible rounding clashes in hero shots.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13db4341-807c-5322-ab9c-0b0b1bfb692b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip-rounding mismatch'),'[^a-z0-9]','','g'));
