INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de04b9de-2d03-5a86-b138-3299e4b331a7','M&E editorial pass','The sound-editorial stage in which editors build the Music and Effects (M&E) track for localization — removing production dialogue, filling the exposed backgrounds and effects, and conforming the result to the final picture — so a clean, fully covered M&E is ready for the foreign-language dub mix.','An M&E editorial pass is the editing work that builds the music-and-effects track. Editors take out the original dialogue and fill any gaps left behind. The goal is a complete sound bed ready for dubbing.','It turns a finished mix into a dialogue-free, gap-free deliverable, so any language can be dubbed over the original music, effects, and backgrounds.','A sound editor works through the timeline removing dialogue, patching ambiences and foley that were tied to that dialogue, and checking sync against the locked picture.','M&E Deliverables',ARRAY['Music and Effects','M&E fill','Language-neutral vocal','Language-specific effort','Optional stem','Walla']::text[],ARRAY['Assuming the M&E is finished once dialogue is muted, without filling the backgrounds that were under it.','Editing the M&E against an outdated picture cut, so it drifts out of sync with the delivered program.','Leaving on-camera source dialogue in the M&E when it should have been handled as an optional element.']::text[],ARRAY['Preparing a fully-filled M&E for a series before its international dub.','Conforming an M&E to a re-cut master before delivery.','Handing off a checked M&E to the dub stage for a foreign-language mix.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de04b9de-2d03-5a86-b138-3299e4b331a7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E editorial pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de04b9de-2d03-5a86-b138-3299e4b331a7','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de04b9de-2d03-5a86-b138-3299e4b331a7' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b0ab269-fd10-599e-9bd2-65f2509bc37c','M&E fill','Replacement background, ambience, foley, and effects material added to a Music and Effects (M&E) track to cover the holes left when production dialogue is removed, so the effects bed plays continuously with no gaps where the original dialogue-recorded sounds used to be.','M&E fill is the extra background sound added to patch holes in the music-and-effects track. When the original talking is removed, the room tone and effects under it go too. Fill replaces them so nothing drops out.','It exists so a fully filled M&E sounds seamless, letting a dub play over continuous backgrounds instead of silent gaps wherever the original dialogue sat.','An editor lays in matching room tone, ambience, and foley beneath the removed dialogue, matching the texture and level of the surrounding scene.','M&E Deliverables',ARRAY['Music and Effects','M&E editorial pass','Room tone','Foley','Walla','Language-neutral vocal']::text[],ARRAY['Leaving unfilled gaps where dialogue was, so the background audibly drops out under each dubbed line.','Filling with ambience that does not match the level or texture of the surrounding scene.','Confusing fill, which covers holes, with added enhancement effects that only sweeten the mix.']::text[],ARRAY['Patching room tone under a removed line so the dub plays over steady ambience.','Recreating footsteps and cloth that were only on the production dialogue track.','QC listening for background drop-outs that reveal missing fill in an M&E.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b0ab269-fd10-599e-9bd2-65f2509bc37c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E fill'),'[^a-z0-9]','','g'));
