WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0b0ab269-fd10-599e-9bd2-65f2509bc37c' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '132c5e0f-7b99-5dd3-897a-c414848dfb66','M&E sweetener','An added, non-essential sound effect layered into a Music and Effects (M&E) track to reinforce or enhance an existing element — for example a low-end layer under an impact or an extra texture on an ambience — improving the effects bed beyond the sounds strictly required to cover the picture.','An M&E sweetener is an extra sound effect added to make the effects track richer. It reinforces a sound that is already there, like adding a deep boom under a crash. It enhances the mix rather than fixing a gap.','Sweeteners give the M&E more impact and polish, so the dubbed version sounds as full and cinematic as the original mix.','A sound editor layers a reinforcing effect — extra low end, a whoosh, or added texture — onto an existing hit or ambience while building the M&E.','M&E Deliverables',ARRAY['Music and Effects','M&E fill','M&E editorial pass','Foley','Room tone','Walla']::text[],ARRAY['Confusing a sweetener, which enhances, with fill, which covers a hole left by removed dialogue.','Adding sweeteners so loud they change the intent of the original mix.','Relying on sweeteners to disguise a poorly filled or out-of-sync M&E.']::text[],ARRAY['Layering a low-end sweetener under an explosion while building the M&E.','Adding a subtle texture to an ambience so the effects bed feels fuller.','Deciding whether an added effect belongs in the delivered M&E or only in the original mix.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='132c5e0f-7b99-5dd3-897a-c414848dfb66' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('M&E sweetener'),'[^a-z0-9]','','g'));
