INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '18e1b1ac-d3f8-53ad-b439-33c162754fd8','Mouth-flap matching','In dubbing pre-recorded animation, the practice of writing and performing target-language lines so they begin, end, and articulate in step with the character''s animated mouth movements (flaps), which are fixed by the original animation and cannot be altered.','Mouth-flap matching is used to dub cartoons and anime. The character''s mouth movements, called flaps, are already drawn and cannot change. The dubbing writers and actors fit the new lines to those flaps.','Because animated mouths are locked, matching the flaps is how a dub stays believable: the voice must start when the mouth opens and stop when it closes.','A dub script writer counts and times the character''s flaps, then crafts lines whose syllables and pauses land on those openings, and the actor performs to match.','Lip Sync',ARRAY['Isochrony','Labial synchrony','Mouth-open interval','Lip synchrony','Automated dialogue replacement','Linguistic expansion']::text[],ARRAY['Writing a line whose length ignores the flap count, so the voice runs on after the mouth stops.','Matching flaps so rigidly that the performance sounds stilted and unnatural.','Assuming animation sync is looser than live action, when locked flaps can be less forgiving than a real mouth.']::text[],ARRAY['Adapting an anime episode so English lines fit the drawn mouth flaps.','Timing a dub take in editorial with quarter-frame nudges to align to flaps.','Rewriting a line that overshoots the character''s last mouth flap.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='18e1b1ac-d3f8-53ad-b439-33c162754fd8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mouth-flap matching'),'[^a-z0-9]','','g'));
