INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b187cf94-162c-5928-bc08-b0852bf49418','Mouth-open interval','The span of time during which an on-screen character''s mouth is visibly open, defining the window into which a dubbed utterance must be fitted; isochrony requires the target line to begin and end within these openings and closings so speech is not heard while the mouth is shut.','The mouth-open interval is the stretch of time a character''s mouth is open on screen. The dubbed line has to fit inside that window. You should not hear talking while the mouth is closed.','It gives adapters and editors a concrete timing target, marking exactly where dubbed dialogue may play so audio and visible speech stay aligned.','An editor or adapter notes where each mouth opening starts and ends, then fits or trims the dubbed line to sit inside that interval.','Lip Sync',ARRAY['Isochrony','Labial synchrony','Mouth-flap matching','Lip synchrony','Linguistic condensation','Linguistic expansion']::text[],ARRAY['Letting dubbed dialogue start before the mouth opens or continue after it closes.','Filling the whole interval when the original had a mid-line pause the mouth showed.','Treating the interval as fixed for every language, ignoring that lines may need condensing or expanding to fit.']::text[],ARRAY['Fitting a target line between the frames where a character opens and closes the mouth.','Trimming a translation that overruns the end of a mouth-open interval.','Aligning a dub take so no speech is heard over a closed mouth.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b187cf94-162c-5928-bc08-b0852bf49418' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mouth-open interval'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b187cf94-162c-5928-bc08-b0852bf49418','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b187cf94-162c-5928-bc08-b0852bf49418' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0422535b-36f3-5500-84ee-835c4c875d5a','Music and Effects','A pre-mixed soundtrack containing all of a program''s music and sound effects — with the original dialogue removed and its underlying backgrounds filled — delivered as an international bed onto which localized dialogue is mixed to create a fully dubbed foreign-language version.','Music and Effects, or M&E, is the full soundtrack with the talking taken out. It keeps the music, sound effects, and background sounds. Studios use it to add dialogue in other languages.','The M&E exists so a film or show can be dubbed into any language without rebuilding the music and effects, giving every version the same sonic world as the original.','A distributor delivers the M&E to a localization vendor, whose mixer combines it with the newly recorded target-language dialogue to produce the dubbed master.','M&E Deliverables',ARRAY['M&E fill','M&E editorial pass','Language-neutral vocal','Language-specific effort','Optional stem','Walla']::text[],ARRAY['Delivering an M&E with dialogue backgrounds unfilled, so gaps appear under each dubbed line.','Assuming the M&E includes dialogue, when by definition the original dialogue is removed.','Forgetting to supply optional tracks for language-specific efforts and on-screen source vocals.']::text[],ARRAY['Delivering an M&E stem so a series can be dubbed in multiple territories.','A mixer combining the M&E with target-language dialogue for a dubbed master.','Checking an M&E delivery against streaming-partner technical specifications.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0422535b-36f3-5500-84ee-835c4c875d5a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Music and Effects'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
