INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dbad5aed-07a9-553a-bbad-43a871dff182','Nodding synchrony','A facet of kinesic synchrony in dubbing in which the target-language dialogue is timed and phrased so that stressed words and beats fall on a character''s visible head nods and affirmative movements. It keeps the rewritten line from contradicting, and ideally reinforces, the emphatic head gestures seen on screen.','Nodding synchrony means the dubbed words line up with a character''s head nods on screen. If the actor nods while stressing a word, the new line should stress a word there too. This keeps the voice and the picture agreeing.','It preserves the visual believability of the dub by keeping vocal emphasis aligned with head movement, so viewers do not sense a mismatch between what is said and what is seen.','During adaptation and recording, the writer and dubbing director place stressed syllables on shots where the character nods, and re-time lines so emphasis and nods coincide.','Synchronization',ARRAY['Kinesic synchrony','Isochrony','Phonetic synchronization','Performance synchrony','Nuclear-stress matching']::text[],ARRAY['Matching only the mouth movements and letting vocal emphasis drift away from the character''s visible nods.','Stressing a different word than the one the on-screen nod emphasizes, creating a seen mismatch.','Confusing kinesic cues like nods with pure lip sync, which concerns mouth shape rather than body movement.']::text[],ARRAY['Adapting a line where a character nods firmly while agreeing.','Re-timing an emphatic agreement so the stressed word lands on the visible nod.','Directing a dub take so the actor''s emphasis matches the character''s head movements.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dbad5aed-07a9-553a-bbad-43a871dff182' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nodding synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dbad5aed-07a9-553a-bbad-43a871dff182','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dbad5aed-07a9-553a-bbad-43a871dff182' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd7b0073b-4c55-5f3c-a3de-569dbd77ca77','Nuclear-stress matching','An adaptation and delivery technique in dubbing that places the nuclear stress — the main, most prominent pitch accent of the target-language intonation phrase — on the word carrying the source line''s focus, coinciding with the actor''s peak vocal and facial emphasis. It aligns the informational and emotional high point of the dubbed line with that of the original.','Every spoken phrase has one word that stands out the most. Nuclear-stress matching puts that strongest beat on the right word in the new language. It should land where the original actor pushed hardest, so the feeling matches.','It keeps the focus and emotional emphasis of the dubbed line where the original placed it, so meaning and feeling are not shifted onto the wrong word.','The adapter chooses target wording and word order so the key stressed word sits under the actor''s strongest facial and vocal push, and the dub actor delivers the peak there.','Prosody',ARRAY['Phrase-contour matching','Phonetic synchronization','Isochrony','Performance synchrony','Oral naturalness']::text[],ARRAY['Defaulting the strong stress to the last word regardless of where the source placed its focus.','Rewording the line so the emphasized word no longer aligns with the actor''s visible push.','Flattening delivery so no clear nuclear stress is heard, weakening the line''s focus.']::text[],ARRAY['Adapting a line where the source stresses a contrast word for emphasis.','Fixing a take where the dub actor stressed the wrong word.','Choosing target word order so the key word falls under the actor''s emphatic beat.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d7b0073b-4c55-5f3c-a3de-569dbd77ca77' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nuclear-stress matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd7b0073b-4c55-5f3c-a3de-569dbd77ca77','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d7b0073b-4c55-5f3c-a3de-569dbd77ca77' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05621e48-97f4-57df-8302-47e14b8d0c3c','Open-vowel correspondence','A phonetic-synchrony criterion in dubbing requiring that, at moments of clearly visible articulation such as close-ups, the target-language text place open vowels — produced with a wide, open mouth such as /a/ — where the on-screen actor''s mouth is open. It is one of the salient viseme constraints, alongside bilabial and rounded-vowel matching, used to make lip movement look convincing.','When someone opens their mouth wide, we expect a wide ''ah'' sound. Open-vowel correspondence picks new words with a wide vowel at those moments. It makes the mouth and the voice look like they belong together.','It sustains the illusion of lip sync by aligning wide-open mouth shapes in the picture with wide-open vowel sounds in the dub, especially where the mouth is clearly seen.','In close-ups the adapter selects synonyms or rephrasings whose stressed vowels are open where the actor''s mouth opens, avoiding closed or rounded sounds at those frames.','Lip Sync',ARRAY['Phonetic synchronization','Isochrony','Kinesic synchrony','Nuclear-stress matching','Phrase-duration matching']::text[],ARRAY['Ignoring vowel shape in close-ups and matching only overall line length.','Placing a closed or rounded vowel where the actor''s mouth is clearly wide open.','Assuming open-vowel matching matters in long shots, where mouth detail is not visible.']::text[],ARRAY['Adapting a shouted line in extreme close-up.','Choosing between synonyms when one ends on an open vowel matching the visible mouth.','Reworking a line so a wide-open mouth frame carries an open vowel.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05621e48-97f4-57df-8302-47e14b8d0c3c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Open-vowel correspondence'),'[^a-z0-9]','','g'));
