INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14fda5cb-fd15-5145-afb0-0b7cc97bad72','Optional dialogue','In music-and-effects (M&E) delivery, dialogue and dialogue-adjacent vocal material supplied on separate optional tracks so a localizing or dubbing team can choose whether to retain or replace it. Typical contents include foreign- or invented-language lines, on-screen sung vocals, group walla, and non-verbal mouth sounds occurring near dialogue.','Optional dialogue is speech given on its own extra track in delivery. The dubbing team can keep it or swap it, as needed. It often holds things like crowd chatter, singing, or foreign lines.','It gives the localization team flexibility to keep material that should stay in the original voice or drop it and re-record, without baking that choice into the main M&E.','A re-recording mixer isolates such lines onto optional tracks in the M&E package, and the dubbing house then decides per line whether to use the original or dub it.','Deliverables',ARRAY['Partially filled M&E','Music and effects track','Walla','Vocal efforts','Fully-filled M&E']::text[],ARRAY['Baking optional lines into the main M&E, removing the localizer''s choice to keep or replace them.','Forgetting to supply on-screen singing or foreign lines as options, forcing guesswork later.','Confusing optional dialogue with the primary dialogue stem that is always removed from M&E.']::text[],ARRAY['Delivering crowd walla and background chatter as optional tracks.','Providing an on-screen character''s song as an option to keep in the original voice.','A dub house deciding whether to retain a foreign-language line or re-voice it.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14fda5cb-fd15-5145-afb0-0b7cc97bad72' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optional dialogue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '14fda5cb-fd15-5145-afb0-0b7cc97bad72','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='14fda5cb-fd15-5145-afb0-0b7cc97bad72' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13af31b2-0722-5ccd-890b-80075ca30b5d','Oral naturalness','The dubbing quality standard by which translated dialogue convincingly imitates the spontaneous spoken register of the target language while remaining fully scripted — an instance of ''prefabricated orality.'' It is achieved through colloquial lexis, natural syntax, discourse markers, and believable prosody, so the dialogue sounds credible rather than written or theatrical.','Oral naturalness means dubbed lines sound like real speech, not like a book read aloud. Writers add everyday words and a natural rhythm. The goal is dialogue that feels spoken, even though it is fully scripted.','It sustains the audience''s belief in the characters by making translated dialogue sound like genuine conversation, which is central to a dub''s credibility.','Adapters replace stiff literal renderings with colloquial phrasing, contractions, and discourse markers, and directors coach delivery so lines sound spoken rather than read.','Dialogue Adaptation',ARRAY['Prefabricated orality','Performability pass','Pragmatic calque','Performance synchrony','Phrase-contour matching']::text[],ARRAY['Translating too literally, producing correct but stilted lines that sound written.','Over-standardizing speech and stripping out the discourse markers that signal real talk.','Adding so much slang that it dates quickly or breaks character consistency.']::text[],ARRAY['Adapting a casual argument so it sounds like everyday speech.','Replacing a literal greeting with an idiomatic one that fits the target language.','Reviewing a dub script for lines that read naturally when spoken aloud.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13af31b2-0722-5ccd-890b-80075ca30b5d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Oral naturalness'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '13af31b2-0722-5ccd-890b-80075ca30b5d','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='13af31b2-0722-5ccd-890b-80075ca30b5d' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '77537029-5d64-5cc8-8d7d-a27833a152e4','Partially filled M&E','A music-and-effects (M&E) track that carries the original music and sound effects with the primary dialogue removed but does not re-create every effect that was married to or masked by that dialogue, leaving gaps where dialogue-linked foley and sync effects once sat. It contrasts with a fully-filled M&E, in which all such gaps are rebuilt so the track stands alone.','A partially filled music-and-effects track has the music and effects but no main dialogue. Some sounds that sat under the speech are missing, leaving holes. A fully filled version rebuilds those missing sounds.','It provides a usable localization stem while saving the cost of rebuilding hidden effects, on the understanding that the dub mix or added foley will cover the remaining gaps.','A dubbing mixer receiving a partially filled M&E must add missing footsteps, cloth, and prop sounds that lived under the original dialogue before the foreign version will sound complete.','Deliverables',ARRAY['Fully-filled M&E','Music and effects track','Optional dialogue','Foley','Dialogue stem']::text[],ARRAY['Assuming a partially filled M&E is complete and mixing over the audible gaps.','Confusing partially filled with fully-filled M&E, then under-budgeting the foley needed to finish the dub.','Leaving dialogue-linked effects missing, so the dubbed scene loses footsteps or prop sounds.']::text[],ARRAY['Receiving a low-budget M&E that lacks foley under removed dialogue.','Quoting extra foley work after inspecting an M&E for unfilled gaps.','Deciding whether a delivered M&E is fully or partially filled before dubbing begins.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='77537029-5d64-5cc8-8d7d-a27833a152e4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Partially filled M&E'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '77537029-5d64-5cc8-8d7d-a27833a152e4','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='77537029-5d64-5cc8-8d7d-a27833a152e4' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c08229e5-4575-54ff-8539-ba72ae7e8869','Pause redistribution','An isochrony technique in which the pauses (silences) of a translated line are re-placed so the speech and silence segments align with the on-screen actor''s mouth activity and rests, rather than preserving the source''s pause positions verbatim. It lets the adapter fit target wording of a different length while keeping visible starts, stops, and breaths in sync.','Spoken lines have gaps of silence between chunks of speech. Pause redistribution moves those gaps so the new words still line up with the mouth. It helps a longer or shorter translation fit the picture.','It preserves the appearance of synchrony when the target line''s length differs from the source, by shifting silences to match when the mouth moves and rests.','The adapter breaks the target line into segments and positions pauses so speech begins and ends where the actor''s lips do, adjusting for added or dropped syllables.','Synchronization',ARRAY['Pause synchrony','Isochrony','Phrase-duration matching','Phonetic synchronization','Phrase-contour matching']::text[],ARRAY['Keeping the source''s pause positions when the translation has a very different length.','Splitting a line at an unnatural point just to place a pause under a mouth rest.','Ignoring visible breaths, so the dub speaks through a frame where the actor pauses.']::text[],ARRAY['Fitting a longer translated sentence into the same on-screen speaking window.','Re-timing a line so a silence falls where the actor closes their mouth.','Adjusting pauses around a visible breath in a close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c08229e5-4575-54ff-8539-ba72ae7e8869' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pause redistribution'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c08229e5-4575-54ff-8539-ba72ae7e8869','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c08229e5-4575-54ff-8539-ba72ae7e8869' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e05c789-dd31-56bb-9a8e-d368fbf0b4c8','Pause synchrony','A component of isochrony requiring that the silences within and between dubbed utterances coincide with the pauses of the on-screen actor, so the character appears to stop and start speaking at the same moments as in the original. It concerns the placement of rests rather than the total utterance length.','Pause synchrony means the quiet moments in the dub match the actor''s pauses. When the character stops talking on screen, the dubbed voice stops too. It keeps the silences lined up with the picture.','It reinforces the illusion that the character is really speaking the target language by matching when they fall silent, not just how long they speak.','The adapter and mixer align each rest in the dubbed line with the actor''s visible pause, so the voice never runs on through a closed mouth.','Synchronization',ARRAY['Isochrony','Pause redistribution','Phrase-duration matching','Phonetic synchronization','Phrase-contour matching']::text[],ARRAY['Matching only total line length while ignoring where the actor pauses.','Letting the dub voice continue through a frame where the character has clearly stopped.','Treating pauses as unimportant filler rather than as sync points.']::text[],ARRAY['Aligning a two-part line with the actor''s mid-sentence breath.','Checking that the dub falls silent when the character''s mouth closes.','Timing a hesitant delivery so pauses match the original performance.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e05c789-dd31-56bb-9a8e-d368fbf0b4c8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pause synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e05c789-dd31-56bb-9a8e-d368fbf0b4c8','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e05c789-dd31-56bb-9a8e-d368fbf0b4c8' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4b00f95e-787c-58dc-9625-b9b18449f16a','Performability pass','A dedicated revision stage in dubbing adaptation in which the translated and synced script is checked and refined for ease and naturalness of oral delivery — its performability or speakability — flagging tongue-twisters, awkward stress, unpronounceable clusters, and breath-impossible lines before recording. It ensures the voice talent can perform each line convincingly.','A performability pass is a check that every line is easy to say out loud. Editors catch tongue-twisters and lines with no room to breathe. It makes sure actors can perform the script naturally.','It prevents recording delays and stilted takes by fixing hard-to-speak lines while they can still be reworded, protecting both schedule and performance quality.','The adapter or dubbing director reads lines aloud, marks any that are awkward or breathless, and rewrites them so they flow before the session.','Dialogue Adaptation',ARRAY['Oral naturalness','Isochrony','Performance synchrony','Pause synchrony','Nuclear-stress matching']::text[],ARRAY['Skipping the read-aloud check, so tongue-twisters surface only during costly recording.','Writing lines with no breathing room, forcing the actor to rush.','Prioritizing literal accuracy over whether a line can be spoken smoothly.']::text[],ARRAY['Reading a dub script aloud to catch unpronounceable phrasings.','Reworking a breathless run-on line before a recording session.','Smoothing consonant clusters that trip the voice actor.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4b00f95e-787c-58dc-9625-b9b18449f16a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Performability pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4b00f95e-787c-58dc-9625-b9b18449f16a','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4b00f95e-787c-58dc-9625-b9b18449f16a' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7ddf5fb5-463c-5b0c-91cd-d79146085efb','Performance synchrony','The alignment of the dub actor''s vocal performance — emotion, energy, intonation, and dramatic intent — with the on-screen actor''s performance, so the delivered feeling matches the visible acting. It reaches beyond timing and mouth shape to the expressive quality of the reading.','Performance synchrony means the dub actor''s feeling matches the actor on screen. If the character sounds angry and tense, the dubbed voice does too. It lines up the acting, not just the timing.','It keeps the emotional truth of the scene intact across languages, so the dubbed voice conveys the same intent the audience sees in the actor''s face and body.','The dubbing director coaches the voice actor to match the original''s emotional pitch, pacing, and emphasis while staying in sync with the picture.','Synchronization',ARRAY['Kinesic synchrony','Nuclear-stress matching','Oral naturalness','Nodding synchrony','Isochrony']::text[],ARRAY['Hitting the timing and lip sync but delivering the line with the wrong emotion.','Under-playing an intense moment because the focus was only on fitting the words.','Ignoring the on-screen actor''s energy and reading lines flatly.']::text[],ARRAY['Directing a dub actor to match an on-screen character''s rising anger.','Re-recording a take that synced well but felt emotionally off.','Matching the energy of a shouted line seen in close-up.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7ddf5fb5-463c-5b0c-91cd-d79146085efb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Performance synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7ddf5fb5-463c-5b0c-91cd-d79146085efb','39203cec-660c-4a27-972c-21f7a63623b9',true
