INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '01c9f18f-39de-516e-9ee1-01a9ae8cfca7','Phonetic synchronization','Also called lip sync, the synchrony that matches the dubbed dialogue to the articulatory movements of the on-screen actor''s mouth, especially the visible open vowels, bilabial consonants (/p, b, m/), and labiodental and rounded sounds seen in close-ups. It is one of the three classic dubbing synchronies, alongside isochrony and kinesic synchrony.','Phonetic synchronization, or lip sync, matches the dubbed sounds to the mouth on screen. Words with lips pressed together are placed where the actor closes their lips. It makes the speech look real.','It creates the core illusion that the character is really speaking the target language, which is most demanding in close-ups where mouth shapes are clearly visible.','In close-ups the adapter chooses target words whose visible sounds — open vowels and lip closures — fall where the actor''s mouth makes those shapes.','Lip Sync',ARRAY['Isochrony','Kinesic synchrony','Open-vowel correspondence','Nuclear-stress matching','Pause synchrony']::text[],ARRAY['Applying strict lip sync to long shots where mouth detail cannot be seen.','Placing an open vowel where the actor''s lips are closed, breaking the illusion.','Sacrificing meaning entirely to force a lip match when a looser rendering would read better.']::text[],ARRAY['Adapting a close-up line so lip closures fall on /p/, /b/, or /m/.','Choosing between synonyms based on which matches the visible mouth shapes.','Reviewing a dub for lip-sync errors in extreme close-ups.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='01c9f18f-39de-516e-9ee1-01a9ae8cfca7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phonetic synchronization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '01c9f18f-39de-516e-9ee1-01a9ae8cfca7','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='01c9f18f-39de-516e-9ee1-01a9ae8cfca7' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c579c127-0943-5a72-a8d4-79f618c16c31','Phrase-contour matching','A prosodic technique in dubbing that shapes the target phrase''s intonation contour — its pattern of rising and falling pitch — to track that of the source utterance, so questions, emphasis, and continuation cues rise and fall at the same points. It aligns the melodic shape of the line rather than only its timing or stress.','Every phrase has a tune of rising and falling pitch. Phrase-contour matching copies that tune in the new language. A question still rises and a statement still falls where the original did.','It preserves the meaning carried by intonation — such as questioning, surprise, or emphasis — so the dubbed line reads the same way the original was spoken.','The adapter and dub actor shape the pitch so rises and falls land where the source''s did, matching the emotional and grammatical cues of the phrase.','Prosody',ARRAY['Nuclear-stress matching','Isochrony','Phrase-duration matching','Performance synchrony','Oral naturalness']::text[],ARRAY['Matching words and timing but delivering a flat pitch that loses the original''s melody.','Ending a question on a fall because the target wording was not shaped to rise.','Copying source pitch so literally that it sounds unnatural in the target language.']::text[],ARRAY['Keeping a rising question contour in the dubbed line.','Matching an incredulous pitch swing seen on the actor''s face.','Shaping emphasis so the melodic peak matches the original.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c579c127-0943-5a72-a8d4-79f618c16c31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrase-contour matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c579c127-0943-5a72-a8d4-79f618c16c31','39203cec-660c-4a27-972c-21f7a63623b9',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c579c127-0943-5a72-a8d4-79f618c16c31' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cfcb3a76-9515-5020-baf2-134c33eacf94','Phrase-duration matching','An isochrony technique that adjusts the target phrasing so each phrase spans the same on-screen time as the corresponding source phrase, matching where speech starts and ends. It works at the phrase level rather than the whole utterance, so segment boundaries stay aligned with the picture.','Phrase-duration matching makes each chunk of the new line last as long as the original chunk. The words start and stop where the actor''s did. This keeps the dub lined up piece by piece.','It maintains synchrony within a line by fitting each phrase to its on-screen window, preventing the drift that would build up if only the total length were matched.','The adapter counts syllables and times each phrase so it fills the same span as the source, adding or trimming words to fit each segment.','Synchronization',ARRAY['Isochrony','Pause synchrony','Pause redistribution','Phrase-contour matching','Phonetic synchronization','Segment-duration matching (near-synonymous: this fits each phrase to the source''s on-screen duration, while segment-duration matching applies the same fit at the more general segment/utterance level)']::text[],ARRAY['Matching only the total line length while individual phrases drift out of sync.','Cramming too many syllables into a short phrase window, forcing a rushed delivery.','Padding a short translation with filler that does not fit the original phrasing.']::text[],ARRAY['Fitting each clause of a multi-part line to its on-screen span.','Trimming a wordy translation so a phrase ends when the mouth stops.','Balancing syllable counts across phrases to hold sync.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cfcb3a76-9515-5020-baf2-134c33eacf94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrase-duration matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
