INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eaf65247-52c7-54d6-9642-4f05348066bc','Pragmatic calque','A translation procedure in which a source-language pragmatic routine or speech formula — such as a greeting, apology, or politeness marker — is transferred into the target language by literal, structure-for-structure rendering rather than by the target''s own idiomatic equivalent. In dubbing it is a common source of ''dubbese,'' producing lines that are grammatically possible but pragmatically foreign.','A pragmatic calque copies a set phrase word-for-word from one language to another. The result may be correct grammar but sound foreign. One example is translating a polite phrase literally instead of using the local one.','Naming it as a procedure lets adapters recognize and usually avoid it, because it flags where a literal rendering of a social formula breaks the target language''s real usage.','An adapter spots a literally translated formula, such as a calqued greeting, and replaces it with the idiomatic target expression to restore naturalness.','Translation Technique',ARRAY['Calque','Oral naturalness','Dubbese','Pragmatic borrowing','Performability pass']::text[],ARRAY['Rendering a greeting or apology literally instead of using the target language''s usual formula.','Assuming a phrase that is grammatical is therefore idiomatic.','Keeping a calqued formula because it matches lip sync, at the cost of naturalness.']::text[],ARRAY['Catching a literally translated farewell that sounds foreign.','Replacing a calqued politeness formula with the idiomatic target version.','Reviewing a dub script for pragmatic calques that break naturalness.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eaf65247-52c7-54d6-9642-4f05348066bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pragmatic calque'),'[^a-z0-9]','','g'));
