INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a866ec63-8335-5a13-b202-0904f25e7b0d','Pragmatic stress','The prosodic prominence a speaker places on a particular word or syllable to signal pragmatic meaning — focus, contrast, emphasis or new information — beyond the default lexical or rhythmic stress of the utterance. In dubbing adaptation the emphasis must be relocated onto the target-language word that carries the same communicative focus.','This is the extra push a speaker puts on a word to make a point. It can show a contrast or mark what matters most. In dubbing, the new line must stress the same idea.','It marks which element of an utterance is most communicatively important, so listeners parse focus, contrast and intent correctly. Preserving it in the target line keeps the character''s meaning and attitude intact.','A dialogue writer rewrites a dubbed line so the emphasized target word falls where the original placed its focus, matching the actor''s vocal peak and on-screen delivery.','Dialogue Adaptation',ARRAY['Prosodic transfer','Prosodic adaptation','Prosodic alignment','Isochrony','Prefabricated orality','Speakability']::text[],ARRAY['Placing the emphasis on the grammatically equivalent word instead of the word that actually carries the focus in the target language.','Flattening the line so no word is stressed, losing the contrast or intent the original conveyed.','Letting the stressed word fall out of sync with the actor''s visible vocal peak or gesture.']::text[],ARRAY['Adapting a line where the joke depends on which word is emphasized.','Rewriting a contrastive reply such as ''I didn''t say she stole it'' where stress changes the meaning.','Coaching a voice actor in the booth to hit the emphasized word on the correct beat.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a866ec63-8335-5a13-b202-0904f25e7b0d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pragmatic stress'),'[^a-z0-9]','','g'));
