INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e8bcf5c1-04b2-509d-8682-38383239a203','Pre-adaptation','The preparatory stage in the dubbing pipeline in which a raw or literal translation is worked over to ready it for full synchronization-oriented adaptation, often flagging sync constraints, register and length before the dialogue writer performs the final fitting. It reflects workflows where translation and adaptation are split across two professionals.','This is early work done on a rough translation before the real fitting begins. It gets the script ready so the writer can match it to the mouth and the timing.','It bridges a source-faithful translation and a performable dub script, so the adapter can focus on lip sync, isochrony and naturalness. It exists because raw translations rarely fit the picture as written.','A translator or first-pass adapter delivers a marked-up script noting close-ups, line lengths and tricky idioms, which the dialogue writer then shapes into synchronized takes.','Dialogue Adaptation',ARRAY['Dialogue adaptation','Speakability','Isochrony','Segment-duration matching','Prefabricated orality']::text[],ARRAY['Treating pre-adaptation as the finished dub script rather than an intermediate stage still needing full synchronization.','Over-literal wording that ignores mouth movements and duration, forcing the adapter to rewrite from scratch.','Failing to flag close-ups and constraints, so the adapter loses information the translator already knew.']::text[],ARRAY['Handing a translated episode to a dialogue writer who does not speak the source language.','Preparing a literal script with timing notes for a fast-turnaround streaming dub.','Marking idioms and cultural references that will need reworking during adaptation.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e8bcf5c1-04b2-509d-8682-38383239a203' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-adaptation'),'[^a-z0-9]','','g'));
