INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7f844184-f07d-553e-bee7-a62d8ae31432','Prefabricated orality','The characteristic mode of audiovisual dialogue that is composed in advance yet crafted to come across as unrehearsed, everyday speech — scripted speech engineered to sound spontaneous through selected markers of orality across phonetic, morphological, syntactic and lexical levels. In dubbing, translators must recreate this false spontaneity in the target language under sync constraints.','Movie talk sounds natural, but it is all scripted first. This planned speech that is written to sound spontaneous is called prefabricated orality. Dubbing must recreate that natural sound in a new language.','It lets fictional conversation feel authentic and immediate while staying comprehensible and controlled, unlike real spontaneous speech. Naming it helps writers judge how many oral markers to keep so the dub sounds believable.','A dialogue writer adds discourse markers, contractions and casual rhythms to a dubbed line so it reads as everyday talk rather than stiff translated prose.','Dialogue Adaptation',ARRAY['Dubbese','Dialogue adaptation','Speakability','Prosodic adaptation','Naturalness','Register']::text[],ARRAY['Assuming dubbed dialogue should copy the messiness of real conversation, when it is deliberately constructed and cleaner.','Producing stilted, over-formal lines that read as translation rather than natural speech.','Overloading a line with slang and fillers so it stops being comprehensible or performable.']::text[],ARRAY['Adapting a sitcom so the banter sounds like real friends talking in the target language.','Deciding how many hesitations and discourse markers to keep in a dramatic scene.','Comparing a dub to a domestic production to judge perceived naturalness.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7f844184-f07d-553e-bee7-a62d8ae31432' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prefabricated orality'),'[^a-z0-9]','','g'));
