WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7f844184-f07d-553e-bee7-a62d8ae31432' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e56b0061-5430-59c3-bcb5-b36915a83dbf','Prosodic adaptation','The reshaping of a translated line''s prosody — its rhythm, stress pattern, intonation and phrasing — so the dubbed utterance conforms to target-language norms while fitting the timing, delivery and emotional contour visible on screen. It is a subset of dialogue adaptation focused on the suprasegmental, musical layer of speech.','Prosody is the music of speech: its rhythm, stress, and pitch. Prosodic adaptation reshapes that music so the new line sounds right and fits the scene.','It ensures the dubbed line not only says the right words but carries the right melody and emphasis, so it sounds native and matches the character''s mood. Without it a line can be accurate yet sound wrong.','A dialogue writer rewords a line so its stress and phrasing follow natural target-language rhythm while still landing on the actor''s beats and pauses.','Dialogue Adaptation',ARRAY['Prosodic transfer','Prosodic alignment','Prosodic resegmentation','Pragmatic stress','Isochrony','Prefabricated orality']::text[],ARRAY['Copying the source rhythm and intonation directly, producing a line that sounds foreign in the target language.','Fixing word choice but ignoring where stresses and pauses fall, so the delivery feels off.','Letting reshaped prosody drift out of sync with the visible timing and emotion on screen.']::text[],ARRAY['Adapting an emotional monologue so its rises and falls sound natural in the dub.','Reworking a line whose translated rhythm clashes with the actor''s cadence.','Matching a shouted or whispered delivery to appropriate target-language phrasing.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e56b0061-5430-59c3-bcb5-b36915a83dbf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic adaptation'),'[^a-z0-9]','','g'));
