WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e56b0061-5430-59c3-bcb5-b36915a83dbf' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '85548253-1613-5e97-a407-362f41fd4caa','Prosodic alignment','The temporal coordination of a dubbed line''s prosodic features — stressed syllables, pitch peaks, pauses and phrase boundaries — with the visible delivery of the on-screen actor, so vocal prominences coincide with the corresponding facial movements, gestures and beats. It links prosody to isochrony and kinesic synchrony.','This lines up the ups and downs of the new speech with what we see. Stress and pauses should land when the face and gestures on screen expect them.','It keeps the dubbed voice believable by making its emphases and pauses hit at the moments the picture leads viewers to expect. Misalignment makes speech feel detached from the body on screen.','A voice director cues the actor so a stressed word or pause lands exactly on a head nod, gesture or mouth movement seen in the shot.','Sync & Timing',ARRAY['Isochrony','Kinesic synchrony','Prosodic transfer','Pragmatic stress','Segment-duration matching','Silence accommodation']::text[],ARRAY['Getting the words to fit the duration but letting stresses and pauses fall on the wrong frames.','Ignoring gestures and head movements that the vocal emphasis should coincide with.','Treating alignment as lip shape only, forgetting rhythm and pause placement.']::text[],ARRAY['Timing a stressed word to land on an actor''s visible gesture in a close-up.','Placing a dubbed pause exactly where the character pauses on screen.','Directing a booth take to hit emotional peaks on the same beats as the picture.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='85548253-1613-5e97-a407-362f41fd4caa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic alignment'),'[^a-z0-9]','','g'));
