WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='85548253-1613-5e97-a407-362f41fd4caa' AND gt.achievement_id='39203cec-660c-4a27-972c-21f7a63623b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00c8e063-38e7-5302-9263-0cfd157d2542','Prosodic resegmentation','The re-division of an utterance into different prosodic units — intonation groups, breath groups or phrases — than those of the source, so the dubbed line''s chunking supports natural target-language delivery while fitting on-screen pauses and timing. Boundaries are moved, merged or split rather than kept one-to-one.','This breaks the line into different chunks than the original. New pause and phrase points help the dubbed speech fit the timing and sound natural.','It lets the adapter regroup words so the dub breathes and phrases naturally in the target language while still respecting where the picture allows pauses. Keeping source segmentation often forces awkward phrasing.','A dialogue writer shifts a phrase boundary so a long source clause becomes two shorter target phrases that fit the actor''s pauses and mouth movements.','Sync & Timing',ARRAY['Segmentation mismatch','Segment-duration matching','Isochrony','Silence accommodation','Prosodic adaptation','Prosodic alignment']::text[],ARRAY['Preserving the source phrase boundaries even when they force unnatural target-language phrasing.','Resegmenting so drastically that pauses no longer match the visible on-screen delivery.','Breaking a line where the target language does not allow a natural pause.']::text[],ARRAY['Splitting one long source sentence into two dubbed phrases to fit the breaths on screen.','Merging two short source utterances that the target language phrases as one.','Rechunking a line so its pauses fall on the character''s visible pauses.']::text[],'39203cec-660c-4a27-972c-21f7a63623b9'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00c8e063-38e7-5302-9263-0cfd157d2542' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosodic resegmentation'),'[^a-z0-9]','','g'));
